                id: 'memo',
                name: 'Memo',
                html: `<div style="font-family: Georgia, 'Times New Roman', serif; line-height: 1.6;">
  <div style="font-size:12px; letter-spacing:3px; text-transform:uppercase; border-bottom:2px solid #111; padding-bottom:8px; margin-bottom:16px;">Memorandum</div>
  <table style="width:100%; border-collapse:collapse; margin-bottom:18px; font-size:14px;">
    <tr><td style="width:78px; font-weight:700;">TO</td><td>{{to}}</td></tr>
    <tr><td style="font-weight:700;">FROM</td><td>{{from}}</td></tr>
    <tr><td style="font-weight:700;">DATE</td><td>{{date}}</td></tr>
    <tr><td style="font-weight:700;">RE</td><td><strong>{{subject}}</strong></td></tr>
  </table>
  <div style="white-space:pre-wrap;">{{body}}</div>
</div>`,
                sample: { to: 'Recipient', from: 'Sender', date: 'DATE', subject: 'Subject', body: 'The memo goes here.' }
            }
        ];
    }

    /**
     * One surface, two cases. A card that carries {{slots}} is the template and is shown as
     * itself. Any other card is material to pour into a template, and the pouring is the
     * model's job because only it can decide that "MSB26006196" is the case number.
     */
    openTemplate(cardId) {
        const card = this.cards.find(c => c.id === cardId);
        const text = card ? String(card.r || card.q || '') : '';
        this.templateSourceId = cardId || null;
        this.templateValues = {};
        this.templateFromCard = /\{\{\s*\w+\s*\}\}/.test(text);
        this.templateCardText = text;

        const pick = document.getElementById('templatePick');
        pick.innerHTML = '';
        this.templates.forEach(t => {
            const option = document.createElement('option');
            option.value = t.id;
            option.textContent = t.name;
            pick.appendChild(option);
        });
        if (this.templateFromCard) {
            const own = document.createElement('option');
            own.value = 'card';
            own.textContent = 'This card, as a template';
            pick.appendChild(own);
        }
        pick.value = 'letter';
        this.pickTemplate('letter');
        this.openModal('templateModal');
    }

    pickTemplate(key) {
        const pick = document.getElementById('templatePick');
        if (pick) pick.value = key;
        const fill = document.getElementById('templateFillBtn');
        const hint = document.getElementById('templateHint');
        if (key === 'card') {
            this.template = {
                id: 'card', name: 'This card', html: this.templateCardText,
                slots: [...this.templateCardText.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map(m => ({ key: m[1], sample: '' })),
                sample: {}
            };
            if (fill) fill.hidden = true;
            if (hint) { hint.hidden = false; hint.textContent = 'This card is the template. Nothing is filled in; it prints as it stands.'; }
        } else {
            this.template = this.templates.find(t => t.id === key) || this.templates[0];
            // The keys to fill are the ones the template actually has a placeholder for.
            this.template.slots = [...this.template.html.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map(m => ({ key: m[1] }));
            if (fill) fill.hidden = !this.templateSourceId || this.templateFromCard;
            if (hint) {
                hint.hidden = this.templateValues && Object.keys(this.templateValues).length > 0;
                hint.textContent = 'Placeholders until a card is poured in.';
            }
        }
        this.renderTemplatePreview();
    }

    renderTemplatePreview() {
        const paper = document.getElementById('templatePaper');
        if (!paper || !this.template) return;
        const fill = this.templateValues || {};
        const escape = (value) => String(value).replace(/[&<>]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]));
        paper.innerHTML = this.template.html.replace(/\{\{\s*(\w+)\s*\}\}/g, (whole, key) => {
            if (fill[key] !== undefined && String(fill[key]).trim() !== '') return escape(fill[key]);
            const sample = (this.template.sample || {})[key];
            if (sample !== undefined && sample !== '') return `<span class="slot-empty">${escape(sample)}</span>`;
            return '<span class="slot-empty">&#8212;</span>';
        });
    }

    /** Only facts in the card. A document that invents facts is worse than a blank slot. */
    async fillTemplateFromCard() {
        const card = this.cards.find(c => c.id === this.templateSourceId);
        const hint = document.getElementById('templateHint');
        if (!this.template) return;
        if (!card) {
            if (hint) { hint.hidden = false; hint.textContent = 'That card is no longer here, so there is nothing to pour in.'; }
            return;
        }
        const source = String(card.r || card.q || '');
        const keys = (this.template.slots || []).map(slot => slot.key);
        if (hint) { hint.hidden = false; hint.textContent = 'Filling from the card\u2026'; }

        const prompt = `Answer with JSON only. No prose, no code fence.
Keys: ${keys.join(', ')}
Rules: use only facts present in the source; if a fact is absent leave the value as an empty string; "body" may be rewritten as the same information in the template's register but must not add facts, names, numbers or dates.
Source:
${source.slice(0, 6000)}`;

        try {
            const answer = await this.streamChat({ messages: [{ role: 'user', content: prompt }], preset: NO_PRESET_KEY }, () => {});
            const json = JSON.parse((answer.match(/\{[\s\S]*\}/) || ['{}'])[0]);
            this.templateValues = json && typeof json === 'object' ? json : {};
            this.renderTemplatePreview();
            if (hint) { hint.hidden = false; hint.textContent = 'Filled from the card. Check every line before it prints.'; }
        } catch (err) {
            if (hint) { hint.hidden = false; hint.textContent = `Could not read the card as facts: ${err.message}`; }
        }
    }

    printTemplate() {
        const paper = document.getElementById('templatePaper');
        if (!paper) return;
        const name = String((this.template && this.template.name) || 'template').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
        if (typeof window.html2pdf !== 'function') {
            window.print();
            return;
        }
        window.html2pdf()
            .set({
                margin: 0,
                filename: `${name}.pdf`,
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { scale: 2, backgroundColor: '#ffffff', useCORS: true },
                jsPDF: { unit: 'pt', format: 'a4' }
            })
            .from(paper)
            .save();
    }

    /**
     * The screen's small icons move too. Each one keeps its own parked position, so an
     * arrangement survives a reload the way the bar's pin does.
     */
    initFloatingIcons() {
        this.applyFabPositions();
        document.querySelectorAll('.fab[data-fab]').forEach((btn) => this.makeFabDraggable(btn));
        window.addEventListener('resize', () => this.applyFabPositions());
    }

    applyFabPositions() {
        const parked = this.settings.fabs || {};
        document.querySelectorAll('.fab[data-fab]').forEach((btn) => {
            const pos = parked[btn.id];
            if (pos) this.parkFab(btn, pos.x, pos.y);
        });
    }

    parkFab(btn, x, y) {
        const box = btn.getBoundingClientRect();
        const w = box.width || 36;
        const h = box.height || 36;
        btn.style.position = 'fixed';
        btn.style.left = Math.round(Math.min(Math.max(8, x), window.innerWidth - w - 8)) + 'px';
        btn.style.top = Math.round(Math.min(Math.max(8, y), window.innerHeight - h - 8)) + 'px';
        btn.style.right = 'auto';
        btn.style.bottom = 'auto';
        btn.classList.add('parked');
    }

    makeFabDraggable(btn) {
        let from = null;
        let box = null;
        let moved = false;
        btn.addEventListener('pointerdown', (e) => {
            from = { x: e.clientX, y: e.clientY };
            box = btn.getBoundingClientRect();
            moved = false;
            if (e.pointerId !== undefined && btn.setPointerCapture) {
                try { btn.setPointerCapture(e.pointerId); } catch (err) { /* not capturable */ }
            }
        });
        btn.addEventListener('pointermove', (e) => {
            if (!from) return;
            const dx = e.clientX - from.x;
            const dy = e.clientY - from.y;
            if (!moved && Math.hypot(dx, dy) < 6) return;
            moved = true;
            btn.classList.add('dragging');
            this.parkFab(btn, box.left + dx, box.top + dy);
        });
        btn.addEventListener('pointerup', () => {
            if (!from) return;
            from = null;
            btn.classList.remove('dragging');
            if (!moved) return;
            const at = btn.getBoundingClientRect();
            this.settings.fabs = { ...(this.settings.fabs || {}), [btn.id]: { x: Math.round(at.left), y: Math.round(at.top) } };
            this.saveState();
            // The drag leaves a click behind; it is not a press on the icon.
            btn.addEventListener('click', (ev) => { ev.stopPropagation(); ev.preventDefault(); }, { capture: true, once: true });
        });
    }

    loadThemeHistory() {
        try {
            const list = JSON.parse(localStorage.getItem(THEME_HISTORY_KEY) || '[]');
            return Array.isArray(list) ? list.filter(t => t && t.name) : [];
        } catch { return []; }
    }

    /** Every palette the Stylist makes is worth keeping; one per name, newest first. */
    rememberTheme(theme) {
        if (!theme || !theme.name) return;
        try {
            const rest = this.loadThemeHistory().filter(t => t.name.toLowerCase() !== theme.name.toLowerCase());
            rest.unshift({
                name: theme.name, primary: theme.primary, bg: theme.bg, cardBg: theme.cardBg,
                text: theme.text, border: theme.border, mode: theme.mode,
                variants: theme.variants, at: Date.now()
            });
            localStorage.setItem(THEME_HISTORY_KEY, JSON.stringify(rest.slice(0, 40)));
        } catch (e) {
            console.warn('Cannot keep theme:', e);
        }
    }

    openThemeHistory() {
        const list = this.loadThemeHistory();
        const host = document.getElementById('themeHistoryList');
        host.innerHTML = '';
        if (!list.length) {
            const empty = document.createElement('p');
            empty.className = 'modal-hint';
            empty.textContent = 'No themes yet - the Stylist keeps them as it makes them.';
            host.appendChild(empty);
        }
        list.forEach((theme) => {
            const row = document.createElement('button');
            row.className = 'theme-row';
            const name = document.createElement('span');
            name.textContent = theme.name;
            const swatches = document.createElement('span');
            swatches.className = 'theme-swatches';
            [theme.bg, theme.cardBg, theme.text, theme.primary, theme.border].filter(Boolean).forEach((colour) => {
                const dot = document.createElement('span');
                dot.className = 'theme-swatch';
                dot.style.background = colour;
                swatches.appendChild(dot);
            });
            row.append(name, swatches);
            row.addEventListener('click', () => this.applySavedTheme(theme));
            host.appendChild(row);
        });
        this.openModal('themeHistoryModal');
    }

    applySavedTheme(theme) {
        if (!theme) return;
        const base = {
            ...this.theme,
            name: theme.name, primary: theme.primary, bg: theme.bg,
            cardBg: theme.cardBg, text: theme.text, border: theme.border,
            mode: theme.mode || 'dark'
        };
        // A theme saved with its variants comes back exactly as it was.
        this.theme = theme.variants ? { ...base, variants: theme.variants } : this.withVariants(base);
        this.applyTheme();
        this.saveState();
        this.closeModal('themeHistoryModal');
        this.showToast(`Theme: ${theme.name}`);
    }

    /** Typing a saved theme's name is the shortest way back to it. */
    applyThemeByName(text) {
        const wanted = text.trim().replace(/^theme\s+/i, '').toLowerCase();
        if (!wanted) return false;
        const hit = this.loadThemeHistory().find(t => t.name.toLowerCase() === wanted);
        if (!hit) return false;
        this.applySavedTheme(hit);
        return true;
    }

    colourRgb(hex) {
        const match = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex || '').trim());
        if (!match) return { r: 128, g: 128, b: 128 };
        let h = match[1];
        if (h.length === 3) h = h.split('').map(ch => ch + ch).join('');
        return { r: parseInt(h.slice(0, 2), 16), g: parseInt(h.slice(2, 4), 16), b: parseInt(h.slice(4, 6), 16) };
    }

    colourHsl(hex) {
        const { r, g, b } = this.colourRgb(hex);
        const rn = r / 255, gn = g / 255, bn = b / 255;
        const max = Math.max(rn, gn, bn), min = Math.min(rn, gn, bn);
        const l = (max + min) / 2;
        let h = 0, sat = 0;
        if (max !== min) {
            const d = max - min;
            sat = l > 0.5 ? d / (2 - max - min) : d / (max + min);
            if (max === rn) h = (gn - bn) / d + (gn < bn ? 6 : 0);
            else if (max === gn) h = (bn - rn) / d + 2;
            else h = (rn - gn) / d + 4;
            h *= 60;
        }
        return { h, s: sat * 100, l: l * 100 };
    }

    hslHex({ h, s, l }) {
        const hue = ((h % 360) + 360) % 360;
        const sat = Math.max(0, Math.min(100, s)) / 100;
        const lum = Math.max(0, Math.min(100, l)) / 100;
        const chroma = (1 - Math.abs(2 * lum - 1)) * sat;
        const x = chroma * (1 - Math.abs(((hue / 60) % 2) - 1));
        const m = lum - chroma / 2;
        let rgb;
        if (hue < 60) rgb = [chroma, x, 0];
        else if (hue < 120) rgb = [x, chroma, 0];
        else if (hue < 180) rgb = [0, chroma, x];
        else if (hue < 240) rgb = [0, x, chroma];
        else if (hue < 300) rgb = [x, 0, chroma];
        else rgb = [chroma, 0, x];
        return '#' + rgb.map(v => Math.round((v + m) * 255).toString(16).padStart(2, '0')).join('');
    }

    colourLum(hex) {
        const { r, g, b } = this.colourRgb(hex);
        const channel = (v) => {
            const n = v / 255;
            return n <= 0.03928 ? n / 12.92 : Math.pow((n + 0.055) / 1.055, 2.4);
        };
        return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
    }

    /** WCAG contrast: 4.5 is readable body text, 7 is comfortable. */
    colourContrast(a, b) {
        const la = this.colourLum(a), lb = this.colourLum(b);
        return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
    }

    /** Move a colour's lightness until it can be read on `against`, keeping its hue. */
    readable(hex, against, target = 4.6) {
        if (this.colourContrast(hex, against) >= target) return hex;
        const base = this.colourHsl(hex);
        const dir = this.colourLum(against) > 0.4 ? -1 : 1;
        for (let step = 2; step <= 100; step += 2) {
            const l = base.l + dir * step;
            if (l <= 0 || l >= 100) break;
            const candidate = this.hslHex({ ...base, l });
            if (this.colourContrast(candidate, against) >= target) return candidate;
        }
        return dir < 0 ? '#101010' : '#f5f5f5';
    }

    /**
     * One palette, two views. The hue and saturation carry across, so a style is still
     * itself in either mode; only lightness moves, and only as far as legibility needs.
     */
    themeVariant(theme, mode) {
        const light = mode === 'light';
        const bg = this.colourHsl(theme.bg);
        const card = this.colourHsl(theme.cardBg);
        const text = this.colourHsl(theme.text);
        const border = this.colourHsl(theme.border);
        const primary = this.colourHsl(theme.primary);

        const bgHex = this.hslHex({ h: bg.h, s: Math.min(bg.s, light ? 26 : 46), l: light ? 96 : 9 });
        const cardHex = this.hslHex({ h: card.s > 2 ? card.h : bg.h, s: Math.min(card.s, light ? 16 : 34), l: light ? 99 : 14 });
        // Text keeps its own hue, then earns its contrast.
        const textHex = this.readable(
            this.hslHex({ h: text.h, s: Math.min(text.s, light ? 45 : 30), l: light ? 16 : 93 }), cardHex, 7);
        const borderHex = this.hslHex({ h: border.s > 2 ? border.h : bg.h, s: Math.min(border.s, 40), l: light ? 82 : 28 });
        // Primary is the identity of the style: it keeps hue and saturation and gives up
        // only the lightness legibility demands.
        const primaryHex = this.readable(
            this.hslHex({ h: primary.h, s: Math.max(primary.s, 45), l: light ? Math.min(primary.l, 46) : Math.max(primary.l, 58) }),
            cardHex, 4.6);

        return { bg: bgHex, cardBg: cardHex, text: textHex, border: borderHex, primary: primaryHex };
    }

    /** Both views are made once, when the palette arrives, so flipping never invents one. */
    withVariants(theme) {
        const mode = theme.mode === 'light' ? 'light' : 'dark';
        return {
            ...theme,
            mode,
            variants: { dark: this.themeVariant(theme, 'dark'), light: this.themeVariant(theme, 'light') }
        };
    }

    applyTheme() {
        if (!this.theme.variants) this.theme = this.withVariants({ ...this.theme });
        const mode = this.theme.mode === 'light' ? 'light' : 'dark';
        const active = this.theme.variants[mode] || this.theme.variants.dark;
        this.theme = { ...this.theme, mode, ...active };
        document.body.setAttribute('data-theme', mode);
        const r = document.documentElement.style;
        r.setProperty('--primary', this.theme.primary);
        r.setProperty('--bg', this.theme.bg);
        r.setProperty('--card-bg', this.theme.cardBg);
        r.setProperty('--text', this.theme.text);
        r.setProperty('--border', this.theme.border);
        // White on primary only while white is actually readable on it: a monochrome
        // theme put white labels on a white button and they vanished.
        r.setProperty('--on-primary', this.colourContrast('#ffffff', this.theme.primary) >= 4.5 ? '#ffffff' : '#101010');
        const brand = document.getElementById('brandPlaceholder');
        if (brand) brand.textContent = this.theme.name || 'ai-Ncards';
    }

    initASR() {
        if ("webkitSpeechRecognition" in window || "SpeechRecognition" in window) {
            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            this.recognition = new SpeechRecognition();
            this.recognition.continuous = false;
            this.recognition.lang = 'en-US';
            this.recognition.interimResults = false;

            this.recognition.onstart = () => {
                this.isListening = true;
                const btn = document.getElementById('sendBtn');
                btn.innerHTML = '<i class="fas fa-stop"></i>';
                btn.classList.add('listening');
                btn.title = "Stop Listening";
            };

            this.recognition.onend = () => {
                this.isListening = false;
                const btn = document.getElementById('sendBtn');
                btn.innerHTML = '⏎';
                btn.classList.remove('listening');
                btn.title = "Send";
            };

            this.recognition.onresult = (event) => {
                const transcript = event.results[0][0].transcript;
                document.getElementById('userInput').value = transcript;
            };
        }
    }

    /** The switch is server state, so the label has to be read, not remembered. */
    async loadEngine() {
        try {
            this.engineKey = localStorage.getItem('mind-engine-key') || '';
        } catch {
            this.engineKey = '';
        }
        const keyInput = document.getElementById('engineKeyInput');
        if (keyInput) keyInput.value = this.engineKey;

        try {
            const res = await fetch('/api/engine', { headers: { accept: 'application/json' } });
            const body = await res.json();
            this.engineCloudflare = Boolean(body.cloudflare);
        } catch {
            // Offline, or a Worker without the route: "On" is what it will be doing.
            this.engineCloudflare = true;
        }
        this.renderEngineToggle();
    }

    /** The key is only ever sent with a write, and never leaves this device. */
    saveEngineKey(value) {
        this.engineKey = String(value || '').trim();
        try {
            if (this.engineKey) localStorage.setItem('mind-engine-key', this.engineKey);
            else localStorage.removeItem('mind-engine-key');
        } catch {
            // Private mode: it still works for this page's lifetime.
        }
    }

    async toggleEngine() {
        const next = !this.engineCloudflare;
        if (!this.engineKey) {
            this.showToast('Add the KEY first — the switch is keyed');
            return;
        }
        try {
            const res = await fetch('/api/engine', {
                method: 'POST',
                headers: { 'content-type': 'application/json', 'x-engine-key': this.engineKey },
                body: JSON.stringify({ cloudflare: next }),
            });
            const body = await res.json().catch(() => null);
            if (!res.ok) {
                this.showToast(body?.error?.message || `Could not switch engines (${res.status})`);
                return;
            }
            this.engineCloudflare = Boolean(body.cloudflare);
            this.renderEngineToggle();
            this.showToast(
                this.engineCloudflare
                    ? 'Cloudflare on — Workers AI answers first'
                    : 'Cloudflare off — OpenRouter only, no neurons',
            );
        } catch (err) {
            this.showToast(`Could not switch engines: ${err.message}`);
        }
    }

    renderEngineToggle() {
        const btn = document.getElementById('engineToggle');
        const label = document.getElementById('engineLabel');
        if (label) label.textContent = this.engineCloudflare ? 'Cloudflare: On' : 'Cloudflare: Off';
        if (btn) {
            btn.setAttribute('aria-pressed', String(this.engineCloudflare));
            btn.classList.toggle('active', this.engineCloudflare);
        }
    }

    toggleASR() {
        this.settings.asrEnabled = !this.settings.asrEnabled;
        this.updateToggles();
        this.saveState();
    }

    toggleTTS() {
        this.settings.autoTTS = !this.settings.autoTTS;
        this.updateToggles();
        this.saveState();
    }

    updateToggles() {
        const asrBtn = document.getElementById('asrToggle');
        const ttsBtn = document.getElementById('ttsToggle');
        if (asrBtn) asrBtn.classList.toggle('active', this.settings.asrEnabled);
        if (ttsBtn) ttsBtn.classList.toggle('active', this.settings.autoTTS);
    }

    readCard(id, e) {
        if (e && e.stopPropagation) e.stopPropagation();
        const card = this.cards.find(c => c.id === id);
        if (!card || !card.r) return;

        this.speak(card.r);
    }

    /** Strip the app's own directives so the voice never reads markup aloud. */
    cleanForSpeech(text) {
        return String(text || '')
            .replace(/!theme:[^!]*!/gi, ' ')
            .replace(/!action:[^!]*!/gi, ' ')
            .replace(/![a-z]+:[^!]*!/gi, ' ')
            .replace(/!(bold|italic)!?/gi, ' ')
            .replace(/\[(FRONT|BACK)\]/gi, ' ')
            .replace(/[#*_`>~]/g, '')
            .replace(/\s+/g, ' ')
            .trim();
    }

    stopSpeech() {
        if (this.speechAudio) {
            this.speechAudio.pause();
            this.speechAudio = null;
        }
        if (window.speechSynthesis) window.speechSynthesis.cancel();
    }

    /**
     * Cloudflare melotts behind a cacheable GET, so the audio element streams it
     * and re-reading the same card costs no neurons. Browser speech is the
     * offline rung when the Worker cannot answer.
     */
    speak(text) {
        const clean = this.cleanForSpeech(text);
        if (!clean) return;

        if (this.speechAudio) {
            this.stopSpeech();
            return;
        }

        const chunks = [];
        let rest = clean;
        while (rest.length > 1800) {
            const cut = rest.lastIndexOf('. ', 1800);
            const at = cut > 400 ? cut + 1 : 1800;
            chunks.push(rest.slice(0, at).trim());
            rest = rest.slice(at).trim();
        }
        if (rest) chunks.push(rest);

        const base = this.getProxyUrl().replace(/\/api\/chat$/, '');
        const queue = chunks.map(chunk => `${base}/api/tts?${new URLSearchParams({ t: chunk, m: 'melotts' })}`);

        const playNext = () => {
            const src = queue.shift();
            if (!src) {
                this.speechAudio = null;
                return;
            }
            const audio = new Audio(src);
            this.speechAudio = audio;
            audio.onended = playNext;
            audio.onerror = () => {
                this.speechAudio = null;
                this.speakLocally(clean);
            };
            audio.play().catch(() => {
                this.speechAudio = null;
                this.speakLocally(clean);
            });
        };

        playNext();
    }

    speakLocally(text) {
        if (!window.speechSynthesis) {
            this.showToast('Speech unavailable');
            return;
        }
        window.speechSynthesis.cancel();
        // Chrome truncates long utterances, so sentence-sized chunks.
        for (const sentence of text.match(/[^.!?]+[.!?]*/g) || [text]) {
            const utterance = new SpeechSynthesisUtterance(sentence.trim());
            utterance.rate = 1.05;
            window.speechSynthesis.speak(utterance);
        }
    }

    /**
     * A saved Proxy URL is honoured only if it serves this app's presets.
     *
     * Which preset ran, its prompt, its budget and the truth cache are all
     * decided by the Worker behind /api/chat. A plain chat relay accepts the
     * same POST, ignores `preset`, and can end a long answer with an empty
     * stream — which reads as truncation rather than as the wrong URL. So ask
     * the configured server for its preset list once at boot: a server that
     * cannot name its presets cannot honour one, and chat returns to this site.
     */
    async verifyProxyUrl() {
        const own = new URL(DEFAULT_PROXY_URL, window.location.href).href;
        const configured = this.getProxyUrl();
        if (configured === own) return true;

        const base = configured.replace(/\/api\/chat$/, '');
        let servesPresets = false;
        let timer = null;
        try {
            const controller = new AbortController();
            timer = setTimeout(() => controller.abort(), 4000);
            const res = await fetch(`${base}/api/presets`, { signal: controller.signal });
            const body = res.ok ? await res.json().catch(() => null) : null;
            servesPresets = Array.isArray(body?.presets) && body.presets.length > 0;
        } catch {
            servesPresets = false;
        } finally {
            if (timer) clearTimeout(timer);
        }
        if (servesPresets) return true;

        const before = configured;
        this.settings.proxyUrl = own;
        this.saveState();
        const input = document.getElementById('proxyUrlInput');
        if (input) input.value = own;
        this.showToast(`Proxy URL ${before} cannot serve presets — chat is back on this site`);
        return false;
    }

    showToast(msg) {
        const t = document.getElementById('toast');
        t.textContent = msg;
        t.classList.add('show');
        setTimeout(() => t.classList.remove('show'), 2000);
    }

    /**
     * A reply that is a page, not prose.
     *
     * A stored document carries its own <style>, and sanitizing a markdown parse
     * drops that block: the layout, the type and every colour go with it, and the
     * card shows a wall of unstyled text. Anything shaped like a document is
     * framed instead, so the CSS it shipped with survives untouched.
     *
     * Fenced code is stripped first: explaining HTML should not turn the answer
     * into a frame.
     */
    looksLikeDocument(text) {
        const prose = String(text || '').replace(/```[\s\S]*?```/g, '');
        return /<!doctype\s+html|<html[\s>]|<head[\s>]|<body[\s>]|<style[\s>]/i.test(prose);
    }

    /**
     * The frame's document, with a light base underneath the page's own CSS.
     *
     * A document that names no colour inherits the browser's default, which is
     * black text — invisible once that frame is painted on a dark card. The base
     * only fills in what the page left unsaid, and it is injected into <head> so
     * the page's own <style> still wins the cascade.
     */
    documentSrcdoc(html) {
        const text = String(html || '');
        const css = (text.match(/<style[^>]*>[\s\S]*?<\/style>/gi) || []).join('\n');
        const hasBackground = /background(-color)?\s*:/i.test(css);
        const hasColor = /(?:^|[;{\s])color\s*:/i.test(css);
        const base =
            `<style>${hasBackground ? '' : 'html{background:#fff}'}` +
            `${hasColor ? '' : 'html,body{color:#111}'}body{margin:0}</style>`;
        const viewport = '<meta name="viewport" content="width=device-width, initial-scale=1">';

        if (/<head[^>]*>/i.test(text)) {
            return text.replace(/<head[^>]*>/i, (tag) => `${tag}${viewport}${base}`);
        }
        if (/<html[^>]*>/i.test(text)) {
            return text.replace(/<html[^>]*>/i, (tag) => `${tag}<head>${viewport}${base}</head>`);
        }
        return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">${viewport}${base}</head><body>${text}</body></html>`;
    }

    /**
     * Render a reply: prose as markdown, a document as a sandboxed frame.
     *
     * The frame runs scripts so a page's own buttons work, but without
     * allow-same-origin it cannot reach this document, its state or its storage.
     */
    renderAnswer(text, { full = false } = {}) {
        const raw = String(text || '');
        if (!raw.trim() || !this.looksLikeDocument(raw)) return this.md(raw);
        const doc = this.escapeAttr(this.documentSrcdoc(raw));
        return (
            '<div class="doc-shell">' +
            `<iframe class="doc-frame${full ? ' doc-frame-full' : ''}" title="Generated document" ` +
            `sandbox="allow-scripts allow-modals allow-popups allow-forms" srcdoc="${doc}"></iframe>` +
            '</div>'
        );
    }

    escapeAttr(text) {
        return String(text)
            .replace(/&/g, '&amp;')
            .replace(/"/g, '&quot;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
    }

    md(text) {
        if (!text) return '';
        try {
            return DOMPurify.sanitize(marked.parse(text));
        } catch (e) {
            console.error("Markdown parsing error", e);
            return text;
        }
    }

    escapeHtml(text) {
        if (!text) return '';
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    window.app = new App();
    window.app.init();
    window.app.verifyProxyUrl();
});

/* ── Ambient: a second voice that can see the canvas ──────────────────────
   Not a card and not the audit engine. It is a conversation about the loaded
   work: what a card says, where two disagree, what to ask next. The context is
   built here, so it is always what is actually on screen.

   It is a window, not a drawer. It floats where it is put, it is moved by its
   own bar, and it closes down to a pin that is itself movable - so it never
   covers the work for longer than it is wanted. The composer is part of the
   window: when the window is a pin, the composer is a pin too. */
const Ambient = {
    thread: [],
    busy: false,
    panel: null,
    pin: null,
    key: 'mind_assist',
    layoutKey: 'mind_assist_layout',
    snapshot: null,
    layout: { x: null, y: null, pinX: null, pinY: null, w: null, h: null },

    load() {
        try { this.thread = JSON.parse(localStorage.getItem(this.key) || '[]'); } catch (e) { this.thread = []; }
        if (!Array.isArray(this.thread)) this.thread = [];
        try {
            const saved = JSON.parse(localStorage.getItem(this.layoutKey) || '{}');
            if (saved && typeof saved === 'object') {
                ['x', 'y', 'pinX', 'pinY', 'w', 'h'].forEach((k) => {
                    if (Number.isFinite(saved[k])) this.layout[k] = saved[k];
                });
            }
        } catch (e) { /* a lost layout is the corner it starts in */ }
    },
    save() {
        try { localStorage.setItem(this.key, JSON.stringify(this.thread.slice(-40))); } catch (e) {}
    },
    saveLayout() {
        try { localStorage.setItem(this.layoutKey, JSON.stringify(this.layout)); } catch (e) {}
    },
    /**
     * Both faces of every card, in full. The assistant used to be handed 200
     * characters of the request and 420 of the answer, so it was reading previews
     * of the work and calling them the work: a letter cut mid-sentence reads like
     * a letter that ends there. It is the voice between the system and him, so it
     * gets what is actually on the canvas, front and back.
     */
    context() {
        const cards = (window.app && window.app.cards) || [];
        const LIMIT = 8000;
        const cut = (text) => {
            const full = String(text || '').trim();
            return full.length > LIMIT
                ? full.slice(0, LIMIT) + '\n[cut here at ' + LIMIT + ' characters]'
                : full;
        };
        const lines = cards.slice(0, 40).map((card, i) => {
            const d = card.decision || {};
            const back = card.r === '...' ? '(still thinking)' : (cut(card.r) || '(empty)');
            return '#' + (i + 1) + ' [' + (d.domain || 'general') + ' / ' + (d.task || 'ask') + (d.source ? ' / ' + d.source : '') + ']' +
                '\nREQUEST (front face):\n' + (cut(card.q) || '(empty)') +
                '\nRESPONSE (back face):\n' + back;
        });
        const head = cards.length + ' card' + (cards.length === 1 ? '' : 's') +
            ' on the canvas. Both faces of each one are below.';
        return [head].concat(lines).join('\n\n');
    },

    /** A window dragged off the edge is a window lost, so both keep to the screen. */
    clamp(x, y, w, h) {
        return {
            x: Math.round(Math.min(Math.max(8, x), Math.max(8, window.innerWidth - w - 8))),
            y: Math.round(Math.min(Math.max(8, y), Math.max(8, window.innerHeight - h - 8)))
        };
    },
    panelSize() {
        return {
            w: (this.panel && this.panel.offsetWidth) || Math.min(380, window.innerWidth - 24),
            h: (this.panel && this.panel.offsetHeight) || Math.min(470, Math.round(window.innerHeight * 0.68))
        };
    },
    applyLayout() {
        if (!this.panel || !this.pin) return;
        // A size he chose is kept inside the screen, the way a position is.
        if (this.layout.w) this.panel.style.width = Math.min(this.layout.w, window.innerWidth - 16) + 'px';
        if (this.layout.h) this.panel.style.height = Math.min(this.layout.h, window.innerHeight - 16) + 'px';
        const size = this.panelSize();
        const at = this.clamp(
            this.layout.x === null ? 12 : this.layout.x,
            this.layout.y === null ? window.innerHeight - size.h - 104 : this.layout.y,
            size.w, size.h
        );
        this.panel.style.left = at.x + 'px';
        this.panel.style.top = at.y + 'px';
        const pinBox = this.pin.offsetWidth || 44;
        const pinAt = this.clamp(
            this.layout.pinX === null ? 14 : this.layout.pinX,
            this.layout.pinY === null ? window.innerHeight - 118 : this.layout.pinY,
            pinBox, pinBox
        );
        this.pin.style.left = pinAt.x + 'px';
        this.pin.style.top = pinAt.y + 'px';
    },

    build() {
        if (this.panel) return this.panel;

        const pin = document.createElement('button');
        pin.id = 'assistPin';
        pin.type = 'button';
        pin.className = 'show';
        pin.title = 'Ambient - tap to open, drag to move';
        pin.innerHTML = '<i class="fas fa-comment-dots"></i>';

        const panel = document.createElement('div');
        panel.id = 'assistPanel';
        panel.innerHTML =
            '<div id="assistHead">' +
              '<strong>Ambient</strong>' +
              '<span id="assistContext"></span>' +
              '<button class="assist-hbtn" id="assistClear" title="Clear this conversation">clear</button>' +
              '<button class="assist-hbtn" id="assistMin" title="Minimize to the pin">&minus;</button>' +
            '</div>' +
            '<div id="assistThread"></div>' +
            '<div id="assistComposer">' +
              '<textarea id="assistInput" rows="2" placeholder="Ask about what is loaded..."></textarea>' +
              '<button id="assistSend">send</button>' +
            '</div>' +
            '<div id="assistGrip" title="Drag to resize"></div>';

        document.body.appendChild(pin);
        document.body.appendChild(panel);
        this.panel = panel;
        this.pin = pin;

        panel.querySelector('#assistMin').onclick = () => this.toggle(false);
        panel.querySelector('#assistClear').onclick = () => { this.thread = []; this.save(); this.render(); };
        panel.querySelector('#assistSend').onclick = () => this.send();
        panel.querySelector('#assistInput').addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); this.send(); }
        });

        // The bar moves the window; a press on a control in the bar is that control.
        this.drag(panel, panel.querySelector('#assistHead'), null);
        // The pin moves the same way, and a press that never travels opens it.
        this.drag(pin, pin, () => this.toggle(true));
        // The corner changes the window's size instead of its place.
        this.resize();

        this.applyLayout();
        window.addEventListener('resize', () => this.applyLayout());
        return panel;
    },

    /**
     * One gesture for both moves. Below a few pixels it is a tap, because a
     * pin that opens on a shaky press is a pin that cannot be moved at all.
     */
    drag(el, handle, onTap) {
        let from = null;
        let start = null;
        let moved = false;
        const isPanel = el === this.panel;

        handle.addEventListener('pointerdown', (e) => {
            if (isPanel && e.target.closest('button')) return;
            from = { x: e.clientX, y: e.clientY };
            start = { x: parseFloat(el.style.left) || 0, y: parseFloat(el.style.top) || 0 };
            moved = false;
            if (e.pointerId !== undefined && handle.setPointerCapture) {
                try { handle.setPointerCapture(e.pointerId); } catch (err) { /* not capturable */ }
            }
            if (isPanel) e.preventDefault();
        });

        handle.addEventListener('pointermove', (e) => {
            if (!from) return;
            const dx = e.clientX - from.x;
            const dy = e.clientY - from.y;
            if (!moved && Math.hypot(dx, dy) < 6) return;
            moved = true;
            el.classList.add('dragging');
            const at = this.clamp(start.x + dx, start.y + dy, el.offsetWidth || 44, el.offsetHeight || 44);
            el.style.left = at.x + 'px';
            el.style.top = at.y + 'px';
            el.style.right = 'auto';
            el.style.bottom = 'auto';
        });

        const end = () => {
            if (!from) return;
            from = null;
            el.classList.remove('dragging');
            if (moved) {
                const at = { x: Math.round(parseFloat(el.style.left) || 0), y: Math.round(parseFloat(el.style.top) || 0) };
                if (isPanel) { this.layout.x = at.x; this.layout.y = at.y; }
                else { this.layout.pinX = at.x; this.layout.pinY = at.y; }
                this.saveLayout();
            } else if (onTap) {
                onTap();
            }
        };
        handle.addEventListener('pointerup', end);
        handle.addEventListener('pointercancel', end);
    },

    /** The corner grip resizes; the size is remembered with the position. */
    resize() {
        const grip = this.panel.querySelector('#assistGrip');
        let from = null;
        let start = null;

        grip.addEventListener('pointerdown', (e) => {
            const box = this.panel.getBoundingClientRect();
            from = { x: e.clientX, y: e.clientY };
            start = { w: box.width, h: box.height };
            if (e.pointerId !== undefined && grip.setPointerCapture) {
                try { grip.setPointerCapture(e.pointerId); } catch (err) { /* not capturable */ }
            }
            e.preventDefault();
            e.stopPropagation();
        });

        grip.addEventListener('pointermove', (e) => {
            if (!from) return;
            const w = Math.min(Math.max(260, start.w + (e.clientX - from.x)), window.innerWidth - 16);
            const h = Math.min(Math.max(200, start.h + (e.clientY - from.y)), window.innerHeight - 16);
            this.panel.style.width = Math.round(w) + 'px';
            this.panel.style.height = Math.round(h) + 'px';
        });

        const end = () => {
            if (!from) return;
            from = null;
            const box = this.panel.getBoundingClientRect();
            this.layout.w = Math.round(box.width);
            this.layout.h = Math.round(box.height);
            this.saveLayout();
            this.applyLayout();
        };
        grip.addEventListener('pointerup', end);
        grip.addEventListener('pointercancel', end);
    },

    toggle(force) {
        const panel = this.build();
        const open = force === undefined ? !panel.classList.contains('open') : force;
        panel.classList.toggle('open', open);
        this.pin.classList.toggle('show', !open);
        if (open) {
            this.render();
            this.applyLayout();
            // On a phone the keyboard would cover the window it was opened for.
            if (window.innerWidth > 768) {
                const input = panel.querySelector('#assistInput');
                if (input) input.focus();
            }
        }
    },

    render() {
        const panel = this.build();
        const box = panel.querySelector('#assistThread');
        const cards = (window.app && window.app.cards) || [];
        panel.querySelector('#assistContext').textContent = cards.length
            ? cards.length + ' card' + (cards.length === 1 ? '' : 's') + ' in view'
            : 'nothing loaded';
        box.innerHTML = '';
        if (!this.thread.length) {
            const hint = document.createElement('div');
            hint.style.cssText = 'color:#6f7885;font-size:12px';
            hint.textContent = cards.length
                ? 'I can see the cards on the canvas. Ask me about them.'
                : 'Load or ask something first, then we can talk it through.';
            box.appendChild(hint);
            return;
        }
        this.thread.forEach((turn) => {
            const bubble = document.createElement('div');
            const mine = turn.role === 'user';
            bubble.style.cssText = 'margin:0 0 10px;padding:8px 10px;border-radius:8px;white-space:pre-wrap;' +
                (mine ? 'background:#1e2a3a;border:1px solid #2a3f5a' : 'background:#141821;border:1px solid #232833');
            bubble.textContent = turn.content;
            box.appendChild(bubble);
        });
        box.scrollTop = box.scrollHeight;
    },

    /**
     * The app's own code, as one generated snapshot (npm run snapshot). Fetched
     * once per session: it is about a megabyte, so it is not re-fetched for
     * every question, and it is never sent whole - only the file asked for.
     */
    async appSource() {
        if (this.snapshot) return this.snapshot;
        const base = (window.app && typeof window.app.getProxyUrl === 'function') ? window.app.getProxyUrl() : location.origin;
        const res = await fetch(new URL('/source-snapshot.json', base).toString());
        if (!res.ok) throw new Error('no source snapshot (' + res.status + ')');
        this.snapshot = await res.json();
        return this.snapshot;
    },
    sourceMap(snapshot) {
        return (snapshot.files || [])
            .map((f) => f.path + ' (' + f.lines + ' lines)' + (f.purpose ? ' - ' + f.purpose : ''))
            .join('\n');
    },
    sourceOf(snapshot, path) {
        const want = String(path || '').trim();
        if (!want) return null;
        const files = snapshot.files || [];
        return files.find((f) => f.path === want)
            || files.find((f) => f.path.endsWith(want) || f.path.endsWith('/' + want))
            || null;
    },
    async ask(context, thread) {
        const base = (window.app && typeof window.app.getProxyUrl === 'function') ? window.app.getProxyUrl() : location.origin;
        const res = await fetch(new URL('/api/assist', base).toString(), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ thread, context })
        });
        const body = await res.json().catch(() => null);
        return body && body.text
            ? body.text
            : ((body && body.error && body.error.message) || ('No answer (' + res.status + ').'));
    },

    async send() {
        if (this.busy) return;
        const panel = this.build();
        const input = panel.querySelector('#assistInput');
        const said = (input.value || '').trim();
        if (!said) return;
        input.value = '';
        this.thread.push({ role: 'user', content: said });
        this.thread.push({ role: 'assistant', content: '…' });
        this.busy = true;
        this.render();
        try {
            // The turns asked so far, without the placeholder being written to.
            const history = this.thread.slice(0, -1);
            const snapshot = await this.appSource().catch(() => null);
            const context = [
                this.context(),
                snapshot
                    ? "Mind's own code, a map of the files you can read (paths exactly as listed):\n" + this.sourceMap(snapshot)
                    : 'Mind\'s own code is not in this build (no source snapshot), so do not guess at it.'
            ].join('\n\n');

            let reply = await this.ask(context, history);

            // One file per question. It asks with a line of its own and gets the
            // file as source, because the point is that it reads the code rather
            // than a description of the code.
            const want = reply.match(/\[read:\s*([^\]]+)\]/i);
            if (want && snapshot) {
                const asked = String(want[1]).trim();
                // [read: path] sends the start; [read: path around aName] sends the
                // part that matters, because a 5000-line script cannot fit in one
                // brief and the answer is usually one function away.
                const around = asked.match(/^(.+?)\s+around\s+(.+)$/i);
                const file = this.sourceOf(snapshot, around ? around[1] : asked);
                reply = reply.replace(want[0], '').trim();
                if (file) {
                    const READ = 40000;
                    let body = '';
                    let where = '';
                    if (around) {
                        const needle = around[2].trim();
                        const at = file.text.indexOf(needle);
                        const lines = file.text.split('\n');
                        if (at < 0) {
                            body = file.text.slice(0, READ);
                            where = ' (nothing matching "' + needle + '", so here is the start)';
                        } else {
                            const lineNo = file.text.slice(0, at).split('\n').length;
                            // A symbol can sit inside a 400-line object, so the
                            // window is wide enough to hold the thing it names.
                            const from = Math.max(1, lineNo - 250);
                            const to = Math.min(lines.length, lineNo + 250);
                            body = lines.slice(from - 1, to).join('\n').slice(0, READ);
                            where = ' (lines ' + from + '-' + to + ' of ' + lines.length + ', around "' + needle + '")';
                        }
                    } else {
                        body = file.text.slice(0, READ);
                        where = file.text.length > READ ? ' (the first ' + READ + ' of ' + file.text.length + ' characters)' : '';
                    }
                    const deliver = 'Here is ' + file.path + where + ', as it stands:\n' + body;
                    reply = await this.ask(context, history.concat([
                        { role: 'assistant', content: want[0] },
                        { role: 'user', content: deliver }
                    ]));
                } else {
                    reply = (reply ? reply + '\n\n' : '') + 'No file at ' + asked + ' in the snapshot.';
                }
            }
            this.thread[this.thread.length - 1] = { role: 'assistant', content: reply };
        } catch (err) {
            this.thread[this.thread.length - 1] = { role: 'assistant', content: 'Ambient unavailable: ' + err.message };
        }
        this.busy = false;
        this.save();
        this.render();
    }
};

Ambient.load();
window.addEventListener('load', function () { Ambient.build(); });

:root {
    --primary: #c41e3a;
    --bg: #121212;
    --card-bg: #1e1e1e;
    --text: #f5f5f5;
    --border: #333;
    --shadow: 0 4px 16px rgba(196,30,58,0.2);
    --radius: 16px;
    --card-min-height: 200px;
    --view-cols: 1;
    --safe-area-bottom: env(safe-area-inset-bottom);
}

/* The light view is a view of the style, not a different one: its colours come from the
   theme's own palette, so this only adjusts what is not a colour. */
[data-theme="light"] { --shadow: 0 4px 16px rgba(0,0,0,0.12); }

body.view-grid { --view-cols: 2; }
body.view-full { --view-cols: 1; }

@media (max-width: 768px) {
    body.view-grid { --view-cols: 2; }
    #grid { gap: 10px; padding: 10px; }
    #inputPanel { padding: 10px; gap: 8px; padding-bottom: calc(10px + var(--safe-area-bottom)); }
    #userInput { padding: 14px; font-size: 16px; height: 48px; }
    #presetSelectorBtn { padding: 0 10px; font-size: 12px; height: 48px; }
    #presetSelectorBtn i { display: none; }
    #sendBtn { padding: 12px 16px; min-width: 50px; height: 48px; font-size: 22px; }
    #topBar { height: 50px; }
    .fab { width: 36px; height: 36px; font-size: 12px; }
    .view-fab-container { bottom: 95px; right: 10px; }
    .card-face { font-size: 14px; }
    #cardMenu, #quickMenu { min-width: 200px; left: 50% !important; transform: translateX(-50%) !important; top: auto !important; bottom: 80px; }
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
body {
    font-family: system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    padding-top: 50px;
    padding-bottom: 80px;
    transition: background 0.3s, color 0.3s;
    overflow-x: hidden;
}

#topBar {
    position: fixed; top: 0; left: 0; right: 0; height: 50px;
    padding: 0 10px; display: flex; align-items: center; justify-content: space-between;
    z-index: 50; background: linear-gradient(to bottom, var(--bg), transparent); pointer-events: none;
}
#brandPlaceholder { background: none; border: none; font-family: inherit; cursor: pointer;
    padding: 6px 8px; margin-left: 2px; border-radius: 8px; font-weight: 900; color: var(--primary); text-transform: uppercase; letter-spacing: 1px; font-size: 12px;
    /* A long theme name must not push the menu off the bar and out of reach. */
    max-width: 42vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#brandPlaceholder:hover { background: rgba(255,255,255,0.07); }
.top-fabs { pointer-events: auto; display: flex; gap: 6px; }
.fab {
    width: 36px; height: 36px; border-radius: 50%; background: var(--card-bg);
    border: 1px solid var(--border); color: var(--text); display: flex; align-items: center; justify-content: center;
    cursor: pointer; box-shadow: var(--shadow); transition: all 0.2s; font-size: 12px; backdrop-filter: blur(5px);
}
.fab:hover { transform: scale(1.1); background: var(--bg); }
.fab.primary { background: var(--primary); color: var(--on-primary, #fff); border: none; }

.preset-select {
    padding: 4px 8px;
    border-radius: 6px;
    border: 1px solid var(--border);
    background: var(--bg);
    color: var(--text);
    font-size: 11px;
    cursor: pointer;
    max-width: 100px;
}
.preset-select:focus { outline: none; border-color: var(--primary); }

#selectionBar {
    position: fixed; top: 0; left: 0; right: 0; background: var(--card-bg); border-bottom: 1px solid var(--border);
    padding: 10px; z-index: 1000; display: none; align-items: center; justify-content: space-between;
    box-shadow: var(--shadow); transform: translateY(-100%); transition: transform 0.3s;
}
#selectionBar.active { display: flex; transform: translateY(0); }
#mergeSelected, #deleteSelected, #splitSelected {
    background: var(--primary); color: var(--on-primary, #fff); border: none; padding: 8px 12px; border-radius: 8px; cursor: pointer; font-size: 13px; margin-left: 6px;
    display: flex; align-items: center; gap: 4px;
}
#deleteSelected { background: #d32f2f; }
#cancelSelect { padding: 6px 10px; }

#grid {
    display: grid; grid-template-columns: repeat(var(--view-cols), 1fr); gap: 16px; padding: 16px;
    max-width: 1000px; margin: 0 auto; transition: all 0.3s ease; min-height: 50vh; outline: none;
}
/* Grid view is a work surface: four cells fill the first screen, and a card can
   be given more than one of them. */
body.view-grid #grid {
    grid-template-columns: repeat(var(--view-cols), minmax(0, 1fr));
    grid-auto-rows: calc((100dvh - 230px) / 2);
    max-width: 1600px; align-items: stretch;
}
body.view-grid .flip-card {
    grid-column: span var(--span-cols, 1); grid-row: span var(--span-rows, 1);
    min-height: 0; height: 100%;
}
@media (max-width: 768px) {
    body.view-grid #grid { grid-auto-rows: calc((100dvh - 210px) / 2); }
}
body.view-full #grid { display: block; padding: 0; gap: 0; }
/* 100vh is the tallest viewport, not the visible one: with the top bar and the
   typing bar around it the card ran past the bottom of the screen and the end of
   the answer sat off-screen. dvh is what is actually on screen, minus the bars. */
body.view-full #grid .flip-card { height: calc(100dvh - 130px); border-radius: 0; border: none; min-height: unset; }
body.view-full.input-hidden #grid .flip-card { height: calc(100dvh - 66px); }
#grid:focus-visible { outline: 2px solid var(--primary); outline-offset: 4px; }

.flip-card {
    min-height: var(--card-min-height); perspective: 1000px; border-radius: var(--radius);
    overflow: hidden; box-shadow: var(--shadow); position: relative;
    background: var(--card-bg); border: 1px solid var(--border);
    transition: transform 0.2s, box-shadow 0.2s; touch-action: manipulation;
}
.flip-card:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.2); }
.flip-card:focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; }
.flip-card.new { animation: appear 0.4s ease forwards; opacity: 0; transform: scale(0.95); }
@keyframes appear { to { opacity: 1; transform: scale(1); } }
.flip-card.selected { outline: 3px solid var(--primary); outline-offset: -3px; z-index: 10; }
.flip-card.locked { border: 2px dashed var(--primary); }

.flip-card-inner { width: 100%; height: 100%; transition: transform 0.6s; transform-style: preserve-3d; position: relative; }
.flip-card.flipped .flip-card-inner { transform: rotateY(180deg); }

.card-face {
    position: absolute; inset: 0; backface-visibility: hidden;
    display: flex; flex-direction: column; padding: 14px; overflow-y: auto;
    font-size: 14px; line-height: 1.5; background: inherit; color: inherit;
    /* A face rotated away is invisible but still takes the press in Chromium, so
       a press on the response landed on the request underneath and flipped the
       card back - the read-aloud and menu buttons included. Only the face that
       is actually showing takes input. */
    pointer-events: none;
}
.flip-card:not(.flipped) .card-face:not(.card-back),
.flip-card.flipped .card-back { pointer-events: auto; }
.card-back { transform: rotateY(180deg); }

.card-header {
    position: sticky; top: 0; display: flex; justify-content: space-between; align-items: center;
    padding-bottom: 8px; background: inherit; z-index: 5; border-bottom: 1px solid var(--border);
    margin-bottom: 8px; gap: 8px;
}
.card-actions { display: flex; gap: 4px; }
.card-actions button { 
    background: none; border: none; color: var(--text); cursor: pointer; 
    padding: 4px; opacity: 0.55; border-radius: 8px; transition: all 0.2s;
    min-width: 38px; min-height: 38px; display: flex; align-items: center; justify-content: center;
    touch-action: manipulation;
}
.card-actions button:hover { opacity: 1; background: rgba(255,255,255,0.1); }

/* Arranging a card: the header grip moves it, the corner grip resizes it. */
.card-head-left { display: flex; align-items: center; gap: 6px; min-width: 0; }
.card-grip, .card-resize { display: none; }
body.view-grid .card-grip {
    display: inline-flex; align-items: center; justify-content: center;
    width: 22px; height: 22px; border-radius: 4px; opacity: 0.45;
    cursor: grab; touch-action: none; flex-shrink: 0;
}
body.view-grid .card-grip:hover { opacity: 1; background: rgba(255,255,255,0.1); }
body.view-grid .card-resize {
    display: block; position: absolute; right: 0; bottom: 0; width: 28px; height: 28px;
    z-index: 20; padding: 0; border: none; background: transparent;
    cursor: nwse-resize; touch-action: none;
}
body.view-grid .card-resize::after {
    content: ''; position: absolute; right: 5px; bottom: 5px; width: 12px; height: 12px;
    border-right: 2px solid var(--primary); border-bottom: 2px solid var(--primary);
    border-radius: 0 0 3px 0; opacity: 0.7;
}
.flip-card.dragging { opacity: 0.45; transform: scale(0.98); }
.flip-card.resizing { outline: 2px dashed var(--primary); outline-offset: -2px; }

.fullscreen-overlay {
    position: fixed; inset: 0; background: var(--bg); z-index: 2000; display: none; flex-direction: column;
}
.fullscreen-overlay.active { display: flex; }
.fs-header { 
    padding: 8px 12px; background: var(--card-bg); border-bottom: 1px solid var(--border); 
    display: flex; justify-content: space-between; align-items: center; flex-shrink: 0; 
}
/* The overlay owns the scroll. The pane is given exactly the room between the
   header and the bottom of the window, so an answer fills the screen it is on
   instead of sizing itself from its own content. */
.fs-content { 
    flex: 1; overflow: hidden; padding: 0; display: flex; flex-direction: column;
    justify-content: flex-start; align-items: stretch; min-height: 0;
}
.fs-pane { 
    background: var(--card-bg); border: none; border-top: 1px solid var(--border); border-radius: 0; 
    position: relative; margin: 0 auto; display: flex; flex-direction: column;
    flex: 1 1 0; padding: 8px 26px 32px; overflow-y: auto; min-height: 0; width: 100%; 
    font-size: 1.3rem; line-height: 1.65; margin-bottom: 0; 
}
.fs-pane h1, .fs-pane h2, .fs-pane h3 { margin-top: 1.5em; margin-bottom: 0.5em; color: var(--primary); }
/* Fullscreen is one answer on the whole screen: the label gets out of the way
   and the answer starts at the top. */
.fs-pane > h3 { font-size: 11px; letter-spacing: 1.6px; text-transform: uppercase; opacity: 0.5; margin: 4px 0 10px; }
.fs-pane > #fsResponse { flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; }
/* The answer fills whatever size the pane has been dragged to, so the document
   grows with the screen instead of keeping a fixed height. The 240px floor that
   used to live here was the whole visible page: with nothing definite to measure
   against, the frame stopped at the floor and the rest of the document was cut
   off. The pane is the floor now. */
.fs-pane .doc-shell { margin-top: 0; height: auto; flex: 1 1 0; min-height: 0; display: flex; flex-direction: column; }
.fs-pane .doc-frame-full { flex: 1 1 0; height: auto; min-height: 0; }
/* A document in the fullscreen pane fills it even when the answer was painted
   without the full flag: otherwise it keeps its 60vh card height and leaves the
   lower half of the screen empty. */
.fs-pane .doc-frame { flex: 1 1 0; height: auto; min-height: 0; }
.fs-grip {
    position: absolute; right: 0; bottom: 0; width: 30px; height: 30px; z-index: 5;
    cursor: nwse-resize; touch-action: none;
}
.fs-grip::after {
    content: ''; position: absolute; right: 6px; bottom: 6px; width: 12px; height: 12px;
    border-right: 2px solid var(--primary); border-bottom: 2px solid var(--primary);
    border-radius: 0 0 3px 0; opacity: 0.7;
}
.fs-pane p { margin-bottom: 1em; }

.streaming { text-align: center; color: #888; padding: 20px; display: flex; align-items: center; justify-content: center; gap: 10px; flex-wrap: wrap; }
.cursor { display: inline-block; width: 3px; height: 1em; background: currentColor; animation: blink 1s infinite; vertical-align: middle; }
@keyframes blink { 50% { opacity: 0; } }

.thinking-indicator {
    display: inline-block; color: var(--primary); font-weight: bold; font-size: 12px; 
    text-transform: uppercase; letter-spacing: 1px; animation: pulse-text 1.5s infinite;
}
@keyframes pulse-text { 0% { opacity: 0.3; } 50% { opacity: 1; } 100% { opacity: 0.3; } }

.stop-stream-btn {
    background: #d32f2f; color: white; border: none; padding: 4px 8px; border-radius: 4px; cursor: pointer; 
    font-size: 12px; vertical-align: middle; margin-left: 10px; transition: all 0.2s;
}
.stop-stream-btn:hover { background: #b71c1c; transform: scale(1.05); }

#inputPanel {
    position: fixed; bottom: 0; left: 0; right: 0; background: var(--card-bg); border-top: 1px solid var(--border); 
    padding: 12px; display: flex; gap: 10px; z-index: 100; transition: transform 0.16s ease-out; box-shadow: 0 -4px 20px rgba(0,0,0,0.2); align-items: center;
    padding-bottom: calc(12px + var(--safe-area-bottom));
}

/* The bar's top edge is a handle. Its size is a preference, and a preference should be
   set with a finger rather than guessed at in a menu. */
#inputGrab {
    position: absolute; top: -9px; left: 0; right: 0; height: 18px;
    cursor: ns-resize; touch-action: none; display: flex;
    align-items: center; justify-content: center; z-index: 2;
}
#inputGrab::after {
    content: ''; width: 46px; height: 4px; border-radius: 2px;
    background: var(--border); transition: background 0.15s, width 0.15s;
}
#inputGrab:hover::after, body.bar-dragging #inputGrab::after { background: var(--primary); width: 66px; }
/* While the finger is down the bar must follow it exactly, so no transition. */
body.bar-dragging #inputPanel { transition: none; }
/* A taller bar is breathing room around the same row. Stretching the field was what turned
   it into a tall sliver on a narrow phone, where four controls leave it little width; the
   direction that earns its keep is shrinking the bar to give the cards the room. */
body.bar-custom #inputPanel { overflow: hidden; }

/* The bar can leave the rail. A floating bar is for the moments the bottom edge is the
   wrong place for it; drop it near the rail and it goes home. */
#barFloatBtn {
    background: var(--bg); color: var(--text); border: 1px solid var(--border);
    border-radius: 50%; width: 40px; height: 40px; flex-shrink: 0; cursor: pointer;
    font-size: 12px; display: flex; align-items: center; justify-content: center;
    opacity: 0.65; transition: opacity 0.2s, border-color 0.2s, color 0.2s;
}
#barFloatBtn:hover { opacity: 1; border-color: var(--primary); }
body.bar-floating #barFloatBtn { opacity: 1; color: var(--primary); border-color: var(--primary); }
body.bar-floating #inputPanel {
    left: 0; top: 0; right: auto; bottom: auto;
    width: min(360px, calc(100vw - 24px));
    border: 1px solid var(--border); border-radius: 14px;
    box-shadow: 0 18px 40px rgba(0,0,0,0.45);
    cursor: move; touch-action: none;
}
body.bar-floating #inputPanel button,
body.bar-floating #inputPanel input { cursor: pointer; }
body.bar-floating.bar-dragging #inputPanel { cursor: grabbing; }
body.bar-floating #inputPanel #userInput { cursor: text; }
/* Six controls leave a 360px bar no room for a field, so a loose bar stacks: the field
   gets the whole first row and the controls sit under it. */
body.bar-floating #inputPanel { flex-wrap: wrap; }
body.bar-floating #userInput { order: -1; flex: 1 1 100%; }

/* Loose, the bar has a corner to pull on: the line still carries it, so the two gestures
   stay apart. Docked there is nothing to pull on, because the rail already decides. */
#barResize { display: none; position: absolute; right: 2px; bottom: 2px; width: 22px; height: 22px; cursor: nwse-resize; touch-action: none; }
#barResize::after {
    content: ''; position: absolute; right: 5px; bottom: 5px; width: 9px; height: 9px;
    border-right: 2px solid var(--border); border-bottom: 2px solid var(--border); border-radius: 1px;
}
body.bar-floating #barResize { display: block; }
body.bar-floating #barResize:hover::after { border-color: var(--primary); }

/* Minimised, a loose bar is only the pin - no strip across the bottom offering to bring
   back something that never lived there. */
body.input-hidden.bar-floating #showInput { bottom: auto; left: 0; top: 0; transform: none; }

/* Hold the pin and the choice opens out, so a tap never has to mean two things. */
#barMenu {
    position: fixed; z-index: 140; display: none; flex-direction: column; gap: 2px; padding: 6px;
    background: var(--card-bg); border: 1px solid var(--border); border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5); min-width: 190px;
}
#barMenu.active { display: flex; }
#barMenu button {
    text-align: left; background: transparent; border: none; color: var(--text);
    padding: 11px 12px; border-radius: 8px; font-size: 14px; cursor: pointer;
}
#barMenu button:hover { background: var(--bg); }
#userInput {
    flex: 1; padding: 12px 14px; border-radius: 24px; border: 1px solid var(--border); 
    background: var(--bg); color: var(--text); font-size: 16px; outline: none; 
    transition: border 0.2s; resize: none; height: 46px; max-height: 100px; overflow-y: auto;
    /* The global input rule gives every text field a 120px floor for modals. That floor
       is why the bar could not be made smaller than its content: this field is a single
       line in a row, so it keeps its own height and no margin. */
    min-height: 46px; margin-bottom: 0;
}
#userInput:focus { border-color: var(--primary); }

#presetSelectorBtn {
    background: var(--bg); color: var(--text); border: 1px solid var(--border);
    padding: 0 12px; border-radius: 24px; cursor: pointer; font-size: 13px;
    display: flex; align-items: center; gap: 6px; height: 46px; white-space: nowrap;
    transition: all 0.2s; flex-shrink: 0;
}
#presetSelectorBtn:hover { border-color: var(--primary); }
#presetSelectorBtn.active { background: var(--primary); color: var(--on-primary, #fff); border-color: var(--primary); }

#sendBtn { 
    background: var(--primary); color: var(--on-primary, #fff); border: none; padding: 0 16px; 
    border-radius: 24px; cursor: pointer; font-weight: bold; 
    display: flex; align-items: center; justify-content: center; 
    min-width: 46px; height: 46px; font-size: 22px; 
    transition: all 0.2s; flex-shrink: 0;
}
#sendBtn:hover { background: #a1172f; transform: translateY(-1px); }
#sendBtn.listening { background: #d32f2f; animation: pulse-btn 1s infinite; }
@keyframes pulse-btn { 0% { transform: scale(1); } 50% { transform: scale(1.05); } 100% { transform: scale(1); } }

.view-fab-container { position: fixed; bottom: 80px; right: 12px; z-index: 90; display: flex; flex-direction: column; gap: 8px; align-items: center; }

/* The bar can be put away: with nothing to type, the cards get the screen. */
#collapseInput {
    background: var(--bg); color: var(--text); border: 1px solid var(--border);
    border-radius: 50%; width: 40px; height: 40px; flex-shrink: 0; cursor: pointer;
    font-size: 12px; display: flex; align-items: center; justify-content: center;
    opacity: 0.65; transition: opacity 0.2s, border-color 0.2s;
}
#collapseInput:hover { opacity: 1; border-color: var(--primary); }

body.input-hidden #inputPanel {
    transform: translateY(calc(100% + 20px));
    visibility: hidden;
    transition: transform 0.16s ease-out, visibility 0s linear 0.16s;
}
body:not(.input-hidden) #inputPanel { visibility: visible; transition: transform 0.16s ease-out; }
body.input-hidden #attachTray { display: none; }
body.input-hidden { padding-bottom: 16px; }
body.input-hidden .view-fab-container { bottom: 58px; }
body.input-hidden.view-grid #grid { grid-auto-rows: calc((100dvh - 150px) / 2); }

/* The way back is a pin, in every state. A strip that appears where the bar was is a
   moving target under a thumb; a pin sits still and does not change shape when tapped. */
#showInput {
    position: fixed; left: 50%; bottom: 14px; transform: translateX(-50%);
    z-index: 130; width: 48px; height: 48px; padding: 0; border-radius: 50%;
    border: 1px solid var(--border); background: var(--card-bg); color: var(--text);
    display: flex; align-items: center; justify-content: center; font-size: 15px;
    box-shadow: var(--shadow); cursor: grab; touch-action: none;
    opacity: 0; pointer-events: none; transition: opacity 0.10s ease-out;
}
body.input-hidden #showInput { opacity: 1; pointer-events: auto; }
.show-input-label { display: none; }

#cardMenu, #quickMenu {
    position: fixed; background: var(--card-bg); border: 1px solid var(--border); border-radius: 12px;
    padding: 6px; display: none; flex-direction: column; gap: 2px; z-index: 2000;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5); min-width: 180px; max-height: 60vh; overflow-y: auto;
}
#cardMenu.active, #quickMenu.active { display: flex; }
#quickMenu { z-index: 2100; }
.menu-item { 
    display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 6px; 
    cursor: pointer; color: var(--text); background: transparent; border: none; width: 100%; 
    text-align: left; font-size: 14px; transition: background 0.1s;
}
.menu-item:active { background: rgba(255,255,255,0.1); }
.menu-item i { width: 20px; text-align: center; }
.menu-separator { height: 1px; background: var(--border); margin: 4px 0; }

.modal-overlay {
    position: fixed; inset: 0; background: rgba(0,0,0,0.6); backdrop-filter: blur(4px); z-index: 1500;
    display: none; align-items: center; justify-content: center; padding: 20px;
}
.modal-overlay.active { display: flex; }
.modal { background: var(--card-bg); border-radius: 16px; width: 100%; max-width: 600px; max-height: 90vh; border: 1px solid var(--border); display: flex; flex-direction: column; box-shadow: 0 20px 50px rgba(0,0,0,0.5); overflow: hidden; }
.modal-header { padding: 16px 20px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; }
.modal-body { padding: 20px; overflow-y: auto; }
.modal-footer { padding: 16px 20px; border-top: 1px solid var(--border); display: flex; justify-content: flex-end; gap: 12px; }

textarea, input[type="text"], input[type="file"] {
    width: 100%; padding: 12px; border-radius: 8px; border: 1px solid var(--border); background: var(--bg); color: var(--text);
    font-family: inherit; font-size: 15px; resize: vertical; min-height: 120px; margin-bottom: 12px;
}

button.btn { padding: 10px 16px; border-radius: 8px; border: none; cursor: pointer; font-size: 14px; font-weight: 600; transition: all 0.2s; }
.btn-primary { background: var(--primary); color: var(--on-primary, #fff); }
.btn-danger { background: #d32f2f; color: white; }
.btn-ghost { background: transparent; color: var(--text); border: 1px solid var(--border); }

.style-section { margin-bottom: 16px; }
.style-section h4 { font-size: 12px; text-transform: uppercase; opacity: 0.7; margin-bottom: 8px; letter-spacing: 0.5px; }
.color-picker { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.color-picker input { width: 40px; height: 30px; border: none; padding: 0; border-radius: 4px; cursor: pointer; }
.toggle-group { display: flex; gap: 6px; flex-wrap: wrap; }
.toggle-btn { padding: 6px 10px; border: 1px solid var(--border); border-radius: 6px; font-size: 12px; cursor: pointer; background: transparent; color: var(--text); }
.toggle-btn.active { background: var(--primary); color: var(--on-primary, #fff); border-color: var(--primary); }
.slider-group { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.slider-group input { flex: 1; }
.lock-checkbox { display: flex; align-items: center; gap: 8px; margin-top: 12px; padding: 10px; background: rgba(255,255,255,0.05); border-radius: 6px; }

#toast { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%) translateY(100px); background: var(--card-bg); border: 1px solid var(--border); color: var(--text); padding: 10px 16px; border-radius: 20px; font-size: 13px; z-index: 2500; transition: transform 0.3s; opacity: 0; box-shadow: var(--shadow); }
#toast.show { transform: translateX(-50%) translateY(0); opacity: 1; }
/* The toast is a message, not a surface: it sits over the bottom of the screen at z-2500
   even when invisible, and it was swallowing taps meant for whatever was underneath -
   the bar's restore pin most of all. */
#toast, #toast.show { pointer-events: none; }

#emptyState { text-align: center; color: rgba(255,255,255,0.3); margin-top: 50px; font-size: 18px; pointer-events: none; display: flex; flex-direction: column; gap: 10px; align-items: center; }

/* A card that is about a page shows that page, and links out to it. */
.card-shot { display: block; margin: 10px 0 0; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; background: #000; }
.card-shot img { display: block; width: 100%; height: auto; }

/* A reply that is a document keeps its own CSS inside its own frame. */
.doc-shell { margin: 10px 0 0; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; background: #fff; }
.doc-frame { display: block; width: 100%; height: 60vh; min-height: 240px; border: 0; background: #fff; }
.doc-frame-full { height: calc(100dvh - 130px); min-height: 420px; }
/* A card that holds a document is the document, not a card with a document in it:
   the frame fills the card it is given instead of stopping at a fixed slice of
   the viewport, which is what left the page cut short with a blank band under it.
   In list view the card itself is given the screen, so the page scrolls inside
   the frame the way a page should. */
body.view-list .flip-card:has(.doc-frame) { height: calc(100dvh - 160px); min-height: 320px; }
.flip-card:has(.doc-frame) .card-face { overflow: hidden; }
.flip-card:has(.doc-frame) .response-content {
    flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column;
}
.flip-card:has(.doc-frame) .doc-shell {
    flex: 1 1 auto; min-height: 0; margin-top: 0; display: flex; flex-direction: column;
}
.flip-card:has(.doc-frame) .doc-frame { flex: 1 1 auto; height: auto; min-height: 0; }

/* Attachments: what is about to be sent, and what a card was made from. */
#attachBtn, #micBtn {
    background: var(--bg); color: var(--text); border: 1px solid var(--border);
    border-radius: 50%; width: 46px; height: 46px; flex-shrink: 0; cursor: pointer;
    font-size: 15px; display: flex; align-items: center; justify-content: center;
    transition: all 0.2s;
}
#attachBtn:hover, #micBtn:hover { border-color: var(--primary); }
#micBtn.recording { background: #d32f2f; border-color: #d32f2f; color: #fff; animation: pulse-btn 1s infinite; }

/* The same recorder, aimed at a field inside a menu. */
.dictation-btn {
    background: var(--bg); color: var(--text); border: 1px solid var(--border);
    border-radius: 50%; width: 36px; height: 36px; flex-shrink: 0; cursor: pointer;
    font-size: 13px; display: inline-flex; align-items: center; justify-content: center;
    transition: all 0.2s; margin-right: auto;
}
.dictation-btn:hover { border-color: var(--primary); }
.dictation-btn.recording { background: #d32f2f; border-color: #d32f2f; color: #fff; animation: pulse-btn 1s infinite; }

.modal-hint { margin-top: 8px; font-size: 12px; color: #ffb4a2; }

#attachTray {
    position: fixed; left: 0; right: 0; bottom: 70px; z-index: 101;
    padding: 0 12px 8px; display: none; gap: 8px; overflow-x: auto;
    padding-bottom: calc(8px + var(--safe-area-bottom));
}
#attachTray.active { display: flex; }
.attach-chip {
    display: flex; align-items: center; gap: 8px; flex-shrink: 0; max-width: 220px;
    background: var(--card-bg); border: 1px solid var(--border); border-radius: 10px;
    padding: 5px 8px; font-size: 12px; box-shadow: var(--shadow);
}
.attach-chip img { width: 34px; height: 34px; object-fit: cover; border-radius: 6px; display: block; }
.attach-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.attach-remove { background: none; border: none; color: var(--text); opacity: 0.6; cursor: pointer; padding: 2px; }
.attach-remove:hover { opacity: 1; }

.card-attachments { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.card-attachments img { width: 64px; height: 64px; object-fit: cover; border-radius: 8px; border: 1px solid var(--border); display: block; }
.card-attachments a { display: flex; align-items: center; gap: 6px; font-size: 11px; opacity: 0.85; border: 1px solid var(--border); border-radius: 8px; padding: 4px 8px; color: inherit; text-decoration: none; }

@media (max-width: 480px) {
    #attachBtn, #micBtn { width: 40px; height: 40px; }
    #inputPanel { gap: 6px; }
}

/* ─── mini web browser ─── */
.mb-overlay {
    position: fixed;
    inset: 0;
    z-index: 900;
    display: none;
    background: color-mix(in srgb, var(--bg) 82%, transparent);
    backdrop-filter: blur(6px);
}

.mb-overlay.show { display: block; }

.mb-shell {
    position: absolute;
    inset: 3vh 2vw;
    display: flex;
    flex-direction: column;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--card-bg);
    overflow: hidden;
    box-shadow: 0 18px 48px rgba(0, 0, 0, .45);
}

.mb-bar {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 10px;
    border-bottom: 1px solid var(--border);
}

.mb-bar button, .mb-bar a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: transparent;
    color: var(--text);
    cursor: pointer;
    text-decoration: none;
}

.mb-bar button:disabled { opacity: .35; cursor: default; }
.mb-bar button:hover:not(:disabled), .mb-bar a:hover { border-color: var(--primary); }
.mb-bar .mb-go { border-color: color-mix(in srgb, var(--primary) 60%, var(--border)); }

.mb-bar input {
    flex: 1;
    min-width: 0;
    height: 34px;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg);
    color: var(--text);
    font: inherit;
    font-size: 13px;
    outline: none;
}

.mb-bar input:focus { border-color: var(--primary); }

.mb-view { flex: 1; min-height: 0; position: relative; background: #fff; }
.mb-frame { width: 100%; height: 100%; border: 0; display: block; background: #fff; }
.mb-shot { width: 100%; height: 100%; object-fit: contain; object-position: top center; background: var(--bg); }

.mb-note {
    padding: 6px 12px;
    border-top: 1px solid var(--border);
    font-size: 11px;
    opacity: .65;
}

@media (max-width: 700px) {
    .mb-shell { inset: 0; border-radius: 0; border: none; }
}

.mb-text {
    margin: 0;
    padding: 16px 18px;
    height: 100%;
    overflow: auto;
    white-space: pre-wrap;
    word-break: break-word;
    background: var(--card-bg);
    color: var(--text);
    font: 13px/1.65 ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* Floating icons are furniture: drag one and it stays where you put it. */
.fab[data-fab] { touch-action: none; cursor: grab; }
.fab[data-fab].dragging { cursor: grabbing; opacity: 0.85; }
.fab.parked { margin: 0 !important; }

.theme-history { display: flex; flex-direction: column; gap: 8px; max-height: 52vh; overflow-y: auto; }
.theme-row { display: flex; align-items: center; gap: 10px; padding: 11px 12px; border: 1px solid var(--border);
    border-radius: 10px; background: transparent; color: var(--text); cursor: pointer; text-align: left;
    font-size: 13px; font-family: inherit; }
.theme-row:hover { background: rgba(255,255,255,0.06); }
.theme-swatches { display: flex; gap: 3px; margin-left: auto; }
.theme-swatch { width: 14px; height: 14px; border-radius: 50%; border: 1px solid rgba(0,0,0,0.35); }

/* A document on screen: it is paper, so it is white and dark-inked whatever the theme is. */
.modal-wide { max-width: 760px; width: 96vw; }
.template-bar { display: flex; gap: 8px; align-items: center; margin-bottom: 10px; }
.template-bar select { flex: 1; min-width: 0; }
.template-scroll { max-height: 52vh; overflow-y: auto; background: #e9e9ec; padding: 14px; border-radius: 10px; }
.template-paper { background: #ffffff; color: #111; padding: 34px 30px; border-radius: 2px;
    box-shadow: 0 6px 24px rgba(0,0,0,0.25); min-height: 300px; font-size: 14px; }
.template-paper .slot-empty { color: #b9b9b9; }
@media print {
    body > *:not(#templateModal) { display: none !important; }
    #templateModal { position: static; display: block; background: none; }
    #templateModal .modal-header, #templateModal .modal-footer, .template-bar, #templateHint { display: none !important; }
    .template-scroll { max-height: none; overflow: visible; background: none; padding: 0; }
    .template-paper { box-shadow: none; padding: 0; }
}

/* Quiet by design: a row of suggestions must not compete with the palette it changes. */
.style-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0 6px; }
.style-chips button { background: none; border: 1px solid var(--border); color: var(--text); opacity: 0.6;
    font: inherit; font-size: 12px; padding: 5px 10px; border-radius: 999px; cursor: pointer;
    transition: opacity 0.15s; }
.style-chips button:hover { opacity: 1; }

/* The line under the chips explains; it is not an error. */
.modal-hint.style-note { color: var(--text); opacity: 0.6; }

/* The thing that is about to change is the thing that moves. While a palette is being
   made, the theme's name breathes, because the name is what is being rewritten - and the
   same class is there to be put on whatever changes next. */
.thinking-text { animation: thinking-text 1.4s ease-in-out infinite; }
@keyframes thinking-text {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
}
@media (prefers-reduced-motion: reduce) {
    .thinking-text { animation: none; opacity: 0.6; }
}

/* How she read the request, on the request: quiet enough to ignore, there when a
   cached or surprising answer needs explaining. */
.decision-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.decision-chips span { font-size: 10px; letter-spacing: 0.02em; opacity: 0.45;
    border: 1px solid var(--border); border-radius: 999px; padding: 2px 8px; }

/* ─── Ambient: a window over the work, not a drawer beside it ───
   It floats, it is moved by its own bar, and it closes down to a pin. The bar
   and the composer are one surface, so minimizing takes the box away with it. */
#assistPanel {
    position: fixed; left: 12px; top: 120px; z-index: 245;
    display: none; flex-direction: column;
    width: min(380px, calc(100vw - 24px)); height: min(470px, 68dvh);
    background: #171a20; color: #e6e9ef;
    border: 1px solid #2a2f38; border-radius: 14px; overflow: hidden;
    box-shadow: 0 18px 44px rgba(0,0,0,0.5);
    font: 13px/1.55 system-ui, sans-serif;
}
#assistPanel.open { display: flex; }
#assistPanel.dragging, #assistPin.dragging { box-shadow: 0 24px 60px rgba(0,0,0,0.65); }
#assistHead {
    display: flex; align-items: center; gap: 8px; padding: 9px 10px 9px 12px;
    border-bottom: 1px solid #2a2f38; cursor: move; touch-action: none; flex-shrink: 0;
}
#assistHead strong { flex: 1; }
#assistContext { font: 11px/1 system-ui, sans-serif; color: #9aa4b2; white-space: nowrap; }
.assist-hbtn {
    background: none; border: 1px solid #2a2f38; border-radius: 4px; color: #9aa4b2;
    font-size: 11px; padding: 3px 7px; cursor: pointer; touch-action: manipulation;
}
.assist-hbtn:hover { border-color: #4a5568; color: #e6e9ef; }
#assistThread { flex: 1; overflow-y: auto; padding: 10px 12px; min-height: 0; }
/* The composer is inset on the right so the corner grip never sits on send. */
#assistComposer { display: flex; gap: 6px; padding: 10px 22px 10px 12px; border-top: 1px solid #2a2f38; flex-shrink: 0; }
#assistInput {
    flex: 1; resize: none; min-height: 0; margin: 0; padding: 6px 8px;
    background: #0d0d1a; color: inherit; border: 1px solid #2a2f38; border-radius: 6px;
    font: inherit;
}
#assistSend {
    align-self: stretch; padding: 0 12px; border-radius: 6px; border: 1px solid #4a9eff;
    background: #4a9eff22; color: #cfe4ff; font-weight: 600; cursor: pointer;
}
#assistPin {
    position: fixed; left: 14px; top: 300px; z-index: 244;
    width: 44px; height: 44px; padding: 0; border-radius: 50%;
    display: none; align-items: center; justify-content: center;
    border: 1px solid #2a2f38; background: #1e222a; color: #e6e9ef;
    font-size: 15px; cursor: grab; touch-action: none;
    box-shadow: 0 8px 22px rgba(0,0,0,0.45);
}
#assistPin.show { display: flex; }
#assistGrip {
    position: absolute; right: 0; bottom: 0; width: 22px; height: 22px; z-index: 3;
    cursor: nwse-resize; touch-action: none;
}
#assistGrip::after {
    content: ''; position: absolute; right: 5px; bottom: 5px; width: 9px; height: 9px;
    border-right: 2px solid #3a414d; border-bottom: 2px solid #3a414d; border-radius: 0 0 2px 0;
}

import { keyMatches } from './util.js';
import { stateKv, masterKv } from './bindings.js';
import { listCandidates, listStyleCandidates, PROMOTE_AT } from './truth.js';

/**
 * The console is a read-and-curate surface, not a chat route: it lists what is
 * already stored so a pair can be found without remembering its key. Every
 * response here needs ADMIN_KEY, and an unset ADMIN_KEY fails closed — the
 * console would otherwise be the one place that hands out the whole store.
 */

const DEFAULT_LIMIT = 100;
const MAX_LIMIT = 200;
const PREVIEW_CHARS = 240;
const MAX_VALUE_CHARS = 262144;

const ANSWER_FIELDS = ['answer', 'html', 'text', 'content', 'body', 'response', 'truth'];
const QUESTION_FIELDS = ['query', 'input', 'question', 'prompt', 'name'];
const TIME_FIELDS = ['saved', 'savedAt', 'updated', 'updatedAt', 'created', 'createdAt', 'at'];

const KINDS = [
  ['truth:master:', 'master'],
  ['truth:provisional:', 'provisional'],
  ['candidate:', 'candidate'],
  ['style:', 'style'],
  ['decision:', 'decision'],
  ['review:', 'review'],
  ['budget:', 'budget'],
  ['tts:', 'tts'],
  ['upload:', 'upload'],
  ['index:', 'index'],
  ['settings:', 'settings'],
];

/** Admin answers are for one signed-in console, so no cross-origin grant. */
function adminJson(data, init = {}) {
  return new Response(JSON.stringify(data, null, 2), {
    ...init,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      'x-content-type-options': 'nosniff',
      ...(init.headers || {}),
    },
  });
}

const adminFail = (status, code, message) => adminJson({ error: { code, message } }, { status });

/** null means the request may continue; a Response means it stops here. */
export function adminGate(request, env) {
  const secret = String(env?.ADMIN_KEY || '');
  if (!secret) {
    return adminFail(
      503,
      'admin_key_unset',
      'Set the ADMIN_KEY secret (wrangler secret put ADMIN_KEY) before the console can be used.',
    );
  }
  const bearer = (request.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  const provided = request.headers.get('x-admin-key') || bearer || '';
  if (!keyMatches(secret, provided)) {
    return adminFail(401, 'admin_key_required', 'Send the ADMIN_KEY in the x-admin-key header.');
  }
  return null;
}

/**
 * MASTER first, then MEM. Where only MEM is bound the two are the same store, so
 * it is listed once instead of twice.
 */
export function adminStores(env) {
  const out = [];
  const master = masterKv(env);
  const mem = stateKv(env);
  if (master && master !== mem) out.push({ name: 'MASTER', store: master });
  if (mem) out.push({ name: 'MEM', store: mem });
  if (!out.length && master) out.push({ name: 'MEM', store: master });
  return out;
}

function parseValue(raw) {
  if (typeof raw !== 'string') return raw ?? null;
  try {
    return JSON.parse(raw);
  } catch {
    return raw; // a bare string value is the answer itself
  }
}

function answerOf(value) {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return '';
  for (const field of ANSWER_FIELDS) {
    const raw = value[field];
    if (typeof raw === 'string' && raw.trim()) return raw;
  }
  return '';
}

function questionOf(value, key) {
  if (value && typeof value === 'object') {
    for (const field of QUESTION_FIELDS) {
      const raw = value[field];
      if (typeof raw === 'string' && raw.trim()) return raw.trim();
    }
  }
  return key;
}

function kindOf(key) {
  for (const [prefix, kind] of KINDS) if (key.startsWith(prefix)) return kind;
  return 'other';
}

function savedOf(value) {
  if (!value || typeof value !== 'object') return null;
  for (const field of TIME_FIELDS) {
    const raw = value[field];
    if (typeof raw === 'string' && raw.trim()) return raw;
    if (typeof raw === 'number' && Number.isFinite(raw)) {
      const date = new Date(raw < 1e12 ? raw * 1000 : raw);
      return Number.isNaN(date.getTime()) ? String(raw) : date.toISOString();
    }
  }
  return null;
}

function rowFor(store, key, raw) {
  const value = parseValue(raw);
  const answer = answerOf(value);
  return {
    key,
    store,
    kind: kindOf(key),
    question: questionOf(value, key).slice(0, 200),
    preview: answer.replace(/\s+/g, ' ').trim().slice(0, PREVIEW_CHARS),
    chars: answer.length,
    bytes: typeof raw === 'string' ? raw.length : 0,
    hits: Number(value?.hits) || Number(value?.attempts) || 0,
    confidence: typeof value?.confidence === 'number' ? value.confidence : null,
    alternatives: Array.isArray(value?.alternatives) ? value.alternatives.length : 0,
    saved: savedOf(value),
  };
}

function clampLimit(value) {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  if (!Number.isFinite(parsed) || parsed <= 0) return DEFAULT_LIMIT;
  return Math.min(parsed, MAX_LIMIT);
}

function pickStore(env, url) {
  const stores = adminStores(env);
  if (!stores.length) return { error: adminFail(503, 'no_store', 'No KV namespace is bound to this worker.') };
  const wanted = String(url.searchParams.get('store') || stores[0].name).toUpperCase();
  const found = stores.find((entry) => entry.name === wanted);
  if (!found) {
    return {
      error: adminFail(
        404,
        'store_not_found',
        `Unknown store ${wanted}; this deployment has ${stores.map((s) => s.name).join(', ')}.`,
      ),
    };
  }
  return { found, stores };
}

/** Proves the key before the console renders anything. */
export async function adminUnlock(request, env) {
  const gate = adminGate(request, env);
  if (gate) return gate;
  const stores = adminStores(env);
  return adminJson({
    ok: true,
    stores: stores.map((s) => s.name),
    limit: MAX_LIMIT,
    preview: PREVIEW_CHARS,
  });
}

/**
 * One page of the store, values included: a key name alone cannot be curated,
 * and a page of 100 reads stays well inside the per-invocation KV budget.
 */
export async function adminListKeys(request, env, url) {
  const gate = adminGate(request, env);
  if (gate) return gate;

  const { found, stores, error } = pickStore(env, url);
  if (error) return error;
  if (typeof found.store.list !== 'function') {
    return adminFail(503, 'store_unlistable', `${found.name} cannot be listed.`);
  }

  const limit = clampLimit(url.searchParams.get('limit'));
  const cursor = url.searchParams.get('cursor') || undefined;

  let listed;
  try {
    listed = await found.store.list(cursor ? { limit, cursor } : { limit });
  } catch (err) {
    return adminFail(502, 'list_failed', `Could not list ${found.name}: ${err?.message || err}`);
  }

  const names = (listed?.keys || [])
    .map((entry) => entry?.name)
    .filter((name) => typeof name === 'string' && name);

  // The name filter runs before the reads, so a narrow search costs fewer gets.
  const needle = String(url.searchParams.get('q') || '').trim().toLowerCase();
  const matched = needle ? names.filter((name) => name.toLowerCase().includes(needle)) : names;

  const rows = await Promise.all(
    matched.map(async (key) => rowFor(found.name, key, await found.store.get(key).catch(() => null))),
  );

  const next = listed?.list_complete === false ? listed.cursor || null : null;
  return adminJson({
    ok: true,
    store: found.name,
    stores: stores.map((s) => s.name),
    rows,
    cursor: next,
    done: !next,
    listed: names.length,
    matched: matched.length,
    limit,
  });
}

/**
 * The human in the loop. Every answer the pipeline produced is already a
 * candidate; this is the queue, most-repeated first, with the ones that have
 * earned a promotion flagged. It is read-only on purpose: promoting is an edit,
 * and edits go to a truth layer, not to whatever the pipeline happened to say.
 */
export async function adminQueue(request, env, url) {
  const gate = adminGate(request, env);
  if (gate) return gate;

  const limit = clampLimit(url.searchParams.get('limit'));
  const [candidates, styles] = await Promise.all([
    listCandidates(env, { limit }).catch(() => []),
    listStyleCandidates(env, { limit }).catch(() => []),
  ]);

  const rows = candidates.map((entry) => ({
    id: entry?.id || null,
    key: entry?.id ? `candidate:${entry.id}` : null,
    question: String(entry?.query || entry?.input || '').slice(0, 200),
    preview: String(entry?.answer || '').replace(/\s+/g, ' ').trim().slice(0, PREVIEW_CHARS),
    chars: String(entry?.answer || '').length,
    hits: Number(entry?.hits) || 0,
    suggested: Boolean(entry?.suggested) || (Number(entry?.hits) || 0) >= PROMOTE_AT,
    alternatives: Array.isArray(entry?.alternatives) ? entry.alternatives.length : 0,
    preset: entry?.preset || null,
    route: entry?.route || null,
    model: entry?.model || null,
    lastAt: entry?.lastAt || null,
  }));

  // Palettes are not answers to a chat question, so they are listed beside the
  // queue rather than in it. The alternatives travel whole: the point of logging
  // both is being able to read both.
  const styleRows = styles.map((entry) => ({
    key: entry?.id ? `style:${entry.id}` : null,
    question: String(entry?.query || entry?.input || '').slice(0, 200),
    answer: String(entry?.answer || '').slice(0, 2000),
    confidence: typeof entry?.confidence === 'number' ? entry.confidence : null,
    attempts: Number(entry?.attempts) || 0,
    alternatives: (Array.isArray(entry?.alternatives) ? entry.alternatives : []).map((alt) => ({
      answer: String(alt?.answer || '').slice(0, 2000),
      confidence: typeof alt?.confidence === 'number' ? alt.confidence : null,
      count: Number(alt?.count) || 0,
      model: alt?.model || null,
      at: alt?.at || null,
    })),
    preset: entry?.preset || null,
    route: entry?.route || null,
    model: entry?.model || null,
    firstAt: entry?.firstAt || null,
    lastAt: entry?.lastAt || null,
  }));

  return adminJson({
    ok: true,
    promoteAt: PROMOTE_AT,
    total: rows.length,
    ready: rows.filter((row) => row.suggested).length,
    rows,
    styleTotal: styleRows.length,
    styles: styleRows,
  });
}

/** The full value behind one row, for the editor. */
export async function adminReadKey(request, env, url) {
  const gate = adminGate(request, env);
  if (gate) return gate;

  const { found, error } = pickStore(env, url);
  if (error) return error;

  const key = String(url.searchParams.get('name') || '');
  if (!key) return adminFail(400, 'name_required', 'Send ?name=<key>.');
  if (typeof found.store.get !== 'function') {
    return adminFail(503, 'store_unreadable', `${found.name} cannot be read.`);
  }

  const raw = await found.store.get(key).catch(() => null);
  if (raw == null) return adminFail(404, 'key_not_found', `${key} is not in ${found.name}.`);

  const text = String(raw);
  const truncated = text.length > MAX_VALUE_CHARS;
  const body = truncated ? text.slice(0, MAX_VALUE_CHARS) : text;
  return adminJson({
    ok: true,
    store: found.name,
    key,
    chars: text.length,
    truncated,
    raw: body,
    value: parseValue(body),
  });
}

/**
 * ARA first.
 *
 * The same place clef sits — the front of the chat pipeline — except this is the
 * point of contact rather than a router: when the binding is present she must
 * answer, and a refusal, a timeout or no decision stops the request before any
 * model is called.
 *
 * Unbound (tests, local dev) falls through untouched, so nothing that already
 * works starts failing for want of a binding.
 */
export async function askAra(env, text, domain = 'mind', choice = null, stored = null) {
  const binder = env && env.ARA;
  if (!binder || typeof binder.fetch !== 'function') {
    return { ok: true, bound: false, id: null, move: null, route: null };
  }

  try {
    const response = await binder.fetch('https://ara/decide', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        text: String(text || ''),
        domain: 'mind',
        surface: 'mind',
        ...(choice ? { choice } : {}),
        ...(stored ? { stored } : {}),
      }),
      signal: AbortSignal.timeout(8000),
    });
    if (!response.ok) return { ok: false, bound: true, reason: 'ara_status_' + response.status };

    const data = await response.json();
    // She did not understand: the card goes back to him and nothing is generated.
    if (data && data.clarify) {
      return { ok: true, bound: true, clarify: data.clarify, id: data.id ?? null, move: data.move ?? null, route: null, notes: data.notes ?? null };
    }
    if (!data || data.refused || !data.move) return { ok: false, bound: true, reason: 'ara_no_decision' };

    return { ok: true, bound: true, id: data.id ?? null, move: data.move, route: data.route ?? null, notes: data.notes ?? null };
  } catch {
    return { ok: false, bound: true, reason: 'ara_error' };
  }
}

/**
 * What the decision produced. She decides, the run happens, and the row is told
 * what came of it — so her record is not just what she picked.
 */
export async function reportOutcome(env, id, what = {}) {
  const binder = env && env.ARA;
  if (!binder || typeof binder.fetch !== 'function' || id == null) return false;
  try {
    const key = araKey(env);
    const response = await binder.fetch('https://ara/outcome', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(key ? { 'x-admin-key': key } : {}) },
      body: JSON.stringify({
        id,
        returned: what.returned ?? null,
        stored: what.stored ?? null,
        route: what.route ?? null,
        origin: what.origin ?? null,
      }),
      signal: AbortSignal.timeout(2000),
    });
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * The key ARA's journal now asks for. It lives here rather than in a browser
 * prompt: these two calls are machine writes made with nobody watching, and a
 * prompt cannot answer them. A missing key is reported once by ARA (503) and the
 * call degrades to false, which is what the caller already handles.
 */
const araKey = (env) => String((env && (env.ARA_KEY || env.ADMIN_KEY)) || '').trim();

/** His verdict on a decision, in his words, sent to the row that made it. */
export async function sendVerdict(env, { id, correct, correctedTo = null } = {}) {
  const binder = env && env.ARA;
  if (!binder || typeof binder.fetch !== 'function' || id == null || correct == null) return false;
  try {
    const key = araKey(env);
    const response = await binder.fetch('https://ara/feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(key ? { 'x-admin-key': key } : {}) },
      body: JSON.stringify({ id, correct, correctedTo }),
      signal: AbortSignal.timeout(3000),
    });
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * Whisper on Workers AI is happiest with clips around 1 MB. Slicing a WAV is
 * safe because every slice can carry its own 44-byte header, which is not true
 * of webm/opus or mp4/aac — the reason the client re-encodes to 16 kHz WAV
 * before uploading.
 */

export function wavInfo(bytes) {
  if (!bytes || bytes.length < 44) return null;
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const riff = String.fromCharCode(...bytes.subarray(0, 4));
  const wave = String.fromCharCode(...bytes.subarray(8, 12));
  if (riff !== 'RIFF' || wave !== 'WAVE') return null;

  let offset = 12;
  let fmt = null;
  let dataOffset = -1;
  let dataLength = 0;

  while (offset + 8 <= bytes.length) {
    const id = String.fromCharCode(...bytes.subarray(offset, offset + 4));
    const size = dv.getUint32(offset + 4, true);
    if (id === 'fmt ' && offset + 24 <= bytes.length) {
      fmt = {
        channels: dv.getUint16(offset + 10, true),
        rate: dv.getUint32(offset + 12, true),
        bits: dv.getUint16(offset + 22, true),
      };
    } else if (id === 'data') {
      dataOffset = offset + 8;
      dataLength = Math.min(size, bytes.length - dataOffset);
      break;
    }
    offset += 8 + size + (size % 2);
  }

  if (!fmt || dataOffset < 0 || !fmt.channels || !fmt.rate || !fmt.bits) return null;
  const bytesPerSecond = fmt.rate * fmt.channels * (fmt.bits / 8);
  return {
    ...fmt,
    dataOffset,
    dataLength,
    bytesPerSecond,
    seconds: dataLength / bytesPerSecond,
  };
}

export function wrapWav(pcm, { channels = 1, rate = 16000, bits = 16 }) {
  const header = new Uint8Array(44);
  const dv = new DataView(header.buffer);
  const write = (at, text) => {
    for (let i = 0; i < text.length; i += 1) header[at + i] = text.charCodeAt(i);
  };

  write(0, 'RIFF');
  dv.setUint32(4, 36 + pcm.length, true);
  write(8, 'WAVE');
  write(12, 'fmt ');
  dv.setUint32(16, 16, true); // PCM chunk size
  dv.setUint16(20, 1, true); // format: PCM
  dv.setUint16(22, channels, true);
  dv.setUint32(24, rate, true);
  dv.setUint32(28, rate * channels * (bits / 8), true);
  dv.setUint16(32, channels * (bits / 8), true);
  dv.setUint16(34, bits, true);
  write(36, 'data');
  dv.setUint32(40, pcm.length, true);

  const out = new Uint8Array(44 + pcm.length);
  out.set(header, 0);
  out.set(pcm, 44);
  return out;
}

/** Split into sample-aligned chunks of at most `maxSeconds`, each a valid WAV. */
export function wavChunks(bytes, info, maxSeconds = 30) {
  const frameSize = info.channels * (info.bits / 8);
  const maxBytes = Math.floor((maxSeconds * info.bytesPerSecond) / frameSize) * frameSize;
  if (maxBytes <= 0 || info.dataLength <= maxBytes) return [bytes];

  const chunks = [];
  for (let pos = 0; pos < info.dataLength; pos += maxBytes) {
    const length = Math.min(maxBytes, info.dataLength - pos);
    const pcm = bytes.subarray(info.dataOffset + pos, info.dataOffset + pos + length);
    chunks.push(wrapWav(pcm, info));
  }
  return chunks;
}

/**
 * The deployment owns the binding names; the code owns the behaviour.
 *
 * In the `mind` worker the stores are called MEM (Memoria) and BUCKET. The
 * generic KV / R2 names stay supported so the test suite, local dev and any
 * earlier deployment keep working without a config fork.
 */

export const stateKv = (env) => env?.MEM || env?.KV || null;

/**
 * Master truths belong in the namespace named for them. Where only MEM is bound
 * (local dev, the test suite, a single-namespace deployment) they live there
 * instead, so promotion never fails for want of a second binding.
 */
export const masterKv = (env) => env?.MASTER || stateKv(env) || null;

/**
 * Optional: the truth worker itself, as a service binding. It is the store the
 * standalone admin writes to, so the first cache check can ask it the same
 * question the console asks.
 */
export const truthService = (env) => env?.TRUTH || null;
export const objects = (env) => env?.BUCKET || env?.R2 || null;

/**
 * Browser Rendering — the puppeteer host that /api/shot launches. This account
 * names it BROWSER; MYBROWSER (Cloudflare's docs name) still works. It must stay
 * separate from ABROWSER below: a service binding cannot drive puppeteer.
 */
export const browserBinding = (env) => env?.BROWSER || env?.MYBROWSER || null;

/**
 * The agent-browsing worker, which does the reading rather than the rendering.
 * This deployment names it ABROWSER and AGENT-BROWSER; AGENT-BROWSING is the
 * older spelling, and the short one is accepted so a config slip cannot leave the
 * agent unreachable at runtime. The same binding can appear twice — callers get
 * whichever name actually resolved.
 */
export const browsingService = (env) =>
  env?.ABROWSER || env?.ABROSWER || env?.['AGENT-BROWSER'] || env?.['AGENT-BROWSING'] || null;

/** The name the agent binding resolved under, for /api/health. */
export function browsingServiceName(env) {
  if (env?.ABROWSER) return 'ABROWSER';
  if (env?.ABROSWER) return 'ABROSWER';
  if (env?.['AGENT-BROWSER']) return 'AGENT-BROWSER';
  if (env?.['AGENT-BROWSING']) return 'AGENT-BROWSING';
  return null;
}

/** What is actually attached, by its deployed name, for /api/health. */
export function bindingReport(env) {
  return {
    ai: Boolean(env?.AI),
    assets: Boolean(env?.ASSETS),
    // Present only when Browser Rendering is enabled for the account.
    browser: Boolean(browserBinding(env)),
    kv: {
      mem: Boolean(env?.MEM),
      master: Boolean(env?.MASTER),
      legacy: Boolean(env?.KV),
    },
    r2: {
      bucket: Boolean(env?.BUCKET),
      legacy: Boolean(env?.R2),
    },
    // Secrets Store entries are unreadable from outside; the binding is the only
    // thing worth reporting, never what it holds.
    secretsStore: {
      truthPrompt: Boolean(env?.TEP?.get),
    },
    services: {
      agentBrowsing: Boolean(env?.['AGENT-BROWSING']),
      browsing: Boolean(browsingService(env)),
      truth: Boolean(env?.TRUTH),
    },
  };
}

import { utcDay } from './util.js';
import { stateKv } from './bindings.js';

// Per-isolate fallback. Resets whenever the isolate is recycled, which is why
// KV is the real store; this only keeps a single-instance deployment honest.
const memory = new Map();

export function _resetBudget() {
  memory.clear();
}

export function dailyLimit(env) {
  const parsed = Number(env?.DAILY_NEURONS);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 8000;
}

/**
 * Reserve `neurons` against today's per-IP allowance.
 * Soft ceiling: two concurrent requests can both pass, which is acceptable for
 * a personal app and avoids a Durable Object.
 */
export async function charge(env, ip, neurons = 0) {
  const limit = dailyLimit(env);
  const key = `budget:${utcDay()}:${ip}`;
  const amount = Math.max(0, Math.round(neurons));

  const kv = stateKv(env);
  if (kv) {
    const raw = await kv.get(key);
    const used = Number(raw || 0);
    if (used + amount > limit) return { ok: false, used, limit };
    const next = used + amount;
    await kv.put(key, String(next), { expirationTtl: 172800 });
    return { ok: true, used: next, limit };
  }

  const used = memory.get(key) || 0;
  if (used + amount > limit) return { ok: false, used, limit };
  memory.set(key, used + amount);
  return { ok: true, used: used + amount, limit };
}

/**
 * Cookies, kept tiny: one session cookie, HttpOnly, SameSite=Lax, Secure
 * whenever the request arrived over https (so a localhost preview still works).
 * `Secure` on an http origin would be silently dropped by the browser, which
 * looks exactly like a broken login.
 */

export function parseCookies(header) {
  const out = {};
  for (const part of String(header || '').split(';')) {
    const at = part.indexOf('=');
    if (at < 0) continue;
    const name = part.slice(0, at).trim();
    if (!name) continue;
    try {
      out[name] = decodeURIComponent(part.slice(at + 1).trim());
    } catch {
      out[name] = part.slice(at + 1).trim();
    }
  }
  return out;
}

export function cookieValue(request, name) {
  return parseCookies(request?.headers?.get?.('cookie'))[name] || '';
}

export function sessionCookie(name, value, { maxAge, secure = true } = {}) {
  const bits = [`${name}=${encodeURIComponent(value)}`, 'Path=/', 'HttpOnly', 'SameSite=Lax'];
  if (maxAge != null) bits.push(`Max-Age=${Math.max(0, Math.floor(maxAge))}`);
  if (secure) bits.push('Secure');
  return bits.join('; ');
}

export function clearCookie(name, { secure = true } = {}) {
  return sessionCookie(name, '', { maxAge: 0, secure });
}

/** Bearer first, then the cookie: the CLI needs no browser to prove a session. */
export function tokenFrom(request, cookieName) {
  const header = String(request?.headers?.get?.('authorization') || '');
  const bearer = header.replace(/^Bearer\s+/i, '').trim();
  if (bearer && bearer !== header) return bearer;
  return cookieValue(request, cookieName);
}

import { sha256Hex } from './util.js';
import { stateKv, browsingService } from './bindings.js';
import { readPage, firstUrl } from './page.js';
import { resolveTruth, questionOf } from './truth.js';
import { findPreset, DEFAULT_PRESET } from './presets.js';

/**
 * A question that names a page, or asks about the live web, needs the browser
 * whatever she said. Keying the browse stage on the decision alone meant the
 * browser never ran when the decision did not name a page.
 */
const WEB_HINT = /\b(browse|search|look ?up|fetch|scrape|latest|current|today|news|website|web ?page)\b/i;

function webWanted(query) {
  const text = String(query || '');
  return /https?:\/\//i.test(text) || WEB_HINT.test(text);
}

const REVIEW_TTL = 60 * 60 * 24 * 30;

const BROWSE_TIMEOUT_MS = 4000;

/**
 * Per-isolate L1 in front of KV.
 *
 * KV reads are served from an edge cache and a freshly written key can stay
 * invisible for up to 60s, so repeating the same turn immediately misses every
 * time — which looks exactly like "the cache does not work". This layer is a
 * plain module-scope Map because `env` is a per-request object in Workers, so
 * keying by it would give each request its own empty cache. Losing the Map on
 * recycle costs one lookup, never a wrong answer.
 */
const L1 = new Map();
const L1_MAX = 500;

/** Exported for tests: a fresh suite must never inherit a previous decision. */
export function _resetDecisionCache() {
  L1.clear();
}

const DECISION_KEY_VERSION = 2;

/** What was asked, with the differences that carry no meaning removed. */
function normaliseQuestion(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(-2000);
}

/**
 * One row per decision, hit or miss. This is what makes "does the decider save
 * money" answerable: hits cost nothing and say so, misses carry what they cost.
 */
async function noteDecision(kv, entry) {
  if (!kv) return;
  try {
    await kv.put(`decide:${Date.now()}:${Math.random().toString(36).slice(2, 8)}`, JSON.stringify(entry), {
      expirationTtl: 86400,
    });
  } catch {
    /* the record is useful, never required */
  }
}

function cacheHit(cached, via, cacheKey) {
  return {
    ...cached,
    source: 'cache',
    // The trace describes this request. Replaying the cached run's stages would
    // claim browse ran again when it did not; keep that under its own name.
    trace: ['cache:hit'],
    cacheSource: via,
    cachedTrace: cached.trace || [],
    cacheKey,
  };
}

/**
 * Bound any upstream call. Without this a stalled engine holds the whole request
 * open — the client sees a spinner, then a blank card, and never learns why.
 */
export function within(ms, label, run) {
  let timer;
  const expiry = new Promise((_, reject) => {
    timer = setTimeout(() => {
      const err = new Error(`${label} timed out after ${Math.round(ms / 1000)}s`);
      err.code = 'upstream_timeout';
      err.status = 504;
      reject(err);
    }, ms);
  });
  return Promise.race([run(), expiry]).finally(() => clearTimeout(timer));
}

/**
 * Stage 2 — intent, straight from her. A missing binding falls back to the old
 * default rather than failing: no decider is the one case she cannot block on.
 */
const PRESET_ACTIONS = new Set(['truth', 'operator', 'mnl', 'doc', 'micro']);

// Her three results, in mind's own terms: the store's result, a preset, or an
// answer written now.
const RESULT_ACTIONS = { result: 'truth', preset: 'operator', ask: 'operator' };

/** The lane a preset answers in. Cods names this on every card; mind never did. */
function domainOf(presetId) {
  return presetId === 'truth' || presetId === 'doc' ? 'legal' : 'general';
}

function fromAra(ara, presetId) {
  if (!ara || !ara.bound) {
    return { preset: presetId || 'operator', task: 'chat', depth: 'normal', tone: 'plain', source: 'no-decider', domain: null };
  }
  // She picks one of mind's own actions, so there is nothing left to classify:
  // a preset action is that preset, browse is generation with the web read first.
  const action = ara.move || 'operator';
  return {
    preset: presetId || (PRESET_ACTIONS.has(action) ? action : RESULT_ACTIONS[action] || 'operator'),
    task: action === 'style' ? 'style' : action === 'truth' || action === 'result' ? 'chat' : 'generate',
    // Her own domain when she sends one; otherwise the lane the preset belongs to.
    depth: 'normal',
    tone: 'plain',
    source: 'ara',
    domain: ara.domain || null,
  };
}

/**
 * Stage 3 — browse. A missing binding is normal, and a failing one must never
 * take the request down: the intent is still good without the material.
 */
async function browseFor(env, { intent, query, worthy }) {
  if (!worthy) return { skipped: true };

  // ABROWSER is this account's name for the agent-browsing worker.
  const service = browsingService(env);
  const url = firstUrl(query);

  if (service && typeof service.fetch === 'function') {
    try {
      const res = await within(BROWSE_TIMEOUT_MS, 'agent-browsing', () =>
        service.fetch(
          new Request('https://agent-browsing/', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ task: intent.task, query: String(query || '').slice(0, 2000) }),
          }),
        ),
      );
      if (res.ok) {
        const text = (await res.text()).slice(0, 4000);
        if (text.trim()) return { ok: true, text, via: 'service' };
      }
      // A service that answers with nothing useful is not the end of the stage.
      // Whether the named page can still be read is decided below.
      if (!url) return { ok: false, status: res.status, via: 'service' };
      const page = await readPage(env, url);
      return page.ok ? page : { ok: false, status: res.status, error: page.error, via: 'rendering' };
    } catch (err) {
      if (!url) return { ok: false, error: String(err?.message || err), via: 'service' };
      const page = await readPage(env, url);
      return page.ok ? page : { ok: false, error: page.error || String(err?.message || err), via: 'rendering' };
    }
  }

  // No browsing service at all: the named page is still readable here.
  if (url) return readPage(env, url);
  return null;
}

/**
 * Stage 6 — review. Records go to MASTER so a session can be read back later;
 * the payload is capped so a long conversation cannot bloat the namespace.
 */
export async function recordReview(env, ctx, record) {
  const master = env?.MASTER;
  if (!master || typeof master.put !== 'function') return false;

  const at = new Date().toISOString();
  const key = `review:${at}:${crypto.randomUUID().slice(0, 8)}`;
  const write = master.put(key, JSON.stringify({ at, ...record }), { expirationTtl: REVIEW_TTL }).catch(
    () => {},
  );

  if (ctx?.waitUntil) ctx.waitUntil(write);
  else await write;
  return true;
}

/**
 * The decision pipeline, in order:
 *
 *   1. cache    MEM lookup; a hit ends the chain
 *   2. intent   ARA answers: route, depth, tone, web
 *   3. browse   AGENT-BROWSING, only when the intent needs outside material
 *   4. user     hand the intent back so the answer can be built
 *   5. operator the rung it runs on: @preset/operator unless a preset was pinned
 *
 * Stage 6 (review) runs after generation, since it records the answer too.
 */
export async function decide(
  env,
  {
    messages,
    images = [],
    presetId = null,
    allowPreset = true,
    engine = 'cloudflare',
    style = false,
    ara = null,
  } = {},
) {
  const trace = [];

  // The client carries its base prompt inside the user turn, so the question a
  // cache or a curated pair is keyed by has to be lifted out of it.
  const lastUser = questionOf([...messages].reverse().find((m) => m.role === 'user')?.content || '');

  const intent = fromAra(ara, presetId);

  const kv = stateKv(env);
  const memo = kv ? L1 : null;
  // The prompt is part of the question. A decision cached under an older prompt
  // replays an answer the current instructions would never give - which is how a
  // corrected preset came back byte-for-byte until the wording changed. Hashing the
  // text means editing a prompt invalidates its cache without anyone tracking a
  // version by hand.
  // A preset carries its prompt as `system` (src/presets.js); reading `prompt`
  // hashed an empty string, which made the fingerprint a constant and the whole
  // guard useless.
  const promptText = String(findPreset(presetId || DEFAULT_PRESET)?.system || '');
  const promptPrint = (await sha256Hex(promptText)).slice(0, 16);
  // The same question typed twice is the same decision: case, punctuation and
  // spacing are not information, and hashing them turned every near-repeat into a
  // miss. The key carries a version so a change of ladder or schema invalidates
  // every decision at once instead of leaving half of them on the old rules.
  const asked = normaliseQuestion(lastUser);
  const cacheKey = `decision:${await sha256Hex(`${asked}|${images.length}|${presetId || ''}|${promptPrint}|v${DECISION_KEY_VERSION}`)}`;

  // A question that names a page must not be answered from a decision recorded
  // when the browser did not run: replaying it would skip the browser for good,
  // and the model would then say the page could not be retrieved.
  const wantsWeb = webWanted(lastUser);
  // Only a deployment that can browse has a stale-browse problem; with no
  // binding there is nothing to re-run, so the decision stays a plain hit.
  const canBrowse = Boolean(browsingService(env));
  const staleBrowse = (entry) => canBrowse && wantsWeb && !entry?.browse;

  // 1. cache. A promoted truth is the strongest hit there is, so master and
  // provisional are checked before the decision cache. Memory sits in front of KV
  // because a KV read can lag the write that produced it.
  if (kv) {
    // A palette request is routed, never answered: a stored truth is an answer,
    // and serving one here is what handed back the same theme for every vibe.
    // Everything but a palette may take a stored answer, whatever lane she
    // named: he asked for the store to answer again, and a cache that stays out
    // of the way is a cache that misses.
    const truth = style ? null : await resolveTruth(env, lastUser).catch(() => null);
    // A candidate is an answer this pipeline already produced for this exact
    // question, so it is a cache hit too. Dropping it here meant every repeated
    // ask was generated again — and came back with a different answer, which is
    // the one thing a cache exists to prevent. Whether a candidate is good
    // enough to stand in for the ask is decided by the caller (a brief ask only).
    if (truth?.layer === 'master' || truth?.layer === 'provisional' || truth?.layer === 'candidate') {
      return {
        preset: presetId || intent.preset || DEFAULT_PRESET,
        task: intent.task,
        depth: 'normal',
        tone: 'plain',
        source: 'cache',
        trace: ['cache:hit'],
        domain: intent.domain || domainOf(presetId || intent.preset),
        cacheSource: truth.layer,
        truth,
        cacheKey,
      };
    }

    const local = memo?.get(cacheKey);
    if (local && !staleBrowse(local)) return cacheHit(local, 'memory', cacheKey);
    if (local) trace.push('cache:stale_browse');

    try {
      const hit = await kv.get(cacheKey);
      if (hit) {
        const cached = JSON.parse(hit);
        if (!staleBrowse(cached)) {
          memo?.set(cacheKey, cached);
          await noteDecision(kv, { cached: true, via: 'kv', key: cacheKey.slice(0, 32), cost: 0, domain: cached.domain, task: cached.task });
          return cacheHit(cached, 'kv', cacheKey);
        }
        trace.push('cache:stale_browse');
      }
      if (!trace.includes('cache:stale_browse')) trace.push('cache:miss');
    } catch {
      trace.push('cache:error');
    }
  } else {
    trace.push('cache:unbound');
  }

  // 2. intent — already known.
  trace.push(`intent:${intent.source}`);

  // 3. browse
  const browseWanted = Boolean(ara && ara.bound && ara.move === 'browse');
  const worthy = browseWanted || wantsWeb;
  const browse = await browseFor(env, { intent, query: lastUser, worthy });
  const material = browse?.ok ? browse.text : null;
  trace.push(
    browse === null
      ? 'browse:unbound'
      : browse.skipped
        ? 'browse:skipped'
        : browse.ok
          ? 'browse:ok'
          : 'browse:error',
  );

  // 4. user, then 5. the generation rung. A preset is always in effect — truth
  // is the default, not the absence of one — so this never resolves to null.
  const preset =
    presetId || (allowPreset ? intent.preset : null) || (allowPreset ? DEFAULT_PRESET : null);
  trace.push('user:handoff');
  trace.push(`rung:${preset}`);

  const browseStatus =
    browse === null
      ? 'unbound'
      : browse.skipped
        ? 'skipped'
        : browse.ok
          ? `ok:${browse.via || 'service'}`
          : `error:${browse.status ? `http ${browse.status}` : browse.error || 'unknown'}`;

  const decision = {
    ...intent,
    // Recorded on the decision so the request card, ARA's outcome and the
    // cross-project comparison all speak the same word.
    domain: intent.domain || domainOf(preset || intent.preset),
    preset,
    browse: material,
    browseStatus,
    trace,
    cacheKey,
  };

  // Only a decision that got what it went looking for is worth replaying: a
  // browse that ran and failed must be retried, not remembered. An unbound
  // browser is not a failure — there is nothing to retry.
  const cacheable = !worthy || Boolean(material) || browse === null;

  if (memo && cacheable) {
    if (memo.size >= L1_MAX) memo.clear();
    memo.set(cacheKey, decision);
  }
  if (kv && cacheable) {
    try {
      await kv.put(cacheKey, JSON.stringify(decision), { expirationTtl: 3600 });
    } catch {
      /* the cache is an optimisation, never a requirement */
    }
  }

  await noteDecision(kv, {
    cached: false,
    key: cacheKey.slice(0, 32),
    domain: decision.domain || null,
    task: decision.task || null,
    depth: decision.depth || null,
    preset: decision.preset || null,
    model: decision.model || null,
    cost: decision.cost ?? null,
  });

  return decision;
}

import { stateKv } from './bindings.js';

/**
 * Which engine answers: Cloudflare Workers AI first, or OpenRouter only.
 *
 * One switch, one store. A flip in the UI has to apply to every isolate and
 * every browser, so the value lives in MEM rather than in the page, and the
 * request path reads it instead of trusting a per-tab preference.
 *
 * Workers AI is the default because that is how the app has always run and the
 * free neuron allowance is real money; the switch exists for the day it is gone.
 */
export const KEY = 'settings:engine';

export const CLOUDFLARE = 'cloudflare';
export const OPENROUTER = 'openrouter';

/** A KV read can trail the write by up to 60s; re-reading every 10s keeps a flip quick. */
const CACHE_MS = 10000;
let cached = { value: null, at: 0 };

/** Exported for tests: a suite that flips the switch must not leak it into the next. */
export function _resetEngine() {
  cached = { value: null, at: 0 };
}

/** Accepts the JSON the API writes and a bare "on"/"off" set by hand. */
function fromRecord(raw) {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && parsed.cloudflare === false) return OPENROUTER;
    if (parsed && parsed.cloudflare === true) return CLOUDFLARE;
    return null;
  } catch {
    const text = String(raw).trim().toLowerCase();
    if (text === 'off' || text === OPENROUTER) return OPENROUTER;
    if (text === 'on' || text === CLOUDFLARE) return CLOUDFLARE;
    return null;
  }
}

export async function engineFor(env) {
  // An explicit env var wins, for the deployment that never wants the switch.
  if (env?.ENGINE === OPENROUTER) return OPENROUTER;
  if (cached.value && Date.now() - cached.at < CACHE_MS) return cached.value;

  let value = CLOUDFLARE;
  const kv = stateKv(env);
  if (kv) {
    try {
      value = fromRecord(await kv.get(KEY)) || CLOUDFLARE;
    } catch {
      // An unreadable store must not take the app down: the default is the
      // behaviour that shipped, not a silent switch to the paid engine.
      value = CLOUDFLARE;
    }
  }
  cached = { value, at: Date.now() };
  return value;
}

export async function setEngineFor(env, cloudflare) {
  const kv = stateKv(env);
  if (!kv) {
    const err = new Error('The switch needs the MEM KV binding, or it resets with the isolate.');
    err.status = 503;
    err.code = 'no_store';
    throw err;
  }

  const value = cloudflare ? CLOUDFLARE : OPENROUTER;
  await kv.put(KEY, JSON.stringify({ cloudflare: Boolean(cloudflare), at: new Date().toISOString() }));
  // Update this isolate now rather than waiting out the cache window.
  cached = { value, at: Date.now() };
  return value;
}

/** The switch and the binding together: off means no env.AI.run anywhere. */
export const canUseCloudflare = (env, engine) => engine === CLOUDFLARE && Boolean(env?.AI);

/**
 * Turning an uploaded file into text a model can read.
 *
 * A model cannot look inside a PDF or a Word file; it can read text. So uploads
 * are decoded here, at upload time, and the extracted text travels with the
 * prompt. Images are deliberately not decoded — they go to a vision model as an
 * image, which is the whole point of attaching one.
 *
 * Two container formats, no dependencies:
 *   PDF  — content streams are usually `/FlateDecode`, so inflate and read the
 *          `(...) Tj` / `[ ... ] TJ` text operators out of them.
 *   DOCX — a zip; inflate `word/document.xml` and strip the markup.
 * `DecompressionStream` is what makes this possible in a Worker: 'deflate' is
 * zlib-wrapped (PDF), 'deflate-raw' is bare (zip).
 */

/** Longest text worth carrying in a prompt; beyond this it is a liability. */
export const MAX_TEXT = 24000;

const TEXTY = ['text/', 'application/json', 'application/xml', 'application/x-yaml', 'application/javascript'];

const latin1 = (bytes) => {
  let out = '';
  const SLICE = 0x8000;
  for (let i = 0; i < bytes.length; i += SLICE) {
    out += String.fromCharCode.apply(null, bytes.subarray(i, i + SLICE));
  }
  return out;
};

const bytesOf = (text) => {
  const out = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i += 1) out[i] = text.charCodeAt(i) & 0xff;
  return out;
};

function indexOfBytes(hay, needle, from = 0) {
  const start = Math.max(0, from);
  outer: for (let i = start; i <= hay.length - needle.length; i += 1) {
    for (let j = 0; j < needle.length; j += 1) {
      if (hay[i + j] !== needle[j]) continue outer;
    }
    return i;
  }
  return -1;
}

function concatChunks(chunks, total) {
  const out = new Uint8Array(total);
  let at = 0;
  for (const chunk of chunks) {
    out.set(chunk, at);
    at += chunk.length;
  }
  return out;
}

/**
 * Inflate, tolerating junk after the end of the stream.
 *
 * A PDF routinely has a newline between the compressed data and `endstream`, and
 * `DecompressionStream` calls those bytes a fatal error — while the decoded
 * output it already produced is complete and correct. So read chunk by chunk and
 * keep what arrived before the error instead of throwing the page away.
 */
async function inflate(bytes, format = 'deflate') {
  if (typeof DecompressionStream !== 'function') return null;

  let reader;
  try {
    reader = new Blob([bytes]).stream().pipeThrough(new DecompressionStream(format)).getReader();
  } catch {
    return null;
  }

  const chunks = [];
  let total = 0;
  while (true) {
    let step;
    try {
      step = await reader.read();
    } catch {
      break;
    }
    if (step.done) break;
    if (step.value?.length) {
      chunks.push(step.value);
      total += step.value.length;
      // A runaway stream is not worth decoding further.
      if (total > 8 * 1024 * 1024) break;
    }
  }

  return total ? concatChunks(chunks, total) : null;
}

function clip(text) {
  const value = String(text || '').replace(/\u0000/g, '').trim();
  return value.length > MAX_TEXT
    ? { text: `${value.slice(0, MAX_TEXT)}\n\n[truncated at ${MAX_TEXT} characters]`, note: 'truncated' }
    : { text: value, note: undefined };
}

/** A PDF literal string, with the escapes the spec defines. */
function decodeLiteral(raw) {
  let out = '';
  for (let i = 0; i < raw.length; i += 1) {
    const char = raw[i];
    if (char !== '\\') {
      out += char;
      continue;
    }
    const next = raw[(i += 1)];
    if (next === undefined) break;
    if (next === 'n') out += '\n';
    else if (next === 'r') out += '\r';
    else if (next === 't') out += '\t';
    else if (next === 'b') out += '\b';
    else if (next === 'f') out += '\f';
    else if (next === '\n' || next === '\r') {
      /* a line continuation contributes nothing */
    } else if (next >= '0' && next <= '7') {
      let octal = next;
      while (octal.length < 3 && raw[i + 1] >= '0' && raw[i + 1] <= '7') {
        octal += raw[(i += 1)];
      }
      out += String.fromCharCode(parseInt(octal, 8));
    } else out += next;
  }
  return out;
}

function decodeHex(hex) {
  const clean = hex.replace(/[^0-9a-f]/gi, '');
  let out = '';
  for (let i = 0; i + 1 < clean.length; i += 2) {
    out += String.fromCharCode(parseInt(clean.slice(i, i + 2), 16));
  }
  return out;
}

/**
 * Text operators out of one content stream. Positions become newlines and
 * string operators become spaces, which reproduces the line breaks closely
 * enough for a model to read the page.
 */
function textFromContent(content) {
  let out = '';
  let i = 0;

  while (i < content.length) {
    const char = content[i];

    if (char === '(') {
      let depth = 1;
      let j = i + 1;
      let raw = '';
      while (j < content.length && depth > 0) {
        const at = content[j];
        if (at === '\\') {
          raw += at + (content[j + 1] ?? '');
          j += 2;
          continue;
        }
        if (at === '(') depth += 1;
        if (at === ')') {
          depth -= 1;
          if (!depth) break;
        }
        raw += at;
        j += 1;
      }
      out += decodeLiteral(raw);
      i = j + 1;
      continue;
    }

    if (char === '<' && content[i + 1] !== '<') {
      const end = content.indexOf('>', i);
      if (end < 0) break;
      out += decodeHex(content.slice(i + 1, end));
      i = end + 1;
      continue;
    }

    if (content.startsWith('Td', i) || content.startsWith('TD', i) || content.startsWith('T*', i) || content.startsWith('ET', i)) {
      out += '\n';
      i += 2;
      continue;
    }

    if (content.startsWith('Tj', i) || content.startsWith('TJ', i) || content.startsWith("'", i) || content.startsWith('"', i)) {
      out += ' ';
      i += 2;
      continue;
    }

    i += 1;
  }

  return out.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
}

/** Every text-bearing stream in the file, inflated when it says it is Flate. */
export async function pdfText(bytes) {
  const pieces = [];
  const streamMarker = bytesOf('stream');
  const endMarker = bytesOf('endstream');
  let at = 0;

  while (at < bytes.length) {
    const start = indexOfBytes(bytes, streamMarker, at);
    if (start < 0) break;

    // 'endstream' also contains 'stream' — never treat its tail as a header.
    const preceding = latin1(bytes.subarray(Math.max(0, start - 3), start));
    const dict = latin1(bytes.subarray(Math.max(0, start - 400), start));

    let dataStart = start + streamMarker.length;
    if (bytes[dataStart] === 0x0d) dataStart += 1;
    if (bytes[dataStart] === 0x0a) dataStart += 1;

    const end = indexOfBytes(bytes, endMarker, dataStart);
    if (end < 0) break;
    at = end + endMarker.length;

    if (preceding === 'end') continue;

    const raw = bytes.subarray(dataStart, end);
    if (!raw.length) continue;

    if (!/\/FlateDecode|\/Fl\b/.test(dict)) {
      const direct = textFromContent(latin1(raw));
      if (direct) pieces.push(direct);
      continue;
    }

    // The newline before `endstream` is not part of the zlib stream.
    let trimmed = raw.length;
    while (trimmed > 0 && (raw[trimmed - 1] === 0x0a || raw[trimmed - 1] === 0x0d || raw[trimmed - 1] === 0x20)) {
      trimmed -= 1;
    }
    const payload = trimmed ? raw.subarray(0, trimmed) : raw;
    const inflated = (await inflate(payload, 'deflate')) || (await inflate(payload, 'deflate-raw'));
    if (!inflated) continue;
    const text = textFromContent(latin1(inflated));
    if (text) pieces.push(text);
  }

  return pieces.join('\n\n').trim();
}

/** Local file headers of a zip, which is all a docx needs. */
export function zipEntries(bytes) {
  const entries = [];
  const signature = [0x50, 0x4b, 0x03, 0x04];
  let at = 0;

  while (at + 30 <= bytes.length) {
    const start = indexOfBytes(bytes, signature, at);
    if (start < 0) break;
    if (start + 30 > bytes.length) break;

    const view = new DataView(bytes.buffer, bytes.byteOffset + start, 30);
    const method = view.getUint16(8, true);
    const compressedSize = view.getUint32(18, true);
    const nameLength = view.getUint16(26, true);
    const extraLength = view.getUint16(28, true);
    const name = latin1(bytes.subarray(start + 30, start + 30 + nameLength));
    const dataStart = start + 30 + nameLength + extraLength;

    // A zero size means the length sits after the data; without it the next
    // header cannot be found reliably, so stop rather than guess.
    if (!compressedSize || dataStart + compressedSize > bytes.length) break;

    entries.push({ name, method, data: bytes.subarray(dataStart, dataStart + compressedSize) });
    at = dataStart + compressedSize;
  }

  return entries;
}

function xmlToText(xml) {
  return xml
    .replace(/<w:tab[^>]*\/>/g, '\t')
    .replace(/<w:br[^>]*\/>/g, '\n')
    .replace(/<\/w:p>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export async function docxText(bytes) {
  const entry = zipEntries(bytes).find((item) => item.name === 'word/document.xml');
  if (!entry) return '';
  const bytesOut = entry.method === 8 ? await inflate(entry.data, 'deflate-raw') : entry.data;
  if (!bytesOut) return '';
  return xmlToText(latin1(bytesOut));
}

/** XML entities, unescaped in the one order that cannot double-decode. */
function unescapeXml(text) {
  return String(text || '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&amp;/g, '&');
}

/** Every text run in document order, with no markup left behind. */
function textRuns(xml, tag) {
  const out = [];
  const re = new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)</${tag}>`, 'g');
  let match;
  while ((match = re.exec(xml))) {
    const value = unescapeXml(match[1].replace(/<[^>]+>/g, '')).replace(/\s+/g, ' ').trim();
    if (value) out.push(value);
  }
  return out;
}

/** Inflate one zip entry and return it as latin1 text. */
async function entryText(entries, name) {
  const entry = entries.find((item) => item.name === name);
  if (!entry) return '';
  const raw = entry.method === 8 ? await inflate(entry.data, 'deflate-raw') : entry.data;
  return raw ? latin1(raw) : '';
}

/** Slide decks and workbooks are zipped XML, like docx. Order is by filename. */
const numbered = (names) =>
  names.sort((a, b) => {
    const left = Number((a.match(/(\d+)\.xml$/) || [])[1] || 0);
    const right = Number((b.match(/(\d+)\.xml$/) || [])[1] || 0);
    return left - right;
  });

/**
 * XLSX: shared strings hold every text cell, sheets hold indices into them.
 * Without the shared-strings table a sheet reads as a grid of numbers.
 */
export async function xlsxText(bytes) {
  const entries = zipEntries(bytes);

  const shared = [];
  const table = await entryText(entries, 'xl/sharedStrings.xml');
  for (const item of table.match(/<si>[\s\S]*?<\/si>/g) || []) {
    shared.push(textRuns(item, 't').join(''));
  }

  const sheets = numbered(
    entries.map((item) => item.name).filter((name) => /^xl\/worksheets\/sheet\d+\.xml$/.test(name)),
  );

  const blocks = [];
  for (const [index, name] of sheets.entries()) {
    const xml = await entryText(entries, name);
    if (!xml) continue;

    const rows = [];
    for (const row of xml.match(/<row[\s\S]*?<\/row>/g) || []) {
      const cells = [];
      for (const cell of row.match(/<c[\s\S]*?<\/c>/g) || []) {
        const type = (cell.match(/ t="([^"]+)"/) || [])[1] || '';
        let value = '';
        if (type === 's') {
          const at = Number((cell.match(/<v>(\d+)<\/v>/) || [])[1]);
          value = Number.isFinite(at) ? shared[at] || '' : '';
        } else if (type === 'inlineStr') {
          value = textRuns(cell, 't').join(' ');
        } else {
          value = unescapeXml((cell.match(/<v>([\s\S]*?)<\/v>/) || [])[1] || '').trim();
        }
        if (value) cells.push(value.replace(/\s+/g, ' '));
      }
      if (cells.length) rows.push(cells.join(' | '));
    }
    if (rows.length) blocks.push(`Sheet ${index + 1}:\n${rows.join('\n')}`);
  }

  return blocks.join('\n\n').trim();
}

/** PPTX: one XML per slide; `<a:t>` is the only element that carries words. */
export async function pptxText(bytes) {
  const entries = zipEntries(bytes);
  const slides = numbered(
    entries.map((item) => item.name).filter((name) => /^ppt\/slides\/slide\d+\.xml$/.test(name)),
  );

  const blocks = [];
  for (const [index, name] of slides.entries()) {
    const xml = await entryText(entries, name);
    if (!xml) continue;
    const runs = [];
    const re = /<a:t(?:\s[^>]*)?>([\s\S]*?)<\/a:t>/g;
    let match;
    while ((match = re.exec(xml))) {
      const value = unescapeXml(match[1]).trim();
      if (value) runs.push(value);
    }
    if (runs.length) blocks.push(`Slide ${index + 1}:\n${runs.join('\n')}`);
  }

  return blocks.join('\n\n').trim();
}

export const isImageType = (type) => /^image\//i.test(String(type || ''));

/**
 * The one entry point: bytes plus a declared type in, `{ kind, text }` out.
 * Never throws — an unreadable file is a file with no text, not a failed upload.
 */
export async function extractText(bytes, contentType) {
  const type = String(contentType || '')
    .toLowerCase()
    .split(';')[0]
    .trim();

  if (!bytes || !bytes.length) return { kind: 'empty', text: '' };
  if (isImageType(type)) return { kind: 'image', text: '' };

  const looksPdf = type === 'application/pdf' || latin1(bytes.subarray(0, 4)) === '%PDF';
  if (looksPdf) {
    const text = await pdfText(bytes).catch(() => '');
    const { text: clipped, note } = clip(text);
    return {
      kind: 'pdf',
      text: clipped,
      note: note || (clipped ? undefined : 'no text layer — the page is probably a scan'),
    };
  }

  const looksZip = bytes[0] === 0x50 && bytes[1] === 0x4b;
  if (type.includes('wordprocessingml') || (looksZip && type.includes('docx'))) {
    const text = await docxText(bytes).catch(() => '');
    const { text: clipped, note } = clip(text);
    return { kind: 'docx', text: clipped, note: note || (clipped ? undefined : 'no readable text') };
  }

  // Spreadsheets and slide decks are zips as well, so the same reader opens
  // them: a workbook yields cell text, a deck yields slide text.
  const office = async (kind, missing) => {
    const text = kind === 'xlsx' ? await xlsxText(bytes).catch(() => '') : await pptxText(bytes).catch(() => '');
    const { text: clipped, note } = clip(text);
    return { kind, text: clipped, note: note || (clipped ? undefined : missing) };
  };

  if (type.includes('spreadsheetml') || type.includes('ms-excel') || (looksZip && type.includes('xlsx'))) {
    return office('xlsx', 'no readable cells');
  }
  if (type.includes('presentationml') || type.includes('ms-powerpoint') || (looksZip && type.includes('pptx'))) {
    return office('pptx', 'no readable slides');
  }

  // A plain .zip (or an unknown type sent as octet-stream) is still worth a
  // look: sniff the container instead of declaring it unreadable.
  if (looksZip) {
    const names = zipEntries(bytes).map((item) => item.name);
    if (names.some((name) => name.startsWith('xl/'))) return office('xlsx', 'no readable cells');
    if (names.some((name) => name.startsWith('ppt/'))) return office('pptx', 'no readable slides');
  }

  if (TEXTY.some((prefix) => type.startsWith(prefix))) {
    const { text, note } = clip(latin1(bytes));
    return { kind: 'text', text, note };
  }

  return { kind: 'binary', text: '', note: 'no text extracted from this type' };
}

