  '@cf/zai-org/glm-5.3-flash',
  '@cf/deepseek-ai/deepseek-v4.1-flash-1017',
  '@cf/meta/llama-3.2-11b-vision-instruct',
]);

const MAX_MESSAGES_CHARS = 200000;
const MAX_IMAGES = 4;
const MAX_AUDIO_BYTES = 12 * 1024 * 1024;
const MAX_TTS_CHARS = 2000;

/**
 * An idle budget, restarted on every chunk: a slow but flowing answer survives,
 * a dead one becomes an error naming the model instead of a 58-second silence.
 */
// A slow model can go quiet mid-answer for far longer than 15s; treating that as
// a stall killed the stream and left the card cut off wherever it got to.
const STREAM_IDLE_MS = 45000;
/** How long opening a connection — not answering — may take. */
const UPSTREAM_OPEN_MS = 20000;

export default {
  async fetch(request, env, ctx = {}) {
    const url = new URL(request.url);

    if (request.method === 'OPTIONS') return options();

    /**
     * Remove one stored row. Narrow on purpose: one id, one layer, no listing,
     * no wildcards - a poisoned answer is deleted, the store is not cleared.
     * Truth holds the write key; this route only decides who may ask.
     */
    if (url.pathname === '/api/truth/purge' && request.method === 'POST') {
      let ask = {};
      try {
        ask = await request.json();
      } catch {
        return fail(400, 'invalid_json', 'Send { id, layer }.');
      }
      const id = String(ask.id || '').trim();
      const layer = String(ask.layer || 'provisional').trim().toLowerCase();
      if (!id || id.length > 200) return fail(400, 'id_required', 'Send the id of the row to remove.');
      if (layer !== 'master' && layer !== 'provisional') {
        return fail(400, 'layer_invalid', 'layer must be master or provisional.');
      }
      const owner = await sessionUser(request, env);
      const adminKey = String(env.ADMIN_KEY || '');
      const bearer = String(request.headers.get('x-admin-key') || '');
      const named = loginEnabled(env) ? Boolean(owner) : false;
      const keyed = adminKey && bearer.length === adminKey.length && bearer === adminKey;
      if (!named && !keyed) {
        return fail(401, 'sign_in_required', loginEnabled(env)
          ? 'Sign in to remove a stored row.'
          : 'Send ADMIN_KEY in x-admin-key, or configure login.');
      }
      if (!adminKey) return fail(503, 'admin_not_configured', 'The store key is not set on this deployment.');
      const truth = env.TRUTH;
      if (!truth || typeof truth.fetch !== 'function') {
        return fail(503, 'truth_unbound', 'No truth binding on this deployment.');
      }
      let status = 0;
      let payload = null;
      try {
        const res = await truth.fetch(`https://truth/api/truth/${layer}/delete`, {
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-admin-key': adminKey },
          body: JSON.stringify({ id }),
          signal: AbortSignal.timeout(8000),
        });
        status = res.status;
        payload = await res.json().catch(() => null);
      } catch (err) {
        return fail(502, 'purge_failed', `Truth did not answer (${err.message}).`);
      }
      const ok = status >= 200 && status < 300 && payload && payload.success !== false;
      const store = stateKv(env);
      if (store) {
        await store
          .put(`purge:${Date.now()}`, JSON.stringify({
            id,
            layer,
            actor: owner || (keyed ? 'admin-key' : 'anonymous'),
            ok,
            status,
            at: new Date().toISOString(),
          }))
          .catch(() => null);
      }
      if (!ok) return fail(502, 'purge_rejected', `Truth answered ${status}.`, { truth: payload });
      return json({ ok: true, id, layer, status, deleted: payload?.deleted || [] });
    }

    if (url.pathname === '/api/verdict' && request.method === 'POST') {
      let verdict = {};
      try {
        verdict = await request.json();
      } catch {
        return fail(400, 'invalid_json', 'Send { id, correct, correctedTo }.');
      }
      // A challenge is a person disagreeing, so it needs a person. Reading mind
      // stays open; only the correction is gated, and only when login exists.
      const gated = loginEnabled(env);
      const actor = await sessionUser(request, env);
      if (gated && !actor) {
        return fail(401, 'sign_in_required', 'Sign in to correct her: a correction carries a name.');
      }
      const sent = await sendVerdict(env, {
        id: verdict.id,
        correct: verdict.correct,
        correctedTo: verdict.correctedTo ?? null,
      });
      if (!sent) return fail(502, 'verdict_failed', 'Her row did not take the verdict.');
      // Her schema has no field for this, so the attribution is kept here: a
      // correction that cannot say who made it cannot be reviewed later.
      const kv = stateKv(env);
      if (kv) {
        await kv
          .put(`verdict:${Date.now()}:${verdict.id}`, JSON.stringify({
            id: verdict.id,
            actor: actor || 'anonymous',
            correct: !!verdict.correct,
            correctedTo: verdict.correctedTo ?? null,
            at: new Date().toISOString(),
          }))
          .catch(() => null);
      }
      return json({ ok: true, id: verdict.id, actor: actor || 'anonymous', correct: !!verdict.correct, correctedTo: verdict.correctedTo ?? null });
    }

    if (url.pathname.startsWith('/api/')) {
      try {
        return await route(request, env, ctx, url);
      } catch (err) {
        const status = err?.status || 500;
        return fail(status, err?.code || 'internal_error', err?.message || String(err));
      }
    }

    if (url.pathname.startsWith('/f/')) return serveObject(env, url.pathname.slice(3));

    // Static assets answer a POST to "/" with a bare 405, which reads as the
    // whole app being down. Name the route that was actually wanted instead.
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return fail(405, 'wrong_route', `${request.method} ${url.pathname} is not an endpoint; chat is POST /api/chat.`);
    }

    if (env?.ASSETS?.fetch) {
      const asset = await env.ASSETS.fetch(request);
      // The client is the app: a cached script.js meant a fix landed on the
      // worker and never ran in the browser that asked for it.
      if (/\.(js|html|css)$/.test(url.pathname)) {
        const copy = new Response(asset.body, asset);
        copy.headers.set('cache-control', 'no-store, must-revalidate');
        return copy;
      }
      return asset;
    }
    return new Response('Not found', { status: 404 });
  },
};

async function route(request, env, ctx, url) {
  const method = request.method;
  const path = url.pathname;

  if (path === '/api/health' && method === 'GET') return health(env);
  if (path === '/api/presets' && method === 'GET') return json({ presets: publicPresets() });
  if (path === '/api/chat' && method === 'POST') return chat(request, env, ctx);
  // A co-pilot beside the canvas: it answers about the loaded work, and never
  // touches the store, the decision system or the card pipeline.
  if (path === '/api/assist' && method === 'POST') return assist(request, env, ctx);
  if (path === '/api/copilot' && method === 'POST') return assist(request, env, ctx);
  // The shape the proxies' last rung posts; an alias of the same pipeline.
  if (path === '/api/generate' && method === 'POST') return generate(request, env, ctx);
  if (path === '/api/stt' && method === 'POST') return stt(request, env);
  if (path === '/api/tts' && method === 'GET') return tts(url, env, ctx);
  if (path === '/api/upload' && method === 'POST') return upload(request, env);
  if (path === '/api/engine' && method === 'GET') return engineView(env);
  if (path === '/api/engine' && method === 'POST') return switchEngine(request, env);
  // Login state lives in a Durable Object, one per user name.
  if (path === '/api/login' && method === 'POST') return loginRoute(request, env);
  if (path === '/api/logout' && method === 'POST') return logoutRoute(request, env);
  if (path === '/api/session' && method === 'GET') return sessionRoute(request, env);
  // Headless screenshots. Billed per browser-second, so one page, one shot, closed.
  if (path === '/api/shot' && method === 'GET') return shot(url, env, ctx);
  // The same page as words: what the mini browser's text mode shows, and what an
  // agent reads when a question names a URL. One launch, one close, capped text.
  if (path === '/api/page' && method === 'GET') {
    const page = await readPage(env, url.searchParams.get('url') || '');
    return json(page, { status: page.ok ? 200 : 400 });
  }

  // The console reads the store; it still cannot write one. Every route below
  // needs ADMIN_KEY, and an unset key fails closed rather than open.
  if (path === '/api/admin/unlock' && method === 'POST') return adminUnlock(request, env);
  if (path === '/api/admin/keys' && method === 'GET') return adminListKeys(request, env, url);
  if (path === '/api/admin/key' && method === 'GET') return adminReadKey(request, env, url);
  if (path === '/api/admin/queue' && method === 'GET') return adminQueue(request, env, url);

  return fail(404, 'not_found', `No route for ${method} ${path}`);
}

async function health(env) {
  const kv = stateKv(env);
  const bucket = objects(env);
  const engine = await engineFor(env);
  const useCf = canUseCloudflare(env, engine);

  return json({
    ok: true,
    service: 'mind',
    version: '1.3.1',
    engine: {
      workersAI: has(env, 'AI'),
      openrouterKey: has(env, 'OPENROUTER_API_KEY'),
      // The switch. "openrouter" means no Workers AI call is made at all.
      active: engine,
      cloudflare: useCf,
    },
    bindings: bindingReport(env),
    // Which prompt the Truth preset actually runs, and a hash of it: enough to
    // tell the store's text from the built-in copy without publishing either.
    truthPrompt: await truthPromptInfo(),
    models: {
      text: cf.TEXT_MODEL,
      asr: cf.ASR_MODEL,
      tts: cf.TTS_MODEL,
      openrouter: env.OPENROUTER_MODEL || or.DEFAULT_MODEL,
      // What answers when the switch is off.
      openrouterFree: or.freeModelFor(env),
      // On the OpenRouter rung these resolve to @preset/<slug> instead.
      openrouterPresets: openRouterBackedPresets(),
    },
    // Features disable themselves rather than failing the whole service.
    features: {
      chat: useCf || has(env, 'OPENROUTER_API_KEY'),
      stt: useCf || has(env, 'OPENROUTER_API_KEY'),
      tts: useCf || has(env, 'OPENROUTER_API_KEY'),
      uploads: Boolean(bucket),
      ttsCache: Boolean(bucket) || typeof caches !== 'undefined',
      // False means the budget is per-isolate and resets; see wrangler.jsonc.
      sharedBudget: Boolean(kv),
      decisionCache: Boolean(kv),
      // Candidates are recorded in MEM; truth records are seeded out of band.
      truth: Boolean(kv),
      // Browser Rendering is opt-in: no binding, no /api/shot.
      screenshots: Boolean(browserBinding(env)),
      // The agent-browsing service, by whichever name this deployment gave it.
      agentBrowse: browsingServiceName(env),
      // Uploads are stored in R2; documents are read as text on the way in.
      documents: Boolean(bucket),
      // Login needs both the Durable Object and the shared password.
      login: Boolean(sessionsBinding(env)) && has(env, 'LOGIN_PASSWORD'),
    },
  });
}

/** What the switch reads as, without exposing the store. */
async function engineView(env) {
  const engine = await engineFor(env);
  return json({
    ok: true,
    engine,
    cloudflare: canUseCloudflare(env, engine),
    bound: {
      ai: has(env, 'AI'),
      openrouter: has(env, 'OPENROUTER_API_KEY'),
      store: Boolean(stateKv(env)),
    },
  });
}

/**
 * The engine switch changes how the app spends money, so an unset KEY fails
 * closed rather than open.
 */
function keyGate(request, env) {
  const secret = String(env?.KEY || '');
  if (!secret) {
    return fail(
      503,
      'key_unset',
      'Set the KEY secret (wrangler secret put KEY) before the switch can be used.',
    );
  }
  const bearer = (request.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  const provided = request.headers.get('x-engine-key') || bearer;
  if (!keyMatches(secret, provided)) {
    return fail(401, 'key_required', 'Send the KEY in the x-engine-key header.');
  }
  return null;
}

async function switchEngine(request, env) {
  // This is the one route that changes how the app spends money, so it is the
  // one route with a gate. An unset KEY fails closed rather than open.
  const denied = keyGate(request, env);
  if (denied) return denied;

  const body = await request.json().catch(() => null);
  if (!body || typeof body.cloudflare !== 'boolean') {
    return fail(400, 'cloudflare_required', 'Send { cloudflare: true | false }.');
  }
  // Turning Cloudflare off with no key to fall back to would leave the app
  // answering nothing, which is a worse outcome than a loud refusal.
  if (!body.cloudflare && !has(env, 'OPENROUTER_API_KEY')) {
    return fail(
      409,
      'no_openrouter_key',
      'OPENROUTER_API_KEY is not set, so Cloudflare cannot be turned off.',
    );
  }

  const engine = await setEngineFor(env, body.cloudflare);
  return json({ ok: true, engine, cloudflare: canUseCloudflare(env, engine) });
}

function normalizeMessages(raw) {
  const messages = [];
  const images = [];

  for (const message of raw) {
    if (!message || typeof message !== 'object') continue;
    const role = ['system', 'user', 'assistant'].includes(message.role) ? message.role : 'user';

    if (typeof message.content === 'string') {
      messages.push({ role, content: message.content });
      continue;
    }

    if (Array.isArray(message.content)) {
      let text = '';
      for (const part of message.content) {
        if (!part) continue;
        if (part.type === 'text') text += part.text || '';
        else if (part.type === 'image_url') {
          const url = typeof part.image_url === 'string' ? part.image_url : part.image_url?.url;
          if (url) images.push(url);
        }
      }
      messages.push({ role, content: text });
    }
  }

  return { messages, images };
}

/** Task -> model. Used when clef decides, rather than the user pinning a preset. */
const TASK_CF = {
  chat: '@cf/google/gemma-4-26b-a4b-it',
  transform: '@cf/qwen/qwen3.8-27b',
  generate: '@cf/google/gemma-4-26b-a4b-it',
  extract: '@cf/qwen/qwen3.8-27b',
  compare: '@cf/qwen/qwen3.8-27b',
};

/** The depth the decision model reports becomes an output budget. */
const DEPTH_TOKENS = { terse: 1024, deep: 8192 };

/**
 * The output budget is a floor, not a ceiling. A "terse" classification used to
 * cap the answer at 1024 tokens whatever preset was in force, which cut long
 * reports off mid-sentence; depth may now widen an answer but never narrow it.
 */
// An ask that names a length cannot be answered by one stored sentence, however
// good that sentence is. Matched against the user's own words so a cache hit
// never stands in for a report.
const ASKS_FOR_LENGTH =
  /\b(?:essays?|reports?|articles?|dissertations?|theses|step[- ]by[- ]step|in detail|detailed|comprehensive|exhaustive|long[- ]form|blog posts?)\b|\b\d{1,4}\b[^.!?]{0,24}\b(?:paragraphs?|words?|bullets?|points?|steps?|sentences?|pages?|sections?|items?|lines?)\b|\b(?:two|three|four|five|six|seven|eight|nine|ten|twenty|thirty|forty|fifty)\b[^.!?]{0,12}\b(?:paragraphs?|words?|bullets?|points?|steps?|sentences?|pages?|sections?|items?)\b/i;

function budgetFor(preset, decision) {
  const depth = DEPTH_TOKENS[decision?.depth] ?? 0;
  const cap = preset?.maxTokens ?? 0;
  return Math.max(depth, cap) || null;
}

/** An ask that names a length gets a long-answer budget whatever the preset says. */
function budgetForAsk(preset, decision, ask) {
  const budget = budgetFor(preset, decision);
  if (!ASKS_FOR_LENGTH.test(String(ask || ''))) return budget;
  return Math.max(budget ?? 0, DEPTH_TOKENS.deep);
}

function pickCfModel(preset, images, { decision, explicit } = {}) {
  // clef first: with nothing pinned, its task picks the model and the preset only
  // supplies the prompt. A pinned preset overrides both.
  const chosen = explicit ? preset?.cf : TASK_CF[decision?.task] || preset?.cf;
  const model = chosen || cf.TEXT_MODEL;
  if (!images.length) return model;
  return VISION_CF.has(model) ? model : cf.TEXT_MODEL;
}

/** The provider ladder: Cloudflare first, OpenRouter when CF cannot serve it. */
async function openUpstream(
  env,
  { messages, images, preset, decision, explicit, allowCloudflare = true, freeRouter = false, presetPinned = false, ask = '' },
) {
  const failures = [];

  if (allowCloudflare && has(env, 'AI')) {
    const model = pickCfModel(preset, images, { decision, explicit });
    try {
      const stream = await within(UPSTREAM_OPEN_MS, `workers-ai ${model}`, () =>
        cf.streamChat(env, {
          model,
          messages,
          images,
          temperature: preset?.temperature,
          maxTokens: budgetForAsk(preset, decision, ask),
        }),
      );
      return { route: 'workers-ai', model, stream, extract: fromWorkersAI };
    } catch (err) {
      failures.push(`workers-ai: ${err?.message || err}`);
    }
  }

  if (has(env, 'OPENROUTER_API_KEY')) {
    // A referenced OpenRouter preset owns its model, prompt and sampling params.
    // Request fields shallow-merge over preset fields, so sending ours here
    // would override the configuration the preset exists to hold.
    // Only the switch sends traffic to the free router, and only for a request
    // that did not pin a preset. A deployment with no AI binding is not the same
    // thing: OpenRouter is its only engine, so it keeps the presets and the paid
    // model it always had. A preset he picked keeps its own model - Doc is the
    // document model, not whatever free router happens to be serving.
    const freeOnly = Boolean(freeRouter) && !presetPinned;
    const usesPreset = !freeOnly && Boolean(preset?.orPreset);
    const model = freeOnly ? or.freeModelFor(env) : or.modelFor(env, preset);
    // A prompt that came from the secret store is the single source of truth, so
    // it travels with the request and overrides the preset's own system turn.
    // OpenRouter shallow-merges messages over the preset, which is exactly the
    // intent here; the preset still supplies the model and sampling params.
    // Prompts written for one provider keep the old behaviour and are stripped.
    const ownPrompt = usesPreset && preset?.systemFrom === 'code' && preset?.system;
    const base =
      usesPreset && !ownPrompt ? messages.filter((message) => message.role !== 'system') : messages;
    const payload = base.map((message, index) =>
      index === base.length - 1 && images.length
        ? { ...message, content: or.withImages(message.content, images) }
        : message,
    );
    const res = await within(UPSTREAM_OPEN_MS, `openrouter ${model}`, () =>
      or.chat(env, {
        model,
        messages: payload,
        temperature: usesPreset ? undefined : preset?.temperature,
        maxTokens: usesPreset ? undefined : preset?.maxTokens,
      }),
    );
    return { route: 'openrouter', model, stream: res.body, extract: fromOpenRouterChat };
  }

  const switchedOff = allowCloudflare ? '' : ' Cloudflare is switched off and OPENROUTER_API_KEY is unset.';
  const err = new Error(
    `No usable engine.${switchedOff} ${failures.join('; ') || 'Bind AI or set OPENROUTER_API_KEY.'}`,
  );
  err.code = 'no_engine';
  err.status = 503;
  throw err;
}

/** "0 frames" and "3 frames with keys choices" point at different faults. */
function describeEmpty(frames, shape) {
  if (!frames) return 'the stream carried no frames';
  return `${frames} frame${frames === 1 ? '' : 's'} with keys ${shape || 'unknown'}`;
}

/** An in-stream provider failure still needs to reach the caller as an error. */
function explain(problem) {
  const err = new Error(problem);
  err.code = 'upstream_error';
  err.status = 502;
  return err;
}

/**
 * Stage 3 is material, not decoration: whatever the browser found becomes its own
 * system turn, ahead of the question. Without this the browse stage ran, logged
 * `browse:ok`, and the model answered as if it had never happened.
 */
function withBrowse(messages, decision) {
  const material = typeof decision?.browse === 'string' ? decision.browse.trim() : '';
  if (!material) return messages;

  const note = {
    role: 'system',
    content: `Browsing material gathered for this request. Use it as the source for the answer and cite any URLs it contains:\n\n${material}`,
  };
  let at = 0;
  while (at < messages.length && messages[at].role === 'system') at += 1;
  return [...messages.slice(0, at), note, ...messages.slice(at)];
}

/**
 * Her notes, as a system turn. She decides and writes nothing: the answer is
 * generated, through orproxy and ai-proxy, so the record she decided from has to
 * reach the model that writes — otherwise it reads the ask with no history.
 */
function withNotes(messages, notes) {
  const text = typeof notes === 'string' ? notes.trim() : '';
  if (!text) return messages;

  const note = {
    role: 'system',
    content:
      'The decision record for this surface, kept by ARA. It is what he has accepted and rejected, and what has come back before. Read the ask as he means it in light of it. It is context, not a source to quote.\n\n' +
      text,
  };
  let at = 0;
  while (at < messages.length && messages[at].role === 'system') at += 1;
  return [...messages.slice(0, at), note, ...messages.slice(at)];
}

/**
 * What he has taught, as a system turn of its own.
 *
 * The ladder is already ordered when TEW assembles it — his own rules, then the
 * domain rules, then what chat learned — so this hands over that ordering whole
 * rather than a list this worker would have to rank again.
 */
function withLearned(messages, hint) {
  const text = typeof hint === 'string' ? hint.trim() : '';
  if (!text) return messages;

  const note = {
    role: 'system',
    content:
      'What this user has taught, from the learning ladder every tool shares. The order is the authority: his own rules outrank the domain rules, and both outrank anything learned in chat. Follow it unless he contradicts it in this conversation.\n\n' +
      text,
  };
  let at = 0;
  while (at < messages.length && messages[at].role === 'system') at += 1;
  return [...messages.slice(0, at), note, ...messages.slice(at)];
}

/** The review record: enough to reconstruct a session, capped so KV stays small. */
function reviewOf({ preset, decision, route, model, lastUser, text }) {
  return {
    preset: preset?.id ?? null,
    task: decision?.task,
    route,
    model,
    charsIn: String(lastUser).length,
    charsOut: String(text).length,
    prompt: String(lastUser).slice(0, 500),
    answer: String(text).slice(0, 1500),
  };
}

/**
 * POST /api/generate {prompt|messages, stream}.
 *
 * orproxy and ai-proxy fall back to this route when their own rungs fail, and a
 * 404 here is the `mind error: 404` in their error chain. It is an alias, not a
 * second generator: the body is rewritten into the chat contract and handed to
 * the same pipeline, so the truth cache, the presets, the store prompt and the
 * stream protocol all behave exactly as they do on /api/chat.
 */
async function generate(request, env, ctx) {
  const body = await request.json().catch(() => null);
  if (!body || typeof body !== 'object') {
    return fail(400, 'body_required', 'Send { prompt | messages, stream }.');
  }

  const supplied = Array.isArray(body.messages) ? body.messages : [];
  // `prompt` is the proxy's name for a single user turn; `input` is its older one.
  const prompt = [body.prompt, body.input].find((value) => typeof value === 'string' && value.trim());
  const messages = supplied.length ? supplied : prompt ? [{ role: 'user', content: prompt }] : [];
  if (!messages.length) {
    return fail(400, 'prompt_required', 'Send a non-empty prompt, or messages: [{ role, content }].');
  }

  // The caller's address still decides the budget, so it is carried across; the
  // body is replaced, which is the only thing this alias rewrites.
  const headers = new Headers({ 'content-type': 'application/json' });
  const ip = request.headers.get('cf-connecting-ip');
  if (ip) headers.set('cf-connecting-ip', ip);

  const rewritten = new Request(new URL('/api/chat', request.url).toString(), {
    method: 'POST',
    headers,
    body: JSON.stringify({
      messages,
      preset: body.preset,
      presetLocked: body.presetLocked === true || body.presetsLocked === true,
      style: body.style === true,
      stream: body.stream,
    }),
  });
  return chat(rewritten, env, ctx);
}

/** The protocol's own end-of-answer signals: the sentinel frame or a finish_reason. */
const isTerminal = (data) => data === '[DONE]' || Boolean(finishReason(data));

/**
 * The only truncation this app can see without a protocol marker is text that
 * stops inside a word — the observed failures ended at "scheduling a new" and
 * "08/26/202". A letter or digit as the last character is that signature; a
 * closing bracket, quote, period or markdown marker is not.
 */
function endsMidWord(text) {
  return /[\p{L}\p{N}]$/u.test(String(text || '').trimEnd());
}

/**
 * The ambient assistant: a second voice that can see the canvas, and stays out of the way.
 *
 * It is deliberately not the audit engine. A card is answered by the engine with
 * provenance and gaps; a co-pilot conversation is about the work in front of him -
 * what a card says, how two cards disagree, what to ask next. So this route does
 * not read the store, does not run the decision model and does not write a card.
 */
async function assist(request, env, ctx) {
  const body = await request.json().catch(() => null);
  const thread = Array.isArray(body?.thread)
    ? body.thread
        .filter((m) => m && typeof m.content === 'string' && (m.role === 'user' || m.role === 'assistant'))
        // A file delivered for reading is source, not chat: 4000 characters cut
        // the middle out of the one thing it was asked to look at.
        .map((m) => ({ role: m.role, content: m.content.slice(0, 40000) }))
        .slice(-12)
    : [];
  // Both faces of every loaded card, in full, is a larger brief than an excerpt
  // was; the assistant is the voice between the system and the owner, so it reads
  // the work rather than a preview of it.
  const context = String(body?.context || '').slice(0, 30000);
  const ask = [...thread].reverse().find((m) => m.role === 'user')?.content.trim() || '';
  if (!ask) return fail(400, 'ask_required', 'Send { thread: [...], context } with a user message.');

  const brief = [
    "You are the ambient assistant inside mind, the owner's card workspace. He is talking to you with his",
    'loaded work in front of him, so speak as someone who can see it.',
    '',
    'What is on the canvas right now, both faces of each card:',
    context || '(nothing loaded yet)',
    '',
    'How to work:',
    '- Refer to a card by its number and question. Quote it when the wording matters.',
    '- Never invent what a card says. If the excerpt is cut off, say what you would need to see.',
    '- He is the author of this material. Do not rewrite his words unless he asks; point at them.',
    '- No preamble, no flattery, no restating the question. Answer, or ask the one thing that unblocks you.',
    '- You assist; you do not take over. Help him do the work himself - point, suggest, narrow - and only do it when he asks you to.',
    '- Short by default. He is working, not reading.',
    '- You are not the audit engine: when a claim needs checking, name the check that would settle it.',
    '',
    "Mind's own code is below as a map, not as text. When a question is about how the app or the worker actually behaves, ask for the one file you need by writing a single line and nothing else:",
    '[read: path/to/file.js]',
    'The file arrives next turn, as source. A long file is sent from its start, so when the question is about one thing in it, ask for that instead:',
    '[read: path/to/file.js around aNameItContains]',
    'Do not guess at code you have not been shown; if the map has no file that answers the question, say that plainly.',
  ].join('\n');

  const messages = [{ role: 'system', content: brief }, ...thread];
  let text = '';
  let note = '';
  try {
    const upstream = await openUpstream(env, { messages, images: [], ask });
    for await (const data of sseData(upstream.stream, { timeoutMs: STREAM_IDLE_MS })) {
      const problem = upstreamError(data);
      if (problem) {
        note = String(problem.message || problem.error?.message || 'upstream refused');
        break;
      }
      text += upstream.extract(data);
    }
  } catch (err) {
    return fail(502, 'assist_failed', err?.message || 'The co-pilot could not answer.');
  }
  if (!text.trim()) return fail(502, 'assist_empty', note || 'No answer came back.');
  return json({ text: text.trim(), contextChars: context.length, turns: thread.length });
}

async function chat(request, env, ctx) {
  const body = await request.json().catch(() => null);
  if (!body || !Array.isArray(body.messages) || body.messages.length === 0) {
    return fail(400, 'messages_required', 'Send { messages: [{ role, content }], preset, stream }.');
  }

  const { messages, images } = normalizeMessages(body.messages);
  const lastUser = [...messages].reverse().find((m) => m.role === 'user')?.content || '';
  // What was actually asked, without the base prompt the client wraps around it.
  const question = questionOf(lastUser);
  if (!messages.length) return fail(400, 'messages_required', 'No usable messages were provided.');

  const totalChars = messages.reduce((sum, m) => sum + m.content.length, 0);
  if (totalChars > MAX_MESSAGES_CHARS) {
    return fail(413, 'context_too_large', `Conversation is ${totalChars} characters; the limit is ${MAX_MESSAGES_CHARS}.`);
  }
  if (images.length > MAX_IMAGES) {
    return fail(413, 'too_many_images', `At most ${MAX_IMAGES} images per request.`);
  }

  const requested = body.preset ? String(body.preset).toLowerCase() : null;
  // "none" is a real selection: no preset prompt and no @preset/ reference.
  const noneSelected = requested === 'none' || requested === 'no-preset';
  const requestedPreset = requested && !noneSelected ? findPreset(requested) : null;
  if (requested && !noneSelected && !requestedPreset) {
    return fail(400, 'unknown_preset', `Unknown preset "${requested}".`, {
      available: publicPresets().map((p) => p.id),
    });
  }

  // A preset picked from the menu wins, truth included — the client marks those
  // with presetLocked. Truth is also the fallback prompt, so an *unlocked* truth
  // must not outrank the decision or clef could never route.
  const pinned =
    Boolean(requestedPreset) &&
    (requestedPreset.id !== DEFAULT_PRESET || body.presetLocked === true);

  // The Stylist asks for a palette, not for an answer. That hint goes to the
  // decision model, which names the task and is what routes the request.
  const styleHint = body.style === true;

  const engine = await engineFor(env);
  const useCf = canUseCloudflare(env, engine);

  // Neurons are the reason this switch exists: with Cloudflare off nothing is
  // charged against the daily allowance, and OpenRouter's limits apply instead.
  const gate = useCf ? await charge(env, clientIp(request), 300) : { ok: true };
  if (!gate.ok) {
    return fail(429, 'budget_exhausted', `Daily budget reached (${gate.used}/${gate.limit} neurons). Resets at 00:00 UTC.`);
  }

  // She is the first contact: no decision from her, no request.
  // What is already stored, read without generating: she sees the pair before
  // she decides, so a stored non-answer is judged before anything is written.
  const peeked = await peekTruth(env, question || lastUser).catch(() => null);
  // He said it is not a key. Told plainly, because the same bare words would
  // otherwise arrive as the same key card every time and the loop never ends.
  // Absence is a question, not a finding. Her answer to a docket audit described
  // text that had simply never been provided as "corrupted", a cause nobody had
  // established, and then built the conclusion on it. The rule goes in the ask she
  // receives: a fact the source does not contain is his to supply, not hers to
  // explain away.
  const premiseRule = [
    '',
    '(Before you decide: if answering needs a fact the attached text does not contain - a date, a warrant or order type, a notice, a filing, an authority - ask the owner for it on a card with options. Never describe text that is absent as corrupted, unreadable or damaged, and never let an assumption about why it is absent carry an audit. Missing is missing; ask what it is.)',
  ].join('\n');
  const araAsk = (body.notAKey === true
    ? `${question || lastUser}\n\n(He has said this is not a lookup key and there is no stored pair. Treat it as ordinary prose and answer it.)`
    : (question || lastUser)) + premiseRule;
  const ara = await askAra(env, araAsk, 'general', body.araChoice || null, peeked);
  if (!ara.ok) return fail(502, 'ara_no_decision', `ARA did not decide (${ara.reason}).`);
  // She is unsure: he is asked on a card, and no model is called behind her.
  // Her "nothing stored under that key" card waits: the pair may be in truth and
  // not in this worker's store, and she should not say there is none until that
  // is settled. Every other question she asks stops the request here.
  let noPairCard = null;
  if (ara.clarify) {
    const askedFirst = (ara.clarify.questions || [])[0] || null;
    const offers = (askedFirst && askedFirst.options) || [];
    const looksNoPair =
      offers.some((o) => o && o.value === 'none') && offers.some((o) => o && o.value === 'write');
    if (!looksNoPair) {
    // Streamed, because the client reads this endpoint as events: a bare JSON
    // body looked like nothing had happened.
    const question = askedFirst;
    // Her words first, then the options: a card with an empty pane is not a card.
    const said = ara.clarify.text || (question && question.q) || '';
    const body = [
      ...(said ? [`data: ${JSON.stringify({ type: 'delta', text: said })}`, ''] : []),
      `data: ${JSON.stringify({ type: 'clarify', question, ara: { id: ara.id } })}`,
      '',
      'data: [DONE]',
      '',
    ].join('\n\n');
    return new Response(body + '\n', { headers: SSE_HEADERS });
    }
    noPairCard = ara;
  }

  // A preset the user picked wins; decide() only fills the gap.
  const decision = await decide(env, {
    messages,
    images,
    presetId: pinned ? requested : null,
    allowPreset: !noneSelected,
    engine,
    style: styleHint,
    ara,
  });
  // Clef's answer routes it too: a request it classified as a style ask is the
  // same thing as one the client marked, whichever arrives first.
  const styling = styleHint || decision.task === 'style';
  // A deliberate pick wins outright. Otherwise the decision steers, and the
  // preset the client sent (truth, normally) is the fallback prompt.
  // A palette is one line of directives: a preset's prompt answers in its own
  // shape instead (Doc returned "!EmeraldTerminal,…!" with no theme keyword).
  const chosen = styling
    ? null
    : noneSelected
      ? null
      : pinned
        ? requestedPreset
        : (decision.preset && findPreset(decision.preset)) || requestedPreset || findPreset(DEFAULT_PRESET);
  // Every preset carries its own prompt from src/prompts, so a served truth and a
  // generated one see the same text and no store can substitute another.
  const preset = chosen;

  // What he has taught, asked of TEW before anything writes. A rule changed at
  // the top reaches this turn without a deploy; no key, no binding or a slow TEW
  // leaves the turn exactly as it was.

  // Report the preset that actually ran, not the one the decision model named:
  // they diverge whenever it suggests a preset that no longer exists.
  // The owner's override: what is stored is not the answer to this ask. Recorded
  // before it runs, because an override nobody can review is a silent exception.
  let overridden = false;
  if (body.override === true) {
    const actor = await sessionUser(request, env);
    // A name when names exist. Before login is configured there is nobody to name,
    // and refusing would leave the owner without the override he asked for.
    if (loginEnabled(env) && !actor) {
      return fail(401, 'sign_in_required', 'An override carries a name: sign in first.');
    }
    overridden = true;
    const store = stateKv(env);
    if (store) {
      await store
        .put(`override:${Date.now()}`, JSON.stringify({
          actor: actor || 'anonymous',
          question: String(question || lastUser).slice(0, 300),
          preset: preset?.id ?? null,
          at: new Date().toISOString(),
        }))
        .catch(() => null);
    }
    // Nothing stored answers this run: the store is what is being questioned.
    decision.truth = null;
    decision.source = 'override';
    decision.cacheSource = null;
  }

  const reported = { ...decision, preset: preset?.id ?? null, ara: ara.bound ? { id: ara.id, move: ara.move, route: ara.route, notes: ara.notes ? ara.notes.length : 0 } : null };

  // Half a record is not a record: she keeps what the run produced beside what
  // she chose, so the next decision is made with the result in view.
  if (ara.bound && ara.id) {
    // Awaited: a fire-and-forget subrequest is dropped when the stream ends.
    await reportOutcome(env, ara.id, {
      returned: decision.source === 'cache' ? decision.cacheSource || 'stored' : 'generated',
      stored: decision.cacheSource || null,
      origin: decision.truth?.origin || null,
      route: decision.task || null,
    });
  }
  // Any pair he did not author and nobody verified is her call before it is
  // served. Master truth is never second-guessed.
  const servedPair = decision.truth && decision.truth.answer ? decision.truth : null;
  const unverifiedPair = servedPair && servedPair.layer !== 'master' && !(servedPair.origin && servedPair.origin.verified === true);
  if (unverifiedPair && !body.araChoice) {
    const card = await askAra(env, question || lastUser, 'general', null, {
      layer: servedPair.layer,
      answer: servedPair.answer,
      key: servedPair.key || null,
      id: servedPair.id || null,
    });
    if (card.clarify) {
      const asked = (card.clarify.questions || [])[0] || null;
      const said = card.clarify.text || (asked && asked.q) || '';
      const payload = [
        `data: ${JSON.stringify({ type: 'meta', route: 'truth', model: servedPair.layer, preset: preset?.id ?? null, decision: reported })}`,
        '',
        ...(said ? [`data: ${JSON.stringify({ type: 'delta', text: said })}`, ''] : []),
        `data: ${JSON.stringify({ type: 'clarify', question: asked, ara: { id: card.id, move: card.move } })}`,
        '',
        'data: [DONE]',
        '',
      ].join('\n\n');
      return new Response(payload + '\n', { headers: SSE_HEADERS });
    }
  }

  // Nothing to look at: now her card about the key is the right answer.
  // A pair written by this request is not a pair he has: she asked what to do
  // about the key, and that answer still stands.
  const writtenJustNow = !servedPair || !servedPair.origin || servedPair.origin.fresh === true;
  if (noPairCard && writtenJustNow) {
    const asked = (noPairCard.clarify.questions || [])[0] || null;
    const said = noPairCard.clarify.text || (asked && asked.q) || '';
    const payload = [
      ...(said ? [`data: ${JSON.stringify({ type: 'delta', text: said })}`, ''] : []),
      `data: ${JSON.stringify({ type: 'clarify', question: asked, ara: { id: noPairCard.id, move: noPairCard.move } })}`,
      '',
      'data: [DONE]',
      '',
    ].join('\n\n');
    return new Response(payload + '\n', { headers: SSE_HEADERS });
  }

  const wantsStream = body.stream !== false;

  // She routes, so this is where her answer changes what happens rather than
  // just being recorded: `generate` and `card` mean write it, never hand back a
  // stored one; `truth` means the store is where to look, however long the ask.
  const araRoute = ara.bound ? ara.route : null;
  const writeIt = araRoute === 'generate' || araRoute === 'card';

  // A curated (master) truth answers in place of the model, and instantly. A
  // provisional one is the truth service's own guess kept on the way past: still
  // a cache hit worth serving, but only when the ask is small enough for one
  // stored sentence to answer it. An ask that names a length, or one clef
  // classified deep, goes to the model, so a report is never replaced by a
  // one-liner. A preset picked from the menu also means "generate".
  const briefAsk = decision.depth !== 'deep' && !ASKS_FOR_LENGTH.test(lastUser);
  // Only the curated pair is an answer. Master, or a pair somebody verified, is
  // what he wrote or what survived review; a provisional one is the service's own
  // guess kept on the way past, and serving it means a prompt fixed this morning
  // is unreachable for every question the store already recognises. The guess is
  // not thrown away: what it replaced goes on the record beside the new answer.
  const curatedPair = Boolean(
    decision.truth?.answer &&
      (decision.truth.layer === 'master' || decision.truth.origin?.verified === true),
  );
  if (decision.truth?.answer && !curatedPair) {
    const replaced = {
      layer: decision.truth.layer || null,
      id: decision.truth.id || null,
      chars: String(decision.truth.answer || '').length,
      verified: decision.truth.origin?.verified === true,
      source: decision.truth.origin?.source || null,
    };
    decision.replaced = replaced;
    decision.truth = null;
    decision.source = 'regenerated';
    decision.trace = [...(decision.trace || []), `replaced:${replaced.layer || 'unknown'}`];
    reported.replaced = replaced;
    reported.truth = null;
    reported.source = 'regenerated';
  }
  const cachedTruth = curatedPair && (araRoute === 'truth' || decision.truth.layer === 'master' || briefAsk);
  // Picking Truth from the menu means "answer with the truth preset", and a
  // stored truth is that preset's answer - so the cache still serves. Picking
  // any other preset means generate with it, cache or no cache.
  const mayServeCache = (!pinned || preset?.id === DEFAULT_PRESET) && !styling && !writeIt;
  const hisChoice = body.araChoice || null;
  // He picked one of her cards: the one moment a turn says how he wants this kind
  // of ask handled. Reported up rather than kept here, so the next tool inherits it.
  const CHOICE_ROWS = {
    none: 'nothing stored under that key: leave it alone',
    pair: 'show the stored pair behind the ask',
    write: 'write a new answer for that key',
  };
  if (hisChoice && CHOICE_ROWS[hisChoice]) {
    learnReport(env, ctx, { q: question, a: CHOICE_ROWS[hisChoice] }).catch(() => false);
  }
  if (hisChoice === 'none') {
    const said = 'Left alone: nothing stored under that key, and nothing written.';
    const quiet = new ReadableStream({
      start(controller) {
        const send = (chunk) => chunk && controller.enqueue(encoder.encode(chunk));
        send(delta(said));
        send(DONE);
        controller.close();
      },
    });
    return new Response(quiet, { headers: SSE_HEADERS });
  }

  // He asked for the record behind a stored non-answer.
  if (hisChoice === 'pair' && decision.truth?.answer) {
    const origin = decision.truth.origin || {};
    const text = [
      'The stored pair behind this ask:',
      `- layer: ${decision.truth.layer || 'unknown'}`,
      `- id: ${decision.truth.id || 'unknown'}`,
      `- source: ${origin.source || 'unknown'}`,
      `- verified: ${origin.verified === true}`,
      `- written: ${origin.created ? new Date(origin.created).toISOString() : 'unknown'}`,
      `- key: ${decision.truth.key || 'unknown'}`,
      '',
      String(decision.truth.answer || ''),
    ].join('\n');

    if (!wantsStream) return json({ text, route: 'truth', model: decision.truth.layer, decision: reported });
    const pairStream = new ReadableStream({
      start(controller) {
        const send = (chunk) => chunk && controller.enqueue(encoder.encode(chunk));
        send(meta({ route: 'truth', model: decision.truth.layer, preset: preset?.id, decision: reported }));
        send(delta(text));
        send(DONE);
        controller.close();
      },
    });
    return new Response(pairStream, { headers: SSE_HEADERS });
  }

  if (cachedTruth && mayServeCache && hisChoice !== 'write') {
    const truth = decision.truth;

    if (truth.layer === 'candidate') {
      await recordCandidate(
        env,
        {
          input: question,
          answer: truth.answer,
          preset: preset?.id,
          route: truth.route || 'truth',
          model: truth.model || 'candidate',
        },
        ctx,
      );
    }
    if (!wantsStream) {
      await recordReview(
        env,
        ctx,
        reviewOf({ preset, decision: reported, route: 'truth', model: truth.layer, lastUser, text: truth.answer }),
      );
      return json({ text: truth.answer, route: 'truth', model: truth.layer, decision: reported });
    }

    const truthStream = new ReadableStream({
      start(controller) {
        const send = (chunk) => chunk && controller.enqueue(encoder.encode(chunk));
        send(meta({ route: 'truth', model: truth.layer, preset: preset?.id, decision: reported }));
        send(delta(truth.answer));
        send(DONE);
        controller.close();
      },
    });
    return new Response(truthStream, { headers: SSE_HEADERS });
  }

  const system = preset?.system
    ? [{ role: 'system', content: preset.system }, ...messages]
    : messages;
  const learned = await learnHint(env, { prompt: question, domain: preset?.id }).catch(() => null);
  const grounded = withBrowse(withNotes(withLearned(system, learned?.hint), ara.notes), decision);

  if (!wantsStream) {
    const { route, model, stream, extract } = await openUpstream(env, {
    ask: lastUser,
      messages: grounded,
      images,
      preset,
      decision: reported,
      explicit: pinned,
      allowCloudflare: useCf,
      freeRouter: engine === 'openrouter',
      presetPinned: pinned,
    });
    let text = '';
    let frames = 0;
    let shape = null;
    let sawTerminal = false;
    let cutReason = null;
    for await (const data of sseData(stream, { timeoutMs: STREAM_IDLE_MS })) {
      const problem = upstreamError(data);
      if (problem) throw explain(problem);
      if (isTerminal(data)) sawTerminal = true;
      if (finishState(data) === 'cut') cutReason = finishReason(data);
      frames += 1;
      shape = shape ?? frameShape(data);
      text += extract(data);
    }
    // An empty answer is not a valid answer. Retry once without streaming so a
    // shape mismatch reads as recovered text instead of a blank card.
    if (!text && route === 'workers-ai') {
      text = await within(UPSTREAM_OPEN_MS, `workers-ai ${model}`, () =>
        cf.chat(env, {
          model,
          messages: grounded,
          images,
          temperature: preset?.temperature,
          maxTokens: budgetForAsk(preset, reported, lastUser),
        }),
      );
    }
    if (!text) {
      return fail(
        502,
        'empty_upstream',
        `${route} (${model}) returned no text: ${describeEmpty(frames, shape)}.`,
      );
    }
    // Text is not the same thing as a finished answer. A stream that closed
    // mid-word used to return 200 carrying half a report, which is how a
    // truncated audit reached its caller looking like a completed one. The
    // partial text is still handed back, under an error, so it can be read
    // without being trusted.
    // A length cut is the provider's own admission, so it outranks how the text
    // happens to end: a report cut at the ceiling can still stop at a full stop.
    if (cutReason) {
      return fail(
        502,
        'output_truncated',
        `${route} (${model}) stopped at its ${cutReason} limit after ${text.length} characters; the text is a prefix, not an answer.`,
        { partial: text, finishReason: cutReason },
      );
    }
    if (!sawTerminal && endsMidWord(text)) {
      return fail(
        502,
        'stream_incomplete',
        `${route} (${model}) closed the stream mid-answer after ${text.length} characters; the text is not a complete answer.`,
        { partial: text },
      );
    }
    await recordReview(env, ctx, reviewOf({ preset, decision: reported, route, model, lastUser, text }));
    // A palette is kept by its own rule: the higher reported confidence wins and
    // the other answer stays logged beside it. Everything else becomes a
    // candidate, so nothing has to be retyped to promote it.
    if (styling) {
      await recordStyleCandidate(env, {
        input: question,
        answer: text,
        confidence: confidenceOf(text),
        preset: preset?.id,
        route,
        model,
      });
    } else {
      await recordCandidate(env, { input: question, answer: text, preset: preset?.id, route, model }, ctx);
    }
    return json({ text, route, model, decision: reported });
  }

  const { route, model, stream, extract } = await openUpstream(env, {
    ask: lastUser,
    messages: grounded,
    images,
    preset,
    decision: reported,
    explicit: pinned,
    allowCloudflare: useCf,
    freeRouter: engine === 'openrouter',
    presetPinned: pinned,
  });

  const out = new ReadableStream({
    async start(controller) {
      const send = (chunk) => chunk && controller.enqueue(encoder.encode(chunk));
      // Declared outside the try: the review call after it still needs them.
      let emitted = 0;
      let answer = '';
      let frames = 0;
      let shape = null;
      let sawTerminal = false;
      let cutReason = null;
      try {
        send(meta({ route, model, preset: preset?.id, decision: reported }));
        for await (const data of sseData(stream, { timeoutMs: STREAM_IDLE_MS })) {
          const problem = upstreamError(data);
          if (problem) throw explain(problem);
          if (isTerminal(data)) sawTerminal = true;
          if (finishState(data) === 'cut') cutReason = finishReason(data);
          frames += 1;
          shape = shape ?? frameShape(data);
          const text = extract(data);
          if (text) {
            emitted += 1;
            answer += text;
            send(delta(text));
          }
        }
        if (!emitted && route === 'workers-ai') {
          const text = await within(UPSTREAM_OPEN_MS, `workers-ai ${model}`, () =>
            cf.chat(env, {
              model,
              messages: grounded,
              images,
              temperature: preset?.temperature,
              maxTokens: budgetForAsk(preset, reported, lastUser),
            }),
          );
          if (text) {
            answer += text;
            send(delta(text));
          }
          else send(errorEvent('empty_upstream', `${model} returned no text: ${describeEmpty(frames, shape)}.`));
        } else if (!emitted) {
          send(errorEvent('empty_upstream', `${route} (${model}) returned no text.`));
        }
        // The deltas are already on the wire, so this cannot become an HTTP
        // error; it is the stream admitting the answer stopped mid-thought.
        // The provider's `length` wins over the text heuristic because a prefix
        // can end on a full stop and still be a prefix.
        if (emitted && cutReason) {
          send(
            incompleteEvent({
              code: 'output_truncated',
              message: `${route} (${model}) stopped at its ${cutReason} limit after ${answer.length} characters. The text above is a prefix, not a complete answer.`,
              reason: cutReason,
              chars: answer.length,
            }),
          );
        } else if (emitted && !sawTerminal && endsMidWord(answer)) {
          send(
            incompleteEvent({
              code: 'stream_incomplete',
              message: `${route} (${model}) closed the stream mid-answer after ${answer.length} characters. The text above is not a complete answer.`,
              chars: answer.length,
            }),
          );
        }
      } catch (err) {
        send(errorEvent(err?.code || 'stream_failed', err?.message || String(err)));
      }
      await recordReview(
        env,
        ctx,
        reviewOf({ preset, decision: reported, route, model, lastUser, text: answer }),
      );
      // Stored whether or not it is good: promotion is a later decision. A
      // palette follows its own rule instead — see recordStyleCandidate.
      if (styling) {
        await recordStyleCandidate(env, {
          input: question,
          answer,
          confidence: confidenceOf(answer),
          preset: preset?.id,
          route,
          model,
        });
        // She decided this ask was a style ask, so she is told what the style turned
        // out to be. The palette was recorded above; this is the same fact in her own
        // row, so the next style decision is made knowing what the last one produced.
        // Awaited for the same reason as the first report: a subrequest let go of
        // here is dropped when the stream closes.
        if (ara.bound && ara.id) {
          const palette = /!theme:([^!\n]+)!/i.exec(answer);
          const name = palette ? (palette[1].split(',')[0] || '').trim().slice(0, 60) : '';
          await reportOutcome(env, ara.id, {
            returned: 'generated',
            stored: name || null,
            route: 'style',
            origin: null,
          });
        }
      } else {
        await recordCandidate(env, { input: question, answer, preset: preset?.id, route, model }, ctx);
      }
      send(DONE);
      controller.close();
    },
  });

  return new Response(out, { headers: SSE_HEADERS });
}

/**
 * A session is a cookie, or a bearer for anything that is not a browser. The
 * token names the account it belongs to, so the right object is asked directly.
 */
/**
 * Sign-in is optional for using mind and required for correcting her: a
 * correction is somebody's judgement, so it carries a name when names exist.
 */
const loginEnabled = (env) => Boolean(sessionsBinding(env)) && has(env, 'LOGIN_PASSWORD');

async function sessionUser(request, env) {
  const token = tokenFrom(request, SESSION_COOKIE);
  const named = token ? tokenUser(token) : null;
  if (!token || !named) return null;
  const data = await readSession(env, token).catch(() => null);
  if (!data) return null;
  if (data.expiresAt && data.expiresAt <= Date.now()) return null;
  return data.user || named;
}

async function sessionRoute(request, env) {
  const token = tokenFrom(request, SESSION_COOKIE);
  const user = token ? tokenUser(token) : null;
  if (!token || !user) return json({ ok: true, user: null });

  const session = await readSession(env, token).catch(() => null);
  return json({
    ok: true,
    user: session ? user : null,
    expiresAt: session?.expiresAt ?? null,
    store: Boolean(sessionsBinding(env)),
  });
}

/**
 * One shared password gates every name, and the name is what the Durable Object
 * namespaces. Per-user passwords would replace the comparison below, not the
 * session plumbing.
 */
async function loginRoute(request, env) {
  const body = await request.json().catch(() => null);
  const user = String(body?.user || '')
    .trim()
    .toLowerCase()
    .slice(0, 64);
  const password = String(body?.password || '');

  if (!user || !password) return fail(400, 'credentials_required', 'Send { user, password }.');
  if (!/^[\w .@-]{1,64}$/.test(user)) {
    return fail(400, 'bad_user', 'Names may use letters, numbers, spaces and . _ @ -');
  }

  const expected = String(env?.LOGIN_PASSWORD || '');
  if (!expected) {
    return fail(
      503,
      'login_unset',
      'Set the LOGIN_PASSWORD secret (wrangler secret put LOGIN_PASSWORD) before anyone can sign in.',
    );
  }
  if (!sessionsBinding(env)) {
    return fail(503, 'no_sessions', 'The SESSIONS Durable Object binding is missing from wrangler.jsonc.');
  }
  if (!keyMatches(expected, password)) {
    return fail(401, 'bad_login', 'Wrong name or password.');
  }

  const session = await openSession(env, user, { ttl: SESSION_TTL_MS });
  if (!session) return fail(503, 'no_sessions', 'The session store did not answer.');

  const secure = new URL(request.url).protocol === 'https:';
  return json(
    { ok: true, user, expiresAt: session.expiresAt },
    {
      headers: {
        'set-cookie': sessionCookie(SESSION_COOKIE, session.token, {
          maxAge: Math.floor(SESSION_TTL_MS / 1000),
          secure,
        }),
      },
    },
  );
}

async function logoutRoute(request, env) {
  const token = tokenFrom(request, SESSION_COOKIE);
  if (token) await closeSession(env, token).catch(() => {});
  const secure = new URL(request.url).protocol === 'https:';
  return json(
    { ok: true, user: null },
    { headers: { 'set-cookie': clearCookie(SESSION_COOKIE, { secure }) } },
  );
}

async function stt(request, env) {
  const contentType = request.headers.get('content-type') || '';
  let bytes;

  if (contentType.includes('application/json')) {
    const body = await request.json().catch(() => null);
    bytes = bytesFromB64(body?.audio || '');
  } else {
    bytes = new Uint8Array(await request.arrayBuffer());
  }

  if (!bytes || !bytes.length) {
    return fail(400, 'audio_required', 'Send a WAV body or {"audio": "<base64>"}.');
  }
  if (bytes.length > MAX_AUDIO_BYTES) {
    return fail(413, 'audio_too_large', `Audio must be under ${Math.round(MAX_AUDIO_BYTES / 1048576)} MB.`);
  }

  const info = wavInfo(bytes);
  const seconds = info?.seconds ?? null;
  const engine = await engineFor(env);
  const useCf = canUseCloudflare(env, engine);
  const gate = useCf ? await charge(env, clientIp(request), (seconds ? seconds / 60 : 1) * 46.63) : { ok: true };
  if (!gate.ok) {
    return fail(429, 'budget_exhausted', `Daily budget reached (${gate.used}/${gate.limit} neurons).`);
  }

  if (useCf) {
    // 30 s of 16 kHz mono WAV is ~960 KB, under the documented ~1 MB guidance.
    const chunks = info ? wavChunks(bytes, info, 30) : [bytes];
    let text = '';
    for (const chunk of chunks) {
      const piece = await cf.transcribe(env, {
        audio: b64FromBytes(chunk),
        initialPrompt: text ? text.slice(-220) : undefined,
      });
      text += (text ? ' ' : '') + String(piece || '').trim();
    }
    return json({ text: text.trim(), engine: 'workers-ai', chunks: chunks.length, seconds });
  }

  if (has(env, 'OPENROUTER_API_KEY')) {
    const text = await or.transcribe(env, { bytes, format: info ? 'wav' : 'webm' });
    return json({ text: String(text || '').trim(), engine: 'openrouter', chunks: 1, seconds });
  }

  return fail(503, 'no_asr_engine', 'No ASR available: bind AI or set OPENROUTER_API_KEY.');
}

async function tts(url, env, ctx) {
  const text = (url.searchParams.get('t') || '').trim();
  if (!text) return fail(400, 'text_required', 'Pass ?t=<text>.');
  if (text.length > MAX_TTS_CHARS) {
    return fail(413, 'text_too_long', `Split text into chunks under ${MAX_TTS_CHARS} characters.`);
  }

  const voice = url.searchParams.get('v') || '';
  const model = url.searchParams.get('m') || 'melotts';
  const key = `tts/${await sha256Key(`${model}|${voice}|${text}`)}.mp3`;

  const bucket = objects(env);
  if (bucket) {
    const hit = await bucket.get(key);
    if (hit) return audioResponse(hit.body, { source: 'r2' });
  }

  const cache = typeof caches !== 'undefined' ? caches.default : null;
  const cacheKey = cache ? new Request(url.toString(), { method: 'GET' }) : null;
  if (cache && cacheKey) {
    const hit = await cache.match(cacheKey);
    if (hit) return hit;
  }

  const engine = await engineFor(env);
  const useCf = canUseCloudflare(env, engine);
  const gate = useCf
    ? await charge(env, clientIpFromUrl(url), Math.max(20, text.length / 6))
    : { ok: true };
  if (!gate.ok) {
    return fail(429, 'budget_exhausted', `Daily budget reached (${gate.used}/${gate.limit} neurons).`);
  }

  let speech;
  if (useCf) {
    speech = await cf.speech(env, { text, voice, lang: url.searchParams.get('lang') || 'en' });
  } else if (has(env, 'OPENROUTER_API_KEY')) {
    speech = await or.speech(env, { text, voice, model });
  } else {
    return fail(503, 'no_tts_engine', 'No TTS available: bind AI or set OPENROUTER_API_KEY.');
  }

  const bytes = speech.bytes || new Uint8Array(await new Response(speech.body).arrayBuffer());
  const response = audioResponse(bytes, { source: 'generated' });

  if (bucket && ctx?.waitUntil) ctx.waitUntil(bucket.put(key, bytes).catch(() => {}));
  if (cache && cacheKey && ctx?.waitUntil) ctx.waitUntil(cache.put(cacheKey, response.clone()).catch(() => {}));

  return response;
}

function clientIpFromUrl(url) {
  return url.searchParams.get('ip') || 'anon';
}

function audioResponse(body, { source }) {
  return new Response(body, {
    headers: { ...AUDIO_HEADERS, 'content-type': 'audio/mpeg', 'x-tts-source': source },
  });
}

async function sha256Key(value) {
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(value));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function upload(request, env) {
  const bucket = objects(env);
  if (!bucket) {
    return fail(503, 'no_storage', 'Uploads need the BUCKET R2 binding.');
  }
  const contentType = (request.headers.get('content-type') || 'application/octet-stream')
    .split(';')[0]
    .trim()
    .toLowerCase();
  // Pictures go to a vision model as pictures; documents are turned into text
  // on the way in, because a model cannot look inside a PDF.
  // Anything the paperclip can offer. Pictures, audio and video are stored and
  // linked; PDF, Word, Excel and slides are turned into text; an unknown binary
  // is stored with no text rather than rejected, because "other files" is the
  // point of the attach button.
  const allowed =
    /^(image\/|audio\/|video\/|text\/|application\/(pdf|json|xml|rtf|zip|octet-stream|x-yaml|yaml|javascript|msword|vnd\.ms-excel|vnd\.ms-powerpoint|vnd\.openxmlformats-officedocument\.(wordprocessingml\.document|spreadsheetml\.sheet|presentationml\.presentation)))/;
  if (!allowed.test(contentType)) {
    return fail(415, 'unsupported_type', `Unsupported content type: ${contentType}`);
  }

  const bytes = new Uint8Array(await request.arrayBuffer());
  if (!bytes.length) return fail(400, 'empty_body', 'Upload was empty.');
  if (bytes.length > MAX_AUDIO_BYTES) return fail(413, 'file_too_large', 'Files must be under 12 MB.');

  const digest = await sha256Key(`${contentType}:${bytes.length}:${Date.now()}`);
  const id = `${digest.slice(0, 32)}${extensionFor(contentType)}`;
  await bucket.put(`uploads/${id}`, bytes, { httpMetadata: { contentType } });

  // Extraction happens once, here: the client sends the text with the prompt, so
  // a 40-page PDF costs one decode rather than one per turn.
  const extracted = await extractText(bytes, contentType).catch(() => null);
  const text = String(extracted?.text || '');

  return json({
    id,
    url: `/f/${id}`,
    contentType,
    size: bytes.length,
    kind: extracted?.kind || 'binary',
    chars: text.length,
    text: text.length > 20000 ? text.slice(0, 20000) : text,
    note: extracted?.note,
  });
}

function extensionFor(contentType) {
  if (contentType.includes('png')) return '.png';
  if (contentType.includes('jpeg')) return '.jpg';
  if (contentType.includes('webp')) return '.webp';
  if (contentType.includes('markdown')) return '.md';
  if (contentType.includes('csv')) return '.csv';
  if (contentType.includes('plain')) return '.txt';
  if (contentType.includes('json')) return '.json';
  if (contentType.includes('gif')) return '.gif';
  if (contentType.includes('pdf')) return '.pdf';
  if (contentType.includes('wav')) return '.wav';
  if (contentType.includes('mpeg')) return '.mp3';
  if (contentType.includes('mp4')) return '.mp4';
  if (contentType.includes('webm')) return '.webm';
  return '.bin';
}

async function serveObject(env, id) {
  const bucket = objects(env);
  if (!bucket) return new Response('Not found', { status: 404 });
  const object = await bucket.get(`uploads/${id}`);
  if (!object) return new Response('Not found', { status: 404 });
  return new Response(object.body, {
    headers: {
      'content-type': object.httpMetadata?.contentType || 'application/octet-stream',
      'cache-control': 'public, max-age=31536000, immutable',
      'access-control-allow-origin': '*',
    },
  });
}

/**
 * What he has taught, read from the top.
 *
 * The ladder lives in TEW — his own rules first, then the domain rules, then
 * what any tool learned in chat. TEW computes the matching, the fit and the
 * tiers; this file only asks and carries the answer, so a rule changed there
 * reaches this worker on its next turn without a deploy.
 *
 * The read is a want, never a dependency: no binding, no key, a slow TEW or a
 * refused answer all mean "carry on without it", which is what mind did before
 * the ladder existed.
 */

/** Long enough for a same-account service hop, short enough to stay invisible. */
const TIMEOUT_MS = 1500;

/** The hint is a few lines of rules; anything larger is not a hint any more. */
const HINT_MAX = 2000;

/** TEW is the name in this deployment; TRUTH-ENGINE is the other spelling. */
const tewOf = (env) => env?.TEW || env?.['TRUTH-ENGINE'] || null;

const keyOf = (env) => (typeof env?.LEARN_KEY === 'string' ? env.LEARN_KEY : '');

function signalFor() {
  return typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function'
    ? AbortSignal.timeout(TIMEOUT_MS)
    : undefined;
}

/**
 * GET /api/learn?prompt=&domain= — the assembled hint and the rows it used.
 * `used` is worth keeping: it says which rows actually shaped this answer.
 */
export async function learnHint(env, { prompt, domain } = {}) {
  const binding = tewOf(env);
  const learnKey = keyOf(env);
  if (!binding || typeof binding.fetch !== 'function' || !learnKey) return null;

  const ask = String(prompt || '').trim().slice(0, 1000);
  if (!ask) return null;

  const query = `prompt=${encodeURIComponent(ask)}${domain ? `&domain=${encodeURIComponent(String(domain))}` : ''}`;

  try {
    const res = await binding.fetch(
      new Request(`https://tew/api/learn?${query}`, {
        headers: { 'x-learn-key': learnKey },
        signal: signalFor(),
      }),
    );
    if (!res.ok) return null;

    const data = await res.json().catch(() => null);
    const hint = typeof data?.hint === 'string' ? data.hint.trim() : '';
    if (!hint) return null;

    return {
      hint: hint.slice(0, HINT_MAX),
      used: Array.isArray(data.used) ? data.used.slice(0, 4) : [],
      counts: data?.counts || null,
    };
  } catch {
    return null; // unreachable TEW is a turn without the hint, not a failed turn
  }
}

/**
 * POST /api/learn — what mind learned, handed up rather than kept here.
 *
 * Only an explicit choice is reported: he picked one of her cards, which is the
 * one moment a turn says something about how he wants this kind of ask handled.
 * Recording every answer instead would fill the ladder with churn.
 */
export async function learnReport(env, ctx, { q, a, source = 'chat' } = {}) {
  const binding = tewOf(env);
  const learnKey = keyOf(env);
  if (!binding || typeof binding.fetch !== 'function' || !learnKey) return false;

  const question = String(q || '').trim().slice(0, 300);
  const answer = String(a || '').trim().slice(0, 500);
  if (!question || !answer) return false;

  const body = JSON.stringify({ action: 'add', q: question, a: answer, source, tool: 'mind' });
  const send = () =>
    binding
      .fetch(
        new Request('https://tew/api/learn', {
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-learn-key': learnKey },
          body,
          signal: signalFor(),
        }),
      )
      .then((res) => Boolean(res?.ok), () => false);

  // Awaited when there is nowhere to defer to, so the write is not dropped.
  if (ctx?.waitUntil) {
    ctx.waitUntil(send());
    return true;
  }
  return send();
}

/**
 * Three upstream dialects, one wire format. The client only ever has to
 * understand these four events, which is why switching providers is invisible
 * to the frontend.
 */

export const DONE = 'data: [DONE]\n\n';

export const event = (payload) => `data: ${JSON.stringify(payload)}\n\n`;

export const meta = (fields) => event({ type: 'meta', ...fields });

export const delta = (text) => (text ? event({ type: 'delta', text }) : '');

export const errorEvent = (code, message) => event({ type: 'error', error: { code, message } });

/**
 * Text arrived, but the upstream never said it had finished. This is its own
 * event rather than an error: the deltas already painted are real, they are just
 * not the whole answer, and a card that shows them as complete is lying.
 */
export const incompleteEvent = (fields) => event({ type: 'incomplete', complete: false, ...fields });

/**
 * What a finish_reason actually claims.
 *
 * `stop` means the model finished. `length` means it was cut off at the token
 * ceiling: the text is a prefix, and a report that stops there is not a report.
 * Treating every finish_reason as success is how a truncated audit reads as a
 * finished one, because the sentinel frame arrives either way.
 */
const COMPLETE_REASONS = new Set(['stop', 'eos', 'end_turn', 'stop_sequence', 'complete', 'completed']);
const CUT_REASONS = new Set(['length', 'max_tokens', 'content_filter', 'model_context_window_exceeded']);

/** 'complete', 'cut', 'unknown', or null when the frame carries no reason. */
export function finishState(data) {
  const reason = finishReason(data);
  if (!reason) return null;
  const key = String(reason).toLowerCase();
  if (CUT_REASONS.has(key)) return 'cut';
  if (COMPLETE_REASONS.has(key)) return 'complete';
  return 'unknown';
}

/**
 * The provider's own end-of-answer signal, when it sends one. OpenAI-shaped
 * streams put a `finish_reason` on the last choice; the sentinel frame is the
 * other spelling of the same claim. Neither means "the socket closed".
 */
export function finishReason(data) {
  if (!data || data === '[DONE]') return null;
  try {
    const parsed = JSON.parse(data);
    const choice = parsed.choices?.[0] ?? parsed.result?.choices?.[0];
    const reason =
      choice?.finish_reason ??
      choice?.finishReason ??
      parsed.finish_reason ??
      parsed.result?.finish_reason;
    return typeof reason === 'string' && reason ? reason : null;
  } catch {
    return null;
  }
}

/**
 * Iterate the `data:` payloads of an SSE stream, whatever produced them.
 *
 * `timeoutMs` is an idle budget, restarted on every chunk: a slow but living
 * stream is never cut off, while a stalled one is cancelled and reported instead
 * of holding the request open until the platform gives up on it.
 */
export async function* sseData(stream, { timeoutMs = 0 } = {}) {
  const reader = stream.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let timer = null;
  let timedOut = false;

  const arm = () => {
    if (!timeoutMs) return;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timedOut = true;
      // Cancelling resolves the pending read as done, so the loop can exit.
      reader.cancel().catch(() => {});
    }, timeoutMs);
  };

  try {
    arm();
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      arm();
      buffer += decoder.decode(value, { stream: true });
      const frames = buffer.split('\n\n');
      buffer = frames.pop() || '';
      for (const frame of frames) {
        for (const line of frame.split('\n')) {
          if (line.startsWith('data:')) yield line.slice(5).trim();
        }
      }
    }
    if (buffer.trim()) {
      for (const line of buffer.split('\n')) {
        if (line.startsWith('data:')) yield line.slice(5).trim();
      }
    }
    if (timedOut) {
      const err = new Error(`Upstream stalled: no data for ${Math.round(timeoutMs / 1000)}s.`);
      err.code = 'upstream_timeout';
      err.status = 504;
      throw err;
    }
  } finally {
    if (timer) clearTimeout(timer);
    try {
      reader.releaseLock?.();
    } catch {
      /* the stream may already be cancelled */
    }
  }
}

/**
 * Workers AI can report a failure as a data frame rather than an HTTP status,
 * so a broken model looks like a successful empty answer unless this is checked.
 */
export function upstreamError(data) {
  if (!data || data === '[DONE]') return null;
  try {
    const parsed = JSON.parse(data);
    const err = parsed?.error ?? parsed?.errors?.[0] ?? parsed?.result?.error;
    if (!err) return null;
    return typeof err === 'string' ? err : err.message || JSON.stringify(err);
  } catch {
    return null;
  }
}

/**
 * Workers AI streams either its native {"response":"..."} shape or an
 * OpenAI-compatible one ({"choices":[{"delta":{"content"}}]}) depending on the
 * model family. Reading only the native shape makes a perfectly good answer
 * look like an empty one, which surfaces as "returned no text".
 */
export function fromWorkersAI(data) {
  if (!data || data === '[DONE]') return '';
  try {
    const parsed = JSON.parse(data);
    const choice = parsed.choices?.[0] ?? parsed.result?.choices?.[0];
    return (
      parsed.response ??
      parsed.result?.response ??
      choice?.delta?.content ??
      choice?.message?.content ??
      choice?.text ??
      ''
    );
  } catch {
    return '';
  }
}

/** The top-level keys of a frame, so an empty answer can say what it received. */
export function frameShape(data) {
  if (!data || data === '[DONE]') return null;
  try {
    const parsed = JSON.parse(data);
    if (!parsed || typeof parsed !== 'object') return null;
    const keys = Object.keys(parsed);
    return keys.length ? keys.join(',') : null;
  } catch {
    return null;
  }
}

/** OpenRouter chat/completions: choices[0].delta.content */
export function fromOpenRouterChat(data) {
  if (!data || data === '[DONE]') return '';
  try {
    return JSON.parse(data).choices?.[0]?.delta?.content || '';
  } catch {
    return '';
  }
}

import puppeteer from '@cloudflare/puppeteer';
import { browserBinding } from './bindings.js';

/**
 * Read a page with Browser Rendering.
 *
 * The agent-browsing service is the preferred way to look something up, but it
 * only answers its own request shapes and it is a DevTools gateway, not a text
 * extractor. When it cannot answer and the question named a page, rendering that
 * page here is the difference between "I can't browse" and an answer grounded in
 * the page. One launch, one close, capped text, so it costs what a screenshot costs.
 */

const NAV_TIMEOUT_MS = 20000;
const MAX_TEXT = 4000;

const VIEWPORT = { width: 1280, height: 800, deviceScaleFactor: 1 };

/** The first http(s) URL in a question, if it named one. */
export function firstUrl(text) {
  const match = String(text || '').match(/https?:\/\/[^\s<>"']+/i);
  return match ? match[0].replace(/[),.;:]+$/, '') : null;
}

export async function readPage(env, url) {
  // The URL is checked before the binding: a file:// path is refused whether or
  // not this deployment happens to have a browser, and the message should say so.
  let parsed;
  try {
    parsed = new URL(String(url));
  } catch {
    return { ok: false, error: 'bad_url' };
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return { ok: false, error: 'bad_scheme' };
  }

  const binding = browserBinding(env);
  if (!binding) return { ok: false, error: 'no_browser' };

  let session = null;
  try {
    session = await puppeteer.launch(binding);
    const page = await session.newPage();
    await page.setViewport(VIEWPORT);
    await page.goto(parsed.href, { waitUntil: 'domcontentloaded', timeout: NAV_TIMEOUT_MS });

    // Main content when the page marks it, the body otherwise: nav and footers
    // are most of a naive innerText and none of the answer.
    const captured = await page.evaluate(() => {
      const root = document.querySelector('main, article') || document.body;
      return { title: document.title || '', text: (root && root.innerText) || '' };
    });

    const text = `${captured.title}\n\n${captured.text}`
      .replace(/[ \t]+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim()
      .slice(0, MAX_TEXT);

    if (!text) return { ok: false, error: 'empty_page', via: 'rendering' };
    return { ok: true, text, via: 'rendering', url: parsed.href };
  } catch (err) {
    return { ok: false, error: String(err?.message || err), via: 'rendering' };
  } finally {
    if (session) await session.close().catch(() => {});
  }
}

import { PRESETS } from './presets.js';

/**
 * Promote a local preset definition into the OpenRouter account, so a prompt
 * edit lives in code and the dashboard just holds the deployed version.
 *
 * Two constraints from the API matter here:
 *
 * 1. The chat/completions skin persists only fields that overlap preset config
 *    (model, temperature, provider, top_p, system, tools). `messages` is ignored
 *    for storage but a system message in it is extracted into `system_prompt`,
 *    which is the only way to set the prompt through this skin.
 * 2. `max_tokens` is not part of a preset, so it stays a request concern. The
 *    preset rung sends none, which means the preset's own output cap applies.
 */

export function upsertPath(slug) {
  return `/presets/${encodeURIComponent(slug)}/chat/completions`;
}

export function upsertBody(preset, { model } = {}) {
  const chosen = model || preset.or;
  if (!chosen) {
    throw new Error(
      `No OpenRouter model for preset "${preset.id}". Set \`or\` in src/presets.js or pass --model.`,
    );
  }

  const body = { model: chosen };
  if (preset.temperature != null) body.temperature = preset.temperature;
  if (preset.system) body.messages = [{ role: 'system', content: preset.system }];
  return body;
}

/** One entry per preset that names an OpenRouter slug; others are local-only. */
export function syncPlan({ model } = {}) {
  return PRESETS.filter((preset) => preset.orPreset && !preset.internal).map((preset) => ({
    id: preset.id,
    slug: preset.orPreset,
    path: upsertPath(preset.orPreset),
    body: upsertBody(preset, { model }),
  }));
}

import { sha256Hex } from './util.js';
import { TRUTH_PROMPT, MNL_PROMPT, MICRO_PROMPT, DOC_PROMPT } from './prompts.js';

/**
 * Presets are server data: prompt + model + params, one rung per provider.
 *
 * Each `orPreset` names a preset in the account
 * (https://openrouter.ai/settings/presets), referenced as `@preset/<slug>`.
 * OpenRouter shallow-merges request fields over preset fields, so anything sent
 * alongside the reference replaces what the preset holds.
 *
 * The prompts are the owner's, in src/prompts/*.md and compiled into
 * src/prompts.js. Truth, MNL, Micro and Doc each carry their own text, and the
 * Truth one is used on both rungs: on Workers AI it is the system turn, and on
 * OpenRouter it overrides the referenced preset's own prompt, leaving the preset
 * to supply the model and sampling params. Operator keeps a local copy for the
 * rung the pipeline generates on when nothing is pinned.
 */

/** Used when no preset is picked and the decision model declines to route. */
export const DEFAULT_PRESET = 'truth';

/** The rung the decision pipeline generates on when nothing was pinned. */
export const OPERATOR_PRESET = 'operator';

export const PRESETS = [
  {
    id: 'truth',
    name: 'Truth',
    cf: '@cf/google/gemma-4-26b-a4b-it',
    orPreset: 'truth',
    or: null,
    // 0.1 stalls on this model: a long ask can run for minutes emitting nothing.
    temperature: 0.3,
    maxTokens: 4096,
    // The owner's Truth Engine prompt (src/prompts/truth.md). `systemFrom: 'code'`
    // tells the OpenRouter rung to send this text over the preset's own prompt, so
    // one prompt is what answers on both rungs.
    system: TRUTH_PROMPT,
    systemFrom: 'code',
  },
  {
    id: 'operator',
    name: 'Operator',
    cf: '@cf/qwen/qwen3.8-27b',
    orPreset: 'operator',
    or: null,
    temperature: 0.3,
    maxTokens: 6144,
    system:
      'You are an operator: you act rather than explain. Give the shortest path to a working result, name the exact commands or steps, state the precondition that would break it, and skip preamble.',
    // The rung the pipeline generates on when nothing is pinned. Nobody picks it
    // from the menu, so it stays out of /api/presets and out of the button cycle.
    internal: true,
  },
  {
    id: 'mnl',
    name: 'MNL',
    cf: '@cf/google/gemma-4-26b-a4b-it',
    orPreset: 'mnl',
    or: null,
    temperature: 0.7,
    maxTokens: 4096,
    // The owner's MNL prompt, kept here so the Workers AI rung runs the same text
    // the OpenRouter preset carries on its own rung.
    system: MNL_PROMPT,
  },
  // Micro and Doc are the owner's prompts too, kept in src/prompts/ and compiled
  // into src/prompts.js. Their OpenRouter presets carry the same text.
  {
    id: 'micro',
    name: 'Micro',
    cf: '@cf/google/gemma-4-26b-a4b-it',
    orPreset: 'micro',
    or: null,
    temperature: 0.3,
    maxTokens: 4096,
    system: MICRO_PROMPT,
  },
  {
    id: 'doc',
    name: 'Doc',
    cf: '@cf/google/gemma-4-26b-a4b-it',
    orPreset: 'doc',
    or: null,
    temperature: 0.3,
    maxTokens: 4096,
    system: DOC_PROMPT,
  },
];

const BY_ID = new Map(PRESETS.map((p) => [p.id, p]));

export function findPreset(id) {
  if (!id) return null;
  // Older clients sent keys with underscores; ids are lowercase and hyphenated.
  return BY_ID.get(String(id).toLowerCase().replace(/_/g, '-')) || null;
}

/**
 * What the Truth preset will run, without the text itself: `version` identifies
 * the prompt by hash, so an edit is visible from outside without publishing it.
 *
 * The text lives in src/prompts/truth.md. The Secrets Store binding that used to
 * hold a prompt answered with a 24,205-character value that took most of a turn's
 * twenty-second opening budget and was not this text, so the file is now the only
 * source and nothing can quietly substitute something else.
 */
export async function truthPromptInfo() {
  const text = BY_ID.get(DEFAULT_PRESET)?.system || '';
  return {
    source: 'code',
    version: text ? (await sha256Hex(text)).slice(0, 12) : null,
    chars: text.length,
  };
}

/** What the client is allowed to see: the presets a person can pick, no internal rung. */
export function publicPresets() {
  return PRESETS.filter((preset) => !preset.internal).map(({ id, name }) => ({ id, name }));
}

/** Presets bound to an OpenRouter preset, for /api/health diagnostics. */
export function openRouterBackedPresets() {
  return PRESETS.filter((p) => p.orPreset && !p.internal).map((p) => p.id);
}

import { b64FromBytes } from '../util.js';

const BASE = 'https://openrouter.ai/api/v1';

export const DEFAULT_MODEL = 'google/gemini-2.5-flash';
export const DEFAULT_STT_MODEL = 'openai/whisper-large-v3';
export const DEFAULT_TTS_MODEL = 'elevenlabs/eleven-flash-v2.5';

export class UpstreamError extends Error {
  constructor(status, body) {
    super(`OpenRouter ${status}: ${String(body).slice(0, 400)}`);
    this.status = 502;
    this.code = 'upstream_error';
    this.upstreamStatus = status;
  }
}

function headers(env) {
  return {
    authorization: `Bearer ${env.OPENROUTER_API_KEY}`,
    'content-type': 'application/json',
    'x-title': 'ai-Ncards',
    ...(env.APP_ORIGIN ? { 'http-referer': env.APP_ORIGIN } : {}),
  };
}

/**
 * A preset slug is referenced as `@preset/<slug>` — a bare slug is ignored by
 * OpenRouter, which would silently fall back to the plain model.
 */
export function modelFor(env, preset) {
  if (preset?.orPreset) return `@preset/${preset.orPreset}`;
  return preset?.or || env.OPENROUTER_MODEL || DEFAULT_MODEL;
}

/**
 * The model that answers when Cloudflare is switched off.
 *
 * `openrouter/free` is OpenRouter's own free router: it picks a free model per
 * request, so the app keeps answering when the daily neurons are gone instead
 * of repointing at one free model that may be withdrawn. A preset cannot be
 * used on this path — its prompt lives in the account and its model is the paid
 * one — so the local prompt travels with the request.
 */
export const FREE_MODEL = 'openrouter/free';

export function freeModelFor(env) {
  return env.OPENROUTER_FREE_MODEL || FREE_MODEL;
}

async function post(env, path, body) {
  const res = await fetch(`${BASE}${path}`, {
    method: 'POST',
    headers: headers(env),
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new UpstreamError(res.status, await res.text().catch(() => ''));
  return res;
}

export async function chat(env, { model, messages, temperature, maxTokens }) {
  const body = { model, messages, stream: true };
  if (temperature != null) body.temperature = temperature;
  if (maxTokens != null) body.max_tokens = maxTokens;
  return post(env, '/chat/completions', body);
}

export async function transcribe(env, { bytes, format = 'wav', model, language, verbose = false }) {
  const body = {
    model: model || env.OPENROUTER_STT_MODEL || DEFAULT_STT_MODEL,
    input_audio: { data: b64FromBytes(bytes), format },
    response_format: verbose ? 'verbose_json' : 'json',
  };
  if (language) body.language = language;
  const res = await post(env, '/audio/transcriptions', body);
  const data = await res.json();
  return data.text || '';
}

/**
 * response_format is mp3 or pcm and DEFAULTS TO PCM — omit it and the browser
 * receives headerless samples it cannot play.
 */
export async function speech(env, { text, voice, model, format = 'mp3' }) {
  const body = {
    model: model || env.OPENROUTER_TTS_MODEL || DEFAULT_TTS_MODEL,
    input: text,
    voice: voice || 'alloy',
    response_format: format,
  };
  const res = await post(env, '/audio/speech', body);
  return { body: res.body, contentType: format === 'mp3' ? 'audio/mpeg' : 'audio/pcm' };
}

/** Build an OpenRouter content-part array for a message carrying images. */
export function withImages(text, images) {
  if (!images.length) return text;
  return [{ type: 'text', text }, ...images.map((url) => ({ type: 'image_url', image_url: { url } }))];
}

import { bytesFromB64 } from '../util.js';

export const TEXT_MODEL = '@cf/google/gemma-4-26b-a4b-it';
export const ASR_MODEL = '@cf/openai/whisper-large-v3-turbo';
export const TTS_MODEL = '@cf/myshell-ai/melotts';
export const AURA_MODEL = '@cf/deepgram/aura-2-en';

/**
 * Workers AI has two image conventions on the binding, and picking the wrong
 * one sends an image the model never sees. Newer OpenAI-shaped models take a
 * content part; llama-3.2-vision and moondream take a top-level `image`.
 */
const OPENAI_SHAPED = new Set([
  '@cf/google/gemma-4-26b-a4b-it',
  '@cf/qwen/qwen3.8-27b',
  '@cf/meta/llama-4-scout-17b-16e-instruct',
  '@cf/mistralai/mistral-small-3.1-24b-instruct',
  '@cf/zai-org/glm-5.3-flash',
  '@cf/deepseek-ai/deepseek-v4.1-flash-1017',
]);

export function isOpenAIShaped(model) {
  return OPENAI_SHAPED.has(model);
}

export function buildPayload(model, { messages = [], temperature, maxTokens, images = [] } = {}) {
  const base = { messages: messages.map((m) => ({ role: m.role, content: m.content })) };
  if (temperature != null) base.temperature = temperature;
  if (maxTokens != null) base.max_tokens = maxTokens;
  if (!images.length) return base;

  if (isOpenAIShaped(model)) {
    const last = base.messages[base.messages.length - 1] || { role: 'user', content: '' };
    const text = typeof last.content === 'string' ? last.content : '';
    base.messages[base.messages.length - 1] = {
      role: last.role || 'user',
      content: [
        // Text first, then images — the documented order for these models.
        { type: 'text', text },
        ...images.map((url) => ({ type: 'image_url', image_url: { url } })),
      ],
    };
    return base;
  }

  base.image = images[0];
  return base;
}

export async function chat(env, opts) {
  const result = await env.AI.run(opts.model, buildPayload(opts.model, opts));
  // OpenAI-shaped models answer under choices[]; native ones under response.
  return (
    result?.response ??
    result?.result?.response ??
    result?.choices?.[0]?.message?.content ??
    result?.result?.choices?.[0]?.message?.content ??
    ''
  );
}

export async function streamChat(env, opts) {
  return env.AI.run(opts.model, { ...buildPayload(opts.model, opts), stream: true });
}

export async function transcribe(env, { audio, model = ASR_MODEL, initialPrompt, language }) {
  const body = { audio, task: 'transcribe' };
  if (initialPrompt) body.initial_prompt = initialPrompt;
  if (language) body.language = language;
  const result = await env.AI.run(model, body);
  return result?.text ?? '';
}

/**
 * melotts returns JSON {audio: base64 mp3}; aura returns a binary stream.
 * Voices are named "aura:<speaker>" so the client can offer them without
 * knowing which binding serves them.
 */
export async function speech(env, { text, voice, lang = 'en' }) {
  if (voice && voice.startsWith('aura:')) {
    const speaker = voice.slice(5) || 'luna';
    const raw = await env.AI.run(
      AURA_MODEL,
      { text, speaker, encoding: 'mp3', container: 'none' },
      { returnRawResponse: true },
    );
    return { body: raw.body, contentType: 'audio/mpeg' };
  }

  const result = await env.AI.run(TTS_MODEL, { prompt: text, lang });
  if (!result?.audio) throw new Error('melotts returned no audio');
  return { bytes: bytesFromB64(result.audio), contentType: 'audio/mpeg' };
}

/**
 * Login state, in a Durable Object.
 *
 * A Durable Object is the piece a Worker cannot do alone: one single-threaded
 * home per user, with storage that survives isolates and reads-after-writes.
 * One object per user name, so a session can be revoked for one account without
 * touching anybody else's, and two logins for the same name cannot race.
 *
 * The password is not per-user — it is the deployment's shared LOGIN_PASSWORD
 * secret, compared in constant time in `index.js`. The name is what the object
 * namespaces; adding real per-user passwords later means adding a member record
 * here and changing only the check, not the session plumbing.
 */

export const SESSION_COOKIE = 'mind_session';
export const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

const MAX_TTL_MS = 90 * 24 * 60 * 60 * 1000;

export const sessionsBinding = (env) => env?.SESSIONS || null;

export function sessionsFor(env, user) {
  const namespace = sessionsBinding(env);
  if (!namespace || typeof namespace.idFromName !== 'function') return null;
  return namespace.get(namespace.idFromName(String(user || '').trim().toLowerCase()));
}

/** base64url of the user name, then the random part: the token names its home. */
export function makeToken(user) {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  const random = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
  const name = btoa(encodeURIComponent(String(user || '').trim().toLowerCase()))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
  return `${name}.${random}`;
}

export function tokenUser(token) {
  const encoded = String(token || '').split('.')[0];
  if (!encoded) return null;
  try {
    const base64 = encoded.replace(/-/g, '+').replace(/_/g, '/');
    const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
    return decodeURIComponent(atob(padded));
  } catch {
    return null;
  }
}

async function call(stub, path, body) {
  const init =
    body === undefined
      ? { method: 'GET' }
      : {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        };
  const res = await stub.fetch(`https://sessions${path}`, init);
  const data = await res.json().catch(() => null);
  return { ok: res.ok, status: res.status, data };
}

export async function openSession(env, user, { ttl = SESSION_TTL_MS } = {}) {
  const stub = sessionsFor(env, user);
  if (!stub) return null;
  const token = makeToken(user);
  const out = await call(stub, '/login', { token, ttl });
  return out.ok ? out.data : null;
}

export async function readSession(env, token) {
  const user = tokenUser(token);
  if (!user) return null;
  const stub = sessionsFor(env, user);
  if (!stub) return null;
  const out = await call(stub, '/read', { token });
  return out.ok ? out.data : null;
}

export async function closeSession(env, token) {
  const user = tokenUser(token);
  if (!user) return null;
  const stub = sessionsFor(env, user);
  if (!stub) return null;
  const out = await call(stub, '/logout', { token });
  return out.ok;
}

const sessionKey = (token) => `session:${token}`;

export class Sessions {
  constructor(state, env) {
    this.state = state;
    this.env = env;
  }

  /** Expired sessions are pruned on write, so an idle account costs nothing. */
  async prune(now) {
    const all = await this.state.storage.list({ prefix: 'session:' });
    for (const [key, value] of all) {
      if (!value || !value.expiresAt || value.expiresAt <= now) {
        await this.state.storage.delete(key);
      }
    }
  }

  async fetch(request) {
    const url = new URL(request.url);
    const body = request.method === 'POST' ? await request.json().catch(() => ({})) : {};
    const token = String(body.token || '').trim();

    if (url.pathname === '/login') {
      if (!token) return jsonError(400, 'token_required');
      const now = Date.now();
      const ttl = Math.min(Math.max(Number(body.ttl) || SESSION_TTL_MS, 60000), MAX_TTL_MS);
      const expiresAt = now + ttl;
      await this.prune(now);
      await this.state.storage.put(sessionKey(token), { createdAt: now, expiresAt });
      return jsonOk({ token, expiresAt });
    }

    if (url.pathname === '/read') {
      const record = token ? await this.state.storage.get(sessionKey(token)) : null;
      if (!record || !record.expiresAt || record.expiresAt <= Date.now()) {
        if (token) await this.state.storage.delete(sessionKey(token));
        return jsonError(401, 'no_session');
      }
      return jsonOk({ expiresAt: record.expiresAt, createdAt: record.createdAt });
    }

    if (url.pathname === '/logout') {
      if (token) await this.state.storage.delete(sessionKey(token));
      return jsonOk({ ok: true });
    }

    return jsonError(404, 'not_found');
  }
}

function jsonOk(data) {
  return new Response(JSON.stringify(data), {
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
  });
}

function jsonError(status, code) {
  return new Response(JSON.stringify({ error: { code } }), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
  });
}

import puppeteer from '@cloudflare/puppeteer';
import { fail, sha256Hex } from './util.js';
import { objects, browserBinding } from './bindings.js';

/**
 * Screenshot a page with Browser Rendering.
 *
 * One request, one browser: launch it, shoot it, close it in `finally`, so a
 * navigation that fails or hangs cannot leak a browser session and keep spending
 * the account's browser seconds after the response is gone.
 *
 * Browser Rendering bills per browser-second, so this route stays cheap on
 * purpose: a hard navigation timeout, a JPEG at quality 80 rather than a PNG,
 * and no full-page capture unless asked. And because a card grid re-requests the
 * same image on every render, a capture is kept in the bucket for ten minutes —
 * after that the page may have changed, so it is shot again.
 */

const NAV_TIMEOUT_MS = 20000;
const MAX_URL_CHARS = 2000;
const JPEG_QUALITY = 80;
const FRESH_MS = 10 * 60 * 1000;

/**
 * Puppeteer opens 800x600, which makes every desktop page look like a phone
 * turned sideways. A real desktop viewport is the whole point of the shot.
 */
const VIEWPORT = { width: 1280, height: 800, deviceScaleFactor: 1 };

function imageResponse(body, { url, cache }) {
  return new Response(body, {
    headers: {
      'content-type': 'image/jpeg',
      // Long enough that one card grid costs one capture, short enough that a
      // page which changed since lunch is not shown as current.
      'cache-control': 'public, max-age=600',
      'access-control-allow-origin': '*',
      'x-screenshot-url': url,
      'x-screenshot-cache': cache,
    },
  });
}

/** R2 keys are flat and content-addressed, so the same page reuses its frame. */
async function cacheKey(href, fullPage) {
  return `shot/${await sha256Hex(`${href}|${fullPage ? 'full' : 'viewport'}`)}.jpg`;
}

export async function shot(url, env, ctx = {}) {
  const target = url.searchParams.get('url');

  if (!target) {
    return fail(400, 'url_required', 'Add ?url=https://example.com to take a screenshot.');
  }
  if (target.length > MAX_URL_CHARS) {
    return fail(400, 'url_too_long', `Keep the URL under ${MAX_URL_CHARS} characters.`);
  }

  let parsed;
  try {
    parsed = new URL(target);
  } catch {
    return fail(400, 'url_invalid', 'That is not a URL.');
  }
  // file:// and friends would let a caller read the browser's own disk, and
  // there is nothing this route could usefully return for them anyway.
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return fail(400, 'url_scheme', 'Only http and https URLs can be screenshotted.');
  }

  const fullPage = url.searchParams.get('full') === '1';
  const bucket = objects(env);
  const key = bucket ? await cacheKey(parsed.href, fullPage) : '';

  // A cached frame is served even when no browser is bound: the shot was already
  // paid for, and refusing it would help nobody.
  if (bucket) {
    try {
      const hit = await bucket.get(key);
      if (hit && Date.now() - new Date(hit.uploaded).getTime() < FRESH_MS) {
        return imageResponse(await hit.arrayBuffer(), { url: parsed.href, cache: 'hit' });
      }
    } catch {
      // A bucket that cannot be read must not cost the caller their screenshot.
    }
  }

  // BROWSER on this account; MYBROWSER is Cloudflare's docs name for the same
  // binding. ABROWSER is deliberately not consulted — that one is a service.
  const browser = browserBinding(env);
  if (!browser) {
    return fail(
      501,
      'browser_unbound',
      'Add the Browser Rendering binding (BROWSER) to wrangler.jsonc and deploy again.',
    );
  }

  let session = null;
  try {
    session = await puppeteer.launch(browser);
    const page = await session.newPage();
    await page.setViewport(VIEWPORT);
    await page.goto(parsed.href, { waitUntil: 'domcontentloaded', timeout: NAV_TIMEOUT_MS });
    const img = await page.screenshot({ type: 'jpeg', quality: JPEG_QUALITY, fullPage });

    if (bucket) {
      // Storing must not delay or fail the answer the caller already has.
      const store = bucket
        .put(key, img, {
          httpMetadata: { contentType: 'image/jpeg' },
          customMetadata: { url: parsed.href, full: fullPage ? '1' : '0' },
        })
        .catch(() => {});
      if (typeof ctx?.waitUntil === 'function') ctx.waitUntil(store);
      else await store;
    }

    return imageResponse(img, { url: parsed.href, cache: 'miss' });
  } catch (err) {
    // The page's own failure (DNS, cert, timeout) is a 502, not a 500: the
    // worker is fine, the thing it was asked to look at is not.
    return fail(502, 'screenshot_failed', err?.message || String(err), { url: parsed.href });
  } finally {
    if (session) await session.close().catch(() => {});
  }
}

import { stateKv, masterKv, truthService } from './bindings.js';
import { sha256Hex } from './util.js';

/**
 * Truth layers, in the order a query resolves:
 *
 *   master       promoted by hand; answers without a model at all
 *   provisional  promoted, but not yet blessed as the final answer
 *   candidate    every answer the pipeline produced, kept for promotion
 *
 * The hit formula is deliberately blunt: case, spacing and trailing punctuation
 * must not split one question into two records, and nothing else is rewritten.
 * A fuzzy match here would promote the wrong answer, which is worse than a miss.
 */

/** How many times one answer must recur before promotion is suggested. */
export const PROMOTE_AT = 3;

/** Thirty days: long enough to review a session, short enough to stay small. */
const TTL = 60 * 60 * 24 * 30;

const MAX_INPUT = 500;
const MAX_ANSWER = 20000;

export function truthKey(input) {
  return String(input || '')
    .toLowerCase()
    .replace(/[‘’“”]/g, "'")
    .replace(/\s+/g, ' ')
    .replace(/[?!.,;:'"()[\]{}]+/g, '')
    .trim()
    .slice(0, MAX_INPUT);
}

/**
 * The question inside a message, not the prompt that carries it.
 *
 * The client sends its whole base prompt in the user turn —
 * `SYSTEM_PROMPT_BASE + "\n\nUser: " + prompt` — so the raw content is a page of
 * instructions followed by one question. Keying a cache or a curated pair on that
 * blob can never match `ranger1185`, which is why a stored answer read as a miss.
 */
export function questionOf(content) {
  let text = String(content || '');
  for (const marker of ['\n\nUser: ', 'User Instruction: ', '\nUser: ']) {
    const at = text.lastIndexOf(marker);
    if (at !== -1) {
      text = text.slice(at + marker.length);
      break;
    }
  }
  return text.trim();
}

export async function truthId(input) {
  const query = truthKey(input);
  return query ? sha256Hex(query) : null;
}

export const candidateKey = (id) => `candidate:${id}`;
export const truthKeyOf = (layer, id) => `truth:${layer}:${id}`;

/** KV keys cap at 512 bytes, so a plain-text key stops well short of that. */
const MAX_TEXT_KEY = 240;

/** How many different answers to keep beside the first stored one. */
const MAX_ALTERNATIVES = 3;

/** How much of a namespace the search path may look through. */
const TRUTH_SCAN_LIMIT = 500;
const TRUTH_SCAN_READS = 30;

/** Keys this app writes itself. None of them is a stored truth. */
const INTERNAL_PREFIXES = ['candidate:', 'style:', 'decision:', 'review:', 'budget:', 'tts:', 'upload:', 'obj:', 'index:'];

/** Queries that already proved empty in this isolate, so a miss scans once. */
const SCAN_MISSES = new Set();

/**
 * A stored truth is a truth whatever wrote it. These are the shapes a pair saved
 * before this layout — or by a separate admin page — may live under.
 */
export function legacyTruthKeys(layer, id, query) {
  const text = String(query || '').slice(0, MAX_TEXT_KEY);
  const names = layer === 'master' ? ['master'] : ['provisional'];
  const keys = [];
  for (const name of names) {
    keys.push(`${name}:${id}`, `truth:${name}:${text}`, `${name}:${text}`);
  }
  keys.push(`truth:${id}`, `truth:${text}`);
  return keys;
}

/**
 * Stored pairs are not always this file's shape: a hand-written admin may have
 * saved the answer as `html`, `text`, `content` or a bare string.
 */
/** How a store admits it cut the value it kept. Such a record is not an answer. */
const CLIPPED = /\{\s*truncated\s*\}|\[\s*truncated\b[^\]]*\]/i;

function answerOf(value) {
  const text =
    typeof value === 'string'
      ? value
      : value && typeof value === 'object'
        ? ['answer', 'html', 'text', 'content', 'body', 'response', 'truth']
            .map((field) => value[field])
            .find((raw) => typeof raw === 'string' && raw.trim()) || ''
        : '';
  const trimmed = text.trim();
  if (!trimmed) return null;
  // A clipped copy would be served as if it were the whole answer, which is
  // exactly what a half-finished report looks like. Miss instead, and generate.
  return CLIPPED.test(trimmed) ? null : trimmed;
}

function citationsOf(value) {
  const raw = Array.isArray(value?.citations)
    ? value.citations
    : Array.isArray(value?.meta?.citations)
      ? value.meta.citations
      : [];
  return raw.filter((c) => c && typeof c === 'object' && c.url).slice(0, 4);
}

function parseRecord(raw) {
  try {
    return JSON.parse(raw);
  } catch {
    return raw; // a bare string value is the answer itself
  }
}

/**
 * What a record says it is. This app writes `layer`; a sibling that shares the
 * namespace writes `status`. Nothing declared is an older record of this app's
 * own shape, which the key it sits at already identifies.
 */
function declaredLayerOf(fields) {
  const record = fields && typeof fields === 'object' ? fields : {};
  if (typeof record.layer === 'string') return record.layer.toLowerCase();
  if (typeof record.status === 'string') return record.status.toLowerCase();
  return null;
}

/** A record that declares another layer is not a master, whatever key it sits at. */
function isMasterRecord(hit) {
  return hit?.declares == null || hit.declares === 'master';
}

/** One read, whatever shape the record is in. A tombstone or review blob is a miss. */
async function readTruth(store, key, layer, id, query) {
  if (!store || typeof store.get !== 'function') return null;
  const raw = await store.get(key).catch(() => null);
  if (!raw) return null;
  const parsed = parseRecord(raw);
  const answer = answerOf(parsed);
  if (!answer) return null;
  const fields = parsed && typeof parsed === 'object' ? parsed : {};
  const declared =
    typeof fields.query === 'string'
      ? fields.query
      : typeof fields.input === 'string'
        ? fields.input
        : null;
  return {
    ...fields,
    layer,
    id,
    query: declared || query,
    declared,
    declares: declaredLayerOf(fields),
    answer,
    citations: citationsOf(parsed),
    key,
  };
}

/** Does the record say it is about this query? A key made of a slug needs this. */
function answersQuery(record, query) {
  for (const field of ['declared', 'question', 'prompt', 'name']) {
    const value = record?.[field];
    if (typeof value === 'string' && truthKey(value) === query) return true;
  }
  return false;
}

/**
 * An opaque key — `ranger1189` — cannot be derived from the query, so the record
 * has to be found by what it says about itself. Bounded, and only reached on a
 * miss, with the miss remembered so the same question does not scan twice.
 */
async function scanForTruth(stores, { id, query }) {
  if (SCAN_MISSES.has(query)) return null;

  for (const store of stores) {
    if (!store || typeof store.list !== 'function') continue;
    const listed = await store.list({ limit: TRUTH_SCAN_LIMIT }).catch(() => null);
    const names = (listed?.keys || [])
      .map((entry) => entry?.name)
      .filter((name) => typeof name === 'string' && !INTERNAL_PREFIXES.some((prefix) => name.startsWith(prefix)))
      .slice(0, TRUTH_SCAN_READS);
    if (!names.length) continue;

    const found = await Promise.all(
      names.map(async (name) => {
        const hit = await readTruth(store, name, 'master', id, query);
        if (!hit) return null;
        if (!answersQuery(hit, query) && hit.key !== query) return null;
        // These namespaces are shared with a writer whose candidates are not
        // truths. Only a record that says it is master is served as one.
        if (hit.declares !== 'master') return null;
        return { ...hit, scanned: true };
      }),
    );
    const match = found.find(Boolean);
    if (match) return match;
  }

  if (SCAN_MISSES.size > 200) SCAN_MISSES.clear();
  SCAN_MISSES.add(query);
  return null;
}

/**
 * Conflict traffic goes to a different Worker, which keeps the list. Two
 * transports because a deploy may only have one: a service binding when it
 * exists, an explicit URL when it does not. Unconfigured is silent — the stored
 * answer still stands, only the notice is missing.
 */
export function reportConflict(env, ctx, payload) {
  const trim = (value) => (typeof value === 'string' ? value.slice(0, 1000) : (value ?? null));
  const notice = {
    service: 'mind',
    ...payload,
    existing: trim(payload?.existing),
    incoming: trim(payload?.incoming),
    at: payload?.at || new Date().toISOString(),
  };
  const body = JSON.stringify(notice);
  const headers = { 'content-type': 'application/json' };

  let send = null;
  const binding = env?.ALERTS;
  if (binding && typeof binding.fetch === 'function') {
    send = () => binding.fetch(new Request('https://alerts/', { method: 'POST', headers, body }));
  } else if (typeof env?.TRUTH_ALERTS_URL === 'string' && env.TRUTH_ALERTS_URL) {
    const url = env.TRUTH_ALERTS_URL;
    send = () => fetch(url, { method: 'POST', headers, body });
  }
  if (!send) return null;

  const promise = Promise.resolve()
    .then(send)
    .then((res) => Boolean(res?.ok), () => false);
  if (ctx?.waitUntil) ctx.waitUntil(promise);
  return promise;
}

function bad(status, code, message) {
  return Object.assign(new Error(message), { status, code });
}

/**
 * A bound service that stops answering must not hold the turn open — but their
 * resolve is resolve-or-create: on a miss it generates and stores a provisional
 * before answering, so this cap has to sit above a PROXY round trip, not below it.
 */
const REMOTE_TIMEOUT_MS = 12000;

/** One extra attempt at step 0; a clean miss is final and is not retried. */
const REMOTE_RETRIES = 1;
const RETRY_DELAY_MS = 250;

/**
 * The truth worker, when bound as TRUTH, is the store the standalone admin writes
 * to — the binding exposes the very routes the page calls, so the first cache
 * check asks it the same question instead of guessing at key shapes.
 *
 * It is read-only from here. An answer generated for a question it did not have
 * is kept as a candidate, so a curated pair is never written over.
 */
async function resolveRemoteTruth(env, input, { id, query }) {
  const binding = truthService(env);
  if (!binding || typeof binding.fetch !== 'function') return null;

  const signalFor = () =>
    typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function'
      ? AbortSignal.timeout(REMOTE_TIMEOUT_MS)
      : undefined;

  // Step 0 gets a second chance. A service is cold on the first request after a
  // deploy, and a timeout can leave the far side holding an answer it already
  // wrote; one retry costs a quarter second and saves the turn its curated pair.
  // A clean `miss` is not retried — that would pay for a second generation.
  for (let attempt = 0; attempt <= REMOTE_RETRIES; attempt += 1) {
    if (attempt) await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));

    try {
      const res = await binding.fetch(
        new Request('https://truth/api/truth/resolve', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ input }),
          signal: signalFor(),
        }),
      );

      // A server error may be transient; try once more before giving up.
      if (!res.ok) continue;

      const data = await res.json().catch(() => null);
      // A miss is a 200 with status "miss", layer "none" and a null answer.
      if (data && data.status === 'miss') return null;

      // "none" is the console's own miss: let the local layers answer instead.
      const answer = answerOf(data);
      const layer = data?.layer === 'master' ? 'master' : data?.layer === 'provisional' ? 'provisional' : null;
      if (!answer || !layer) continue;

      // Provenance: a provisional written seconds ago is not the same thing as
      // one he wrote before, and not the same as master. The record says which.
      const created = Number(data?.meta?.created) || null;
      return {
        layer,
        id: typeof data?.id === 'string' && data.id ? data.id : id,
        query,
        answer,
        origin: {
          source: data?.source || null,
          verified: data?.verified === true,
          created,
          fresh: created ? Date.now() - created < 120000 : false,
        },
        citations: citationsOf(data),
        source: 'truth-service',
        key: 'service:truth',
      };
    } catch {
      // Network error or timeout: fall through to the retry.
    }
  }

  return null; // bound but unreachable is a miss, never a failed turn
}

/**
 * Master, then provisional, then the candidate worth promoting. A miss is a
 * normal answer, not an error: it just means the pipeline has to generate.
 *
 * The canonical keys are read first, one round trip. Only when they all miss does
 * the search path run: the shapes an older writer used, the key name itself (an
 * opaque slug like `ranger1189` is the query), then a bounded scan for a record
 * that says which question it answers. A stored pair is found, never answered
 * over — that is the whole point of the first cache check.
 */
export async function resolveTruth(env, input) {
  const mem = stateKv(env);
  const master = masterKv(env);
  const remote = truthService(env);
  const query = truthKey(input);
  const stores = [master, mem].filter((store, index, all) => store && all.indexOf(store) === index);

  if (!stores.length && !remote) return { layer: 'none', query, reason: 'unbound' };
  if (!query) return { layer: 'none', query, reason: 'empty' };

  const id = await sha256Hex(query);
  const raw = String(input || '').trim();

  // The admin's store answers first: it is the one place a pair is written by
  // hand, so it outranks anything this app cached for itself.
  const curated = await resolveRemoteTruth(env, raw || query, { id, query });
  if (curated) return curated;
  const canonical = [truthKeyOf('master', id), truthKeyOf('provisional', id), candidateKey(id)];

  const reads = [];
  for (const store of stores) {
    reads.push(readTruth(store, canonical[0], 'master', id, query));
    reads.push(readTruth(store, canonical[1], 'provisional', id, query));
    reads.push(readTruth(store, canonical[2], 'candidate', id, query));
  }
  const hits = await Promise.all(reads);

  // Layer beats store: a master anywhere outranks a provisional anywhere.
  const masterHit = hits.find((hit) => hit && hit.layer === 'master');
  if (masterHit) return masterHit;
  const provisionalHit = hits.find((hit) => hit && hit.layer === 'provisional');
  if (provisionalHit) return provisionalHit;
  const candidateHit = hits.find((hit) => hit && hit.layer === 'candidate');
  if (candidateHit) return candidateHit;

  const pairs = [];
  const seen = new Set(canonical);
  const add = (store, keys, layer) => {
    for (const key of keys) {
      if (!store || seen.has(key)) continue;
      seen.add(key);
      pairs.push([store, key, layer]);
    }
  };

  for (const store of stores) {
    add(store, legacyTruthKeys('master', id, query), 'master');
    add(store, [query, raw].filter(Boolean), 'master');
  }
  for (const store of stores) {
    add(store, legacyTruthKeys('provisional', id, query), 'provisional');
  }

  const swept = await Promise.all(
    pairs.map(([store, key, layer]) => readTruth(store, key, layer, id, query)),
  );
  const sweptMaster = swept.find((hit) => hit && hit.layer === 'master' && isMasterRecord(hit));
  if (sweptMaster) return sweptMaster;
  const sweptProvisional = swept.find((hit) => hit && hit.layer === 'provisional');
  if (sweptProvisional) return sweptProvisional;

  const scanned = await scanForTruth(stores, { id, query });
  if (scanned) return scanned;

  return { layer: 'none', id, query };
}

/**
 * Every generated answer lands here, so nothing the pipeline said is lost before
 * someone decides whether it is the truth. `hits` counts how many times the same
 * normalized question was answered — the only signal distinguishing a recurring
 * question from a one-off, and the thing promotion is based on.
 *
 * The first stored answer is never replaced. A different answer is kept beside it
 * as an alternative and reported as a conflict: choosing between two answers is
 * an edit, and edits belong in the admin, not in the cache.
 */
export async function recordCandidate(env, { input, answer, preset, route, model }, ctx) {
  const kv = stateKv(env);
  const query = truthKey(input);
  const text = String(answer || '').trim();
  if (!kv || !query || !text) return null;

  const id = await sha256Hex(query);
  const key = candidateKey(id);
  const now = new Date().toISOString();

  let previous = null;
  try {
    previous = JSON.parse((await kv.get(key)) || 'null');
  } catch {
    previous = null;
  }

  const stored = typeof previous?.answer === 'string' ? previous.answer.trim() : '';
  const same = !stored || stored === text;
  const alternatives = Array.isArray(previous?.alternatives) ? [...previous.alternatives] : [];

  if (!same) {
    const known = alternatives.find((entry) => entry?.answer === text);
    if (known) known.count = (known.count || 1) + 1;
    else if (alternatives.length < MAX_ALTERNATIVES) {
      alternatives.push({ answer: text.slice(0, MAX_ANSWER), count: 1, at: now, model: model || null });
    }
  }

  const hits = (previous?.hits || 0) + 1;
  const record = {
    layer: 'candidate',
    id,
    query,
    input: String(input).slice(0, MAX_INPUT),
    answer: (stored || text).slice(0, MAX_ANSWER),
    hits,
    ...(alternatives.length ? { alternatives } : {}),
    firstAt: previous?.firstAt || now,
    lastAt: now,
    preset: preset || null,
    route: route || null,
    model: model || null,
    suggested: hits >= PROMOTE_AT,
  };

  try {
    await kv.put(key, JSON.stringify(record), { expirationTtl: TTL });
  } catch {
    return record;
  }

  if (!same) {
    reportConflict(env, ctx, {
      type: 'candidate_divergence',
      query,
      id,
      key,
      layer: 'candidate',
      existing: stored,
      incoming: text,
      route: route || null,
      model: model || null,
      at: now,
    });
  }

  return record;
}

/**
 * The confidence an answer reports about itself. This reads the model's own
 * number and clamps it; nothing here judges an answer.
 */
export function confidenceOf(text) {
  const match = String(text || '').match(/confidence\s*[:=]\s*(\d{1,3}(?:\.\d+)?)\s*%?/i);
  if (!match) return null;
  let value = Number(match[1]);
  if (!Number.isFinite(value)) return null;
  // 0.82 and 82% are the same statement.
  if (value <= 1 && match[1].includes('.')) value *= 100;
  return Math.max(0, Math.min(100, Math.round(value)));
}

export const styleKey = (id) => `style:${id}`;

/**
 * A style answer is generated every time, never served, so it is not a cache.
 * It is kept so the population follows the palette: the stored answer is
 * replaced only when the new one reports a higher confidence, and the one that
 * lost stays beside it with its own number. Both are always logged, and the
 * number compared is the model's own — this file computes no score.
 */
export async function recordStyleCandidate(env, { input, answer, confidence, preset, route, model }) {
  const kv = stateKv(env);
  const query = truthKey(input);
  const text = String(answer || '').trim();
  if (!kv || !query || !text) return null;

  const id = await sha256Hex(query);
  const key = styleKey(id);
  const now = new Date().toISOString();

  let previous = null;
  try {
    previous = JSON.parse((await kv.get(key)) || 'null');
  } catch {
    previous = null;
  }

  const stored = typeof previous?.answer === 'string' ? previous.answer.trim() : '';
  const storedConfidence = typeof previous?.confidence === 'number' ? previous.confidence : null;
  const incoming = typeof confidence === 'number' ? confidence : null;
  const alternatives = Array.isArray(previous?.alternatives) ? [...previous.alternatives] : [];

  let answerKept = text;
  let confidenceKept = incoming;
  let modelKept = model || null;

  if (!stored) {
    // The first palette is the stored one: there is nothing to compare against.
  } else if (stored === text) {
    answerKept = stored;
    confidenceKept =
      incoming != null && (storedConfidence == null || incoming > storedConfidence)
        ? incoming
        : storedConfidence;
    modelKept = previous?.model || model || null;
  } else {
    // Better is the higher reported confidence. An unstated one is never better
    // than a stated one, so a silent model cannot replace a numbered palette.
    const better = incoming != null && (storedConfidence == null || incoming > storedConfidence);
    const loser = better ? stored : text;
    const loserConfidence = better ? storedConfidence : incoming;
    answerKept = better ? text : stored;
    confidenceKept = better ? incoming : storedConfidence;
    modelKept = better ? model || null : previous?.model || null;

    const known = alternatives.find((entry) => entry?.answer === loser);
    if (known) known.count = (known.count || 1) + 1;
    else if (alternatives.length < MAX_ALTERNATIVES) {
      alternatives.push({
        answer: loser.slice(0, MAX_ANSWER),
        confidence: loserConfidence,
        count: 1,
        at: now,
        model: better ? previous?.model || null : model || null,
      });
    }
  }

  const record = {
    layer: 'candidate',
    kind: 'style',
    id,
    query,
    input: String(input).slice(0, MAX_INPUT),
    answer: answerKept.slice(0, MAX_ANSWER),
    confidence: confidenceKept,
    attempts: (previous?.attempts || 0) + 1,
    ...(alternatives.length ? { alternatives } : {}),
    firstAt: previous?.firstAt || now,
    lastAt: now,
    preset: preset || null,
    route: route || null,
    model: modelKept,
  };

  try {
    await kv.put(key, JSON.stringify(record), { expirationTtl: TTL });
  } catch {
    return record;
  }
  return record;
}

/**
 * The style population, newest first. One record per question: the palette that
 * is kept, and every answer it beat or lost to, so both can be read side by side.
 */
export async function listStyleCandidates(env, { limit = 40 } = {}) {
  const kv = stateKv(env);
  if (!kv || typeof kv.list !== 'function') return [];

  const listed = await kv.list({ prefix: 'style:', limit }).catch(() => null);
  const keys = listed?.keys || [];
  const out = [];

  for (const entry of keys) {
    const raw = await kv.get(entry.name).catch(() => null);
    if (!raw) continue;
    try {
      out.push(JSON.parse(raw));
    } catch {
      /* skip a corrupt record */
    }
  }

  return out.sort((a, b) => String(b.lastAt || '').localeCompare(String(a.lastAt || '')));
}

/**
 * Promote a candidate, or save an edit of one, into a truth layer.
 *
 * Master records carry no expiry: a hand-curated answer that vanishes after
 * thirty days is a bug, not housekeeping. An existing record is not replaced
 * unless `overwrite` is passed — the call reports the clash and leaves both
 * versions alone, so the difference is settled by hand instead of by whichever
 * write came last.
 */
export async function promote(
  env,
  { input, answer, layer = 'master', editor = 'admin', citations = [], overwrite = false },
  ctx,
) {
  const kv = stateKv(env);
  if (!kv) throw bad(503, 'no_store', 'MEM is not bound, so a truth cannot be stored.');
  if (layer !== 'master' && layer !== 'provisional') {
    throw bad(400, 'bad_layer', 'layer must be "master" or "provisional".');
  }

  const query = truthKey(input);
  if (!query) throw bad(400, 'query_required', 'A query is required.');
  const text = String(answer || '').trim();
  if (!text) throw bad(400, 'answer_required', 'An answer is required.');

  const id = await sha256Hex(query);
  const now = new Date().toISOString();
  const key = truthKeyOf(layer, id);
  const store = layer === 'master' ? masterKv(env) : kv;
  const existing = await readTruth(store, key, layer, id, query);

  if (existing && !overwrite && existing.answer.trim() !== text) {
    reportConflict(env, ctx, {
      type: 'promote_conflict',
      query,
      id,
      key,
      layer,
      existing: existing.answer,
      incoming: text,
      at: now,
    });
    return {
      saved: false,
      conflict: true,
      layer,
      id,
      key,
      existing: { layer: existing.layer, answer: existing.answer },
    };
  }

  const record = {
    layer,
    id,
    query,
    input: String(input).slice(0, MAX_INPUT),
    answer: text.slice(0, MAX_ANSWER),
    editor: String(editor || 'admin').slice(0, 80),
    citations: (Array.isArray(citations) ? citations : [])
      .filter((c) => c && c.title && c.url)
      .slice(0, 4)
      .map((c) => ({ title: String(c.title).slice(0, 200), url: String(c.url).slice(0, 500) })),
    promotedAt: existing?.promotedAt || now,
    updatedAt: now,
  };

  if (layer === 'master') await store.put(key, JSON.stringify(record));
  else await store.put(key, JSON.stringify(record), { expirationTtl: TTL });

  // The provisional is left alone: master wins by precedence, and a stored pair
  // is never deleted just to make room for another one.
  return { ...record, saved: true, conflict: false };
}

/** The review queue: candidates by hits, so recurring questions surface first. */
export async function listCandidates(env, { limit = 40 } = {}) {
  const kv = stateKv(env);
  if (!kv) return [];

  const listed = await kv.list({ prefix: 'candidate:', limit }).catch(() => null);
  const keys = listed?.keys || [];
  const out = [];

  for (const entry of keys) {
    const raw = await kv.get(entry.name).catch(() => null);
    if (!raw) continue;
    try {
      out.push(JSON.parse(raw));
    } catch {
      /* skip a corrupt record */
    }
  }

  return out.sort((a, b) => (b.hits || 0) - (a.hits || 0));
}

/**
 * What is already stored for this ask, read from KV only. No service call and no
 * generation: this is the pair she is shown before she decides, so a stored
 * non-answer can be judged before anything is written.
 */
export async function peekTruth(env, input) {
  const mem = stateKv(env);
  const master = masterKv(env);
  const query = truthKey(input);
  if (!query) return null;

  const stores = [master, mem].filter((store, index, all) => store && all.indexOf(store) === index);
  if (!stores.length) return null;

  const id = await sha256Hex(query);
  const layers = ['master', 'provisional', 'candidate'];
  const keys = [truthKeyOf('master', id), truthKeyOf('provisional', id), candidateKey(id)];

  const reads = [];
  for (const store of stores) keys.forEach((key, i) => reads.push(readTruth(store, key, layers[i], id, query)));
  const hits = (await Promise.all(reads)).filter(Boolean);

  for (const layer of layers) {
    const hit = hits.find((entry) => entry.layer === layer);
    if (hit) return { layer: hit.layer, answer: hit.answer, id: hit.id, key: hit.key || null };
  }
  return null;
}

const encoder = new TextEncoder();

export const has = (env, key) => Boolean(env && env[key]);

export function json(data, init = {}) {
  return new Response(JSON.stringify(data, null, 2), {
    ...init,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      'access-control-allow-origin': '*',
      ...(init.headers || {}),
    },
  });
}

export function fail(status, code, message, extra = {}) {
  return json({ error: { code, message, ...extra } }, { status });
}

export function options() {
  return new Response(null, {
    status: 204,
    headers: {
      'access-control-allow-origin': '*',
      'access-control-allow-methods': 'GET, POST, OPTIONS',
      'access-control-allow-headers': 'content-type, authorization',
      'access-control-max-age': '86400',
    },
  });
}

/** base64 without blowing the argument limit on multi-megabyte audio. */
export function b64FromBytes(bytes) {
  let binary = '';
  const SLICE = 0x8000;
  for (let i = 0; i < bytes.length; i += SLICE) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + SLICE));
  }
  return btoa(binary);
}

export function bytesFromB64(b64) {
  const binary = atob(String(b64 || ''));
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}

export async function sha256Hex(input) {
  const data = typeof input === 'string' ? encoder.encode(input) : input;
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

export function clientIp(request) {
  return (
    request.headers.get('cf-connecting-ip') ||
    (request.headers.get('x-forwarded-for') || '').split(',')[0].trim() ||
    'anon'
  );
}

export const utcDay = () => new Date().toISOString().slice(0, 10);

/**
 * Compare a presented key with the configured one without leaking where they
 * diverge. Length is compared up front, which only reveals a length.
 */
export function keyMatches(expected, provided) {
  const a = String(expected || '');
  const b = String(provided || '');
  if (!a || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i += 1) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
